import sys

def solve(s: str) -> int:
    floor = 0
    for c in s.strip():
        if c == '(':
            floor += 1
        elif c == ')':
            floor -= 1
    return floor

if __name__ == "__main__":
    s = sys.stdin.readline().rstrip("\n")
    print(solve(s))

