import sys

def first_basement_position(s: str) -> int:
    floor = 0
    for i, c in enumerate(s):
        if c == '(':
            floor += 1
        elif c == ')':
            floor -= 1
        if floor == -1:
            return i + 1  # convert 0-based index to 1-based position
    return -1  # should not happen for valid inputs

def main():
    s = sys.stdin.readline().rstrip('\n')
    print(first_basement_position(s))

if __name__ == "__main__":
    main()

