import sys

def count_nice(strings):
    vowels = set("aeiou")
    forbidden = {"ab", "cd", "pq", "xy"}

    nice_count = 0
    for s in strings:
        vowel_count = 0
        has_double = False
        has_forbidden = False

        for i, ch in enumerate(s):
            if ch in vowels:
                vowel_count += 1
            if i > 0 and s[i] == s[i - 1]:
                has_double = True
            if i > 0 and (s[i - 1] + s[i]) in forbidden:
                has_forbidden = True

        if vowel_count >= 3 and has_double and not has_forbidden:
            nice_count += 1

    return nice_count

def main():
    lines = [line.strip() for line in sys.stdin.read().splitlines() if line.strip() != ""]
    if not lines:
        print(0)
        return
    print(count_nice(lines))

if __name__ == "__main__":
    main()

