import sys

def solve():
    lines = [line.strip() for line in sys.stdin.read().splitlines() if line.strip()]
    if not lines:
        print(0)
        return

    # Brightness grid for Part Two: 1000x1000, all start at 0
    brightness = [[0] * 1000 for _ in range(1000)]

    for line in lines:
        if line.startswith("turn on"):
            op = "on"
            rest = line[len("turn on "):]
        elif line.startswith("turn off"):
            op = "off"
            rest = line[len("turn off "):]
        else:
            op = "toggle"
            rest = line[len("toggle "):]

        left, right = rest.split(" through ")
        x1_str, y1_str = left.split(",")
        x2_str, y2_str = right.split(",")

        x1, y1 = int(x1_str), int(y1_str)
        x2, y2 = int(x2_str), int(y2_str)

        x_min, x_max = (x1, x2) if x1 <= x2 else (x2, x1)
        y_min, y_max = (y1, y2) if y1 <= y2 else (y2, y1)

        for x in range(x_min, x_max + 1):
            row = brightness[x]
            if op == "on":
                for y in range(y_min, y_max + 1):
                    row[y] += 1
            elif op == "off":
                for y in range(y_min, y_max + 1):
                    v = row[y] - 1
                    row[y] = v if v > 0 else 0
            else:  # toggle
                for y in range(y_min, y_max + 1):
                    row[y] += 2

    total = 0
    for x in range(1000):
        total += sum(brightness[x])

    print(total)

if __name__ == "__main__":
    solve()

