import sys
from functools import lru_cache

MASK = 0xFFFF

def parse_operand(tok: str):
    tok = tok.strip()
    if tok.isdigit():
        return int(tok)
    return tok  # wire name

def main():
    instr = {}  # destination wire -> parsed instruction tuple

    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        lhs, out = map(str.strip, line.split("->"))
        tokens = lhs.split()

        if len(tokens) == 1:
            # ASSIGN: x -> y  OR  123 -> y
            instr[out] = ("ASSIGN", parse_operand(tokens[0]))
        elif len(tokens) == 2 and tokens[0] == "NOT":
            # NOT x -> y
            instr[out] = ("NOT", parse_operand(tokens[1]))
        elif len(tokens) == 3:
            a, op, b = tokens
            if op == "AND":
                instr[out] = ("AND", parse_operand(a), parse_operand(b))
            elif op == "OR":
                instr[out] = ("OR", parse_operand(a), parse_operand(b))
            elif op == "LSHIFT":
                instr[out] = ("LSHIFT", parse_operand(a), parse_operand(b))
            elif op == "RSHIFT":
                instr[out] = ("RSHIFT", parse_operand(a), parse_operand(b))
            else:
                raise ValueError(f"Unknown operator: {op}")
        else:
            raise ValueError(f"Cannot parse instruction: {line}")

    @lru_cache(maxsize=None)
    def value(wire_or_int):
        # If it's an int literal, return it masked.
        if isinstance(wire_or_int, int):
            return wire_or_int & MASK

        # Otherwise it's a wire name.
        w = wire_or_int
        op = instr[w][0]

        if op == "ASSIGN":
            return value(instr[w][1]) & MASK
        if op == "NOT":
            return (~value(instr[w][1])) & MASK
        if op == "AND":
            return (value(instr[w][1]) & value(instr[w][2])) & MASK
        if op == "OR":
            return (value(instr[w][1]) | value(instr[w][2])) & MASK
        if op == "LSHIFT":
            return (value(instr[w][1]) << value(instr[w][2])) & MASK
        if op == "RSHIFT":
            return (value(instr[w][1]) >> value(instr[w][2])) & MASK

        raise ValueError(f"Unknown instruction type: {op}")

    # Problem asks for signal ultimately provided to wire 'a'
    print(value("a") & MASK)

if __name__ == "__main__":
    main()

