import sys
from typing import Dict, Tuple, Union

Expr = Tuple[str, Union[str, int, None], Union[str, int, None], Union[int, None]]

MASK = 0xFFFF

def solve() -> None:
    lines = [line.strip() for line in sys.stdin.read().splitlines() if line.strip()]
    expr_by_wire: Dict[str, Expr] = {}

    def is_int(tok: str) -> bool:
        return tok.isdigit()

    for line in lines:
        parts = line.split()
        # Patterns:
        # 1) "x -> y"
        # 2) "x AND y -> z"
        # 3) "x OR y -> z"
        # 4) "x LSHIFT k -> z"
        # 5) "x RSHIFT k -> z"
        # 6) "NOT x -> y"
        if len(parts) == 3 and parts[1] == "->":
            src, _, dst = parts
            expr_by_wire[dst] = ("ASSIGN", src, None, None)
        elif len(parts) == 4 and parts[0] == "NOT" and parts[2] == "->":
            _, x, _, dst = parts
            expr_by_wire[dst] = ("NOT", x, None, None)
        elif len(parts) == 5 and parts[3] == "->":
            x, op, y, _, dst = parts
            if op == "AND":
                expr_by_wire[dst] = ("AND", x, y, None)
            elif op == "OR":
                expr_by_wire[dst] = ("OR", x, y, None)
            elif op == "LSHIFT":
                expr_by_wire[dst] = ("LSHIFT", x, y, None)  # y is shift amount token
            elif op == "RSHIFT":
                expr_by_wire[dst] = ("RSHIFT", x, y, None)  # y is shift amount token
            else:
                raise ValueError(f"Unknown op: {op}")
        else:
            raise ValueError(f"Unrecognized instruction: {line}")

    def eval_token(token: Union[str, int], cache: Dict[str, int]) -> int:
        if isinstance(token, int):
            return token & MASK
        if is_int(token):
            return int(token) & MASK
        if token in cache:
            return cache[token]
        expr = expr_by_wire[token]
        kind = expr[0]

        if kind == "ASSIGN":
            src = expr[1]
            val = eval_token(src, cache)
        elif kind == "NOT":
            x = expr[1]
            val = (~eval_token(x, cache)) & MASK
        elif kind == "AND":
            x, y = expr[1], expr[2]
            val = (eval_token(x, cache) & eval_token(y, cache)) & MASK
        elif kind == "OR":
            x, y = expr[1], expr[2]
            val = (eval_token(x, cache) | eval_token(y, cache)) & MASK
        elif kind == "LSHIFT":
            x, k_tok = expr[1], expr[2]
            k = int(k_tok) if is_int(k_tok) else eval_token(k_tok, cache)
            val = (eval_token(x, cache) << k) & MASK
        elif kind == "RSHIFT":
            x, k_tok = expr[1], expr[2]
            k = int(k_tok) if is_int(k_tok) else eval_token(k_tok, cache)
            val = (eval_token(x, cache) >> k) & MASK
        else:
            raise ValueError(f"Unknown expression kind: {kind}")

        cache[token] = val
        return val

    # Part 1
    cache1: Dict[str, int] = {}
    a1 = eval_token("a", cache1)

    # Part 2: override wire b with a1, reset cache
    expr_by_wire["b"] = ("ASSIGN", a1, None, None)
    cache2: Dict[str, int] = {}
    a2 = eval_token("a", cache2)

    sys.stdout.write(str(a2) + "\n")

if __name__ == "__main__":
    solve()

