import sys

def solve():
    lines = sys.stdin.read().strip().splitlines()
    if not lines:
        return

    name_to_idx = {}
    edges = []

    def get_idx(name):
        if name not in name_to_idx:
            name_to_idx[name] = len(name_to_idx)
        return name_to_idx[name]

    for line in lines:
        line = line.strip()
        if not line:
            continue
        # Format: "CityA to CityB = distance"
        left, dist_str = line.split(" = ")
        city_a, city_b = left.split(" to ")
        a = get_idx(city_a.strip())
        b = get_idx(city_b.strip())
        d = int(dist_str.strip())
        edges.append((a, b, d))

    n = len(name_to_idx)
    if n <= 1:
        print(0)
        return

    INF = 10**18
    dist = [[INF] * n for _ in range(n)]
    for i in range(n):
        dist[i][i] = 0

    for a, b, d in edges:
        dist[a][b] = d
        dist[b][a] = d

    size = 1 << n
    dp = [[INF] * n for _ in range(size)]

    # Base: start at any city i with cost 0
    for i in range(n):
        dp[1 << i][i] = 0

    for mask in range(1, size):
        for last in range(n):
            if not (mask & (1 << last)):
                continue
            prev_mask = mask ^ (1 << last)
            if prev_mask == 0:
                continue
            best = INF
            # Transition from prev -> last
            for prev in range(n):
                if prev_mask & (1 << prev):
                    prev_cost = dp[prev_mask][prev]
                    if prev_cost != INF:
                        cand = prev_cost + dist[prev][last]
                        if cand < best:
                            best = cand
            dp[mask][last] = min(dp[mask][last], best)

    full = size - 1
    ans = min(dp[full][last] for last in range(n))
    print(ans)

if __name__ == "__main__":
    solve()

