import sys

def look_and_say_length(s: str, steps: int = 40) -> int:
    cur = s.strip()
    for _ in range(steps):
        nxt = []
        i = 0
        n = len(cur)
        while i < n:
            d = cur[i]
            j = i + 1
            while j < n and cur[j] == d:
                j += 1
            cnt = j - i
            nxt.append(str(cnt))
            nxt.append(d)
            i = j
        cur = ''.join(nxt)
    return len(cur)

def main():
    s = sys.stdin.readline().strip()
    print(look_and_say_length(s, 40))

if __name__ == "__main__":
    main()

