import sys

def is_valid(p):
    # p: list of 8 ints in [0..25]
    forbidden = {ord('i') - 97, ord('o') - 97, ord('l') - 97}
    for x in p:
        if x in forbidden:
            return False

    # Check for increasing straight of at least 3 letters
    has_straight = False
    for k in range(6):  # windows of length 3: 0..5
        if p[k + 1] == p[k] + 1 and p[k + 2] == p[k] + 2:
            has_straight = True
            break
    if not has_straight:
        return False

    # Check for at least two different, non-overlapping pairs
    pair_letters = set()
    k = 0
    while k < 7:
        if p[k] == p[k + 1]:
            pair_letters.add(p[k])
            k += 2  # enforce non-overlap
        else:
            k += 1
    return len(pair_letters) >= 2

def increment(p):
    # Increment like an odometer: rightmost first, carry on wrap
    i = 7
    while i >= 0:
        p[i] += 1
        if p[i] <= 25:
            break
        p[i] = 0
        i -= 1

def solve(start):
    p = [ord(c) - 97 for c in start.strip()]
    while True:
        increment(p)
        if is_valid(p):
            return ''.join(chr(x + 97) for x in p)

def main():
    s = sys.stdin.readline().strip()
    print(solve(s))

if __name__ == "__main__":
    main()

