import json

def solve():
    s = sys.stdin.read()
    s = s.strip()
    if not s:
        return

    data = json.loads(s)

    def dfs(x):
        # Numbers contribute directly
        if isinstance(x, (int, float)) and not isinstance(x, bool):
            return x
        # Strings never contain numbers
        if isinstance(x, str):
            return 0
        # Arrays: sum over elements
        if isinstance(x, list):
            total = 0
            for e in x:
                total += dfs(e)
            return total
        # Objects: sum over values
        if isinstance(x, dict):
            total = 0
            for v in x.values():
                total += dfs(v)
            return total
        return 0

    ans = dfs(data)

    # Output as integer if it's effectively an integer
    if isinstance(ans, float) and ans.is_integer():
        ans = int(ans)
    sys.stdout.write(str(ans))

if __name__ == "__main__":
    solve()

