def sum_pruned(node):
    # Part Two: ignore any object (and all its children) that has any property value == "red"
    if isinstance(node, bool):
        # JSON booleans are not expected per problem statement, but treat as 0
        return 0
    if isinstance(node, (int, float)):
        return node
    if isinstance(node, str):
        return 0
    if isinstance(node, list):
        return sum(sum_pruned(x) for x in node)
    if isinstance(node, dict):
        # If any immediate value is exactly "red", prune this entire object
        for v in node.values():
            if v == "red":
