import sys
import re

def solve():
    lines = [line.strip() for line in sys.stdin if line.strip()]
    if not lines:
        return

    nameToId = {}
    def get_id(name):
        if name not in nameToId:
            nameToId[name] = len(nameToId)
        return nameToId[name]

    # Parse directed happiness changes H[i][j]
    parsed = []
    pat = re.compile(r'^(\w+)\s+would\s+(gain|lose)\s+(\d+)\s+happiness\s+units\s+by\s+sitting\s+next\s+to\s+(\w+)\.?$')
    for line in lines:
        m = pat.match(line)
        if not m:
            continue
        a, gl, val, b = m.group(1), m.group(2), int(m.group(3)), m.group(4)
        i = get_id(a)
        j = get_id(b)
        signed = val if gl == "gain" else -val
        parsed.append((i, j, signed))

    n = len(nameToId)
    if n <= 1:
        print(0)
        return

    # Build directed matrix H
    H = [[0] * n for _ in range(n)]
    for i, j, signed in parsed:
        H[i][j] = signed

    # Undirected edge weights for adjacency contribution
    W = [[0] * n for _ in range(n)]
    for i in range(n):
        for j in range(n):
            if i != j:
                W[i][j] = H[i][j] + H[j][i]

    # Anchor guest 0 to remove rotational symmetry
    anchor = 0
    others = [i for i in range(n) if i != anchor]
    m = n - 1  # number of nodes in DP

    # Map guest id -> bit position in [0..m-1]
    bitpos = {}
    for idx, guest in enumerate(others):
        bitpos[guest] = idx

    fullMask = (1 << m) - 1

    # dp[mask][last] where last is guest id (not bit index) for guests in others
    # We'll store dp as list of dicts for memory efficiency.
    # dp_mask_last[mask][last_guest] = best value
    dp = [dict() for _ in range(1 << m)]

    # Initialize: paths starting at anchor and going to last
    for guest in others:
        mask = 1 << bitpos[guest]
        dp[mask][guest] = W[anchor][guest]

    # Transitions
    for mask in range(1 << m):
        if not dp[mask]:
            continue
        # For each possible last in this mask, extend to a new guest
        for last_guest, cur_val in list(dp[mask].items()):
            # Try adding next guest not in mask
            for nxt in others:
                b = bitpos[nxt]
                if mask & (1 << b):
                    continue
                nxt_mask = mask | (1 << b)
                cand = cur_val + W[last_guest][nxt]
                prev = dp[nxt_mask].get(nxt)
                if prev is None or cand > prev:
                    dp[nxt_mask][nxt] = cand

    # Close the cycle back to anchor
    best = None
    for last_guest, val in dp[fullMask].items():
        total = val + W[last_guest][anchor]
        if best is None or total > best:
            best = total

    print(best if best is not None else 0)

if __name__ == "__main__":
    solve()

