import sys
import re

T = 2503

def solve(lines):
    pattern = re.compile(
        r"(\d+)\s+km/s\s+for\s+(\d+)\s+seconds,\s+but\s+then\s+must\s+rest\s+for\s+(\d+)\s+seconds"
    )

    reindeers = []
    for line in lines:
        line = line.strip()
        if not line:
            continue
        m = pattern.search(line)
        if not m:
            continue
        speed, fly, rest = map(int, m.groups())
        reindeers.append((speed, fly, rest))

    n = len(reindeers)
    dist = [0] * n
    points = [0] * n

    for t in range(1, T + 1):
        for i, (speed, fly, rest) in enumerate(reindeers):
            cycle = fly + rest
            pos = (t - 1) % cycle  # phase at the start of second t
            if pos < fly:          # flying during [t-1, t)
                dist[i] += speed

        best = max(dist)
        for i in range(n):
            if dist[i] == best:
                points[i] += 1

    return str(max(points) if points else 0)

def main():
    lines = sys.stdin.read().splitlines()
    print(solve(lines))

if __name__ == "__main__":
    main()

