import sys

def solve_part(target: int, multiplier: int, max_houses_per_elf: int | None) -> int:
    # Find smallest house h such that presents[h] >= target
    if target <= multiplier:
        return 1

    # Exponential search for a sufficient upper bound N
    N = max(1, target // multiplier)
    if N < 1:
        N = 1

    while True:
        presents = [0] * (N + 1)

        if max_houses_per_elf is None:
            # Part 1: elf e visits all multiples of e
            for e in range(1, N + 1):
                add = multiplier * e
                for m in range(e, N + 1, e):
                    presents[m] += add
        else:
            # Part 2: elf e visits only first max_houses_per_elf multiples
            limit_k = max_houses_per_elf
            for e in range(1, N + 1):
                add = multiplier * e
                # m = e*k, k in [1..limit_k], m <= N
                max_k = min(limit_k, N // e)
                for k in range(1, max_k + 1):
                    presents[e * k] += add

        for h in range(1, N + 1):
            if presents[h] >= target:
                return h

        N *= 2


