    target = int(data[0])

    part1 = solve_part(target, multiplier=10, max_houses_per_elf=None)
    part2 = solve_part(target, multiplier=11, max_houses_per_elf=50)

    sys.stdout.write(f"{part1}\n{part2}\n")


