from functools import lru_cache

def solve(weights, k=4):
    w = sorted(weights, reverse=True)
    n = len(w)
    total = sum(w)
    if total % k != 0:
        return None
    target = total // k

    # Precompute suffix sums for pruning in feasibility checks
    # (not strictly necessary, but can help)
    # We'll use bitmask states for remaining items.
    all_mask = (1 << n) - 1

    best_size = float('inf')
    best_qe = None

    # Feasibility: can remaining items be partitioned into groups_left groups each sum to target?
    @lru_cache(maxsize=None)
    def can_partition(mask, groups_left):
        if groups_left == 1:
            # Only one group left: must sum to target
            s = 0
            m = mask
            while m:
                lsb = m & -m
                idx = (lsb.bit_length() - 1)
                s += w[idx]
                if s > target:
                    return False
                m ^= lsb
            return s == target

        # Quick fail: if remaining sum != groups_left * target, impossible
        # Compute remaining sum with early exit
        rem_sum = 0
        m = mask
        while m:
            lsb = m & -m
            idx = (lsb.bit_length() - 1)
            rem_sum += w[idx]
            if rem_sum > groups_left * target:
                return False
            m ^= lsb
        if rem_sum != groups_left * target:
            return False

        # Build one group summing to target, then recurse
        # Choose first available item to reduce symmetric duplicates
        # Find lowest index set bit
        first_bit = mask & -mask
        first_idx = first_bit.bit_length() - 1

        used_mask = 0
        found = False

        # DFS to form one group from mask, must include first_idx
        def build_group(curr_mask, curr_sum, start_idx):
            nonlocal found
            if found:
                return
            if curr_sum == target:
                # Recurse for remaining groups
                if can_partition(mask ^ curr_mask, groups_left - 1):
                    found = True
                return
            if curr_sum > target:
                return

            # Iterate candidates; enforce inclusion of first_idx by starting from it
            for j in range(start_idx, n):
                bit = 1 << j
                if not (mask & bit):
                    continue
                if curr_sum + w[j] > target:
                    continue
                # Prune duplicates: skip same weight at same recursion depth
                # (only safe because w is sorted; we skip equal weights when previous equal not chosen)
                if j > start_idx and w[j] == w[j - 1] and not (curr_mask & (1 << (j - 1))):
                    continue
                build_group(curr_mask | bit, curr_sum + w[j], j + 1)
                if found:
                    return

        # Start building group including first_idx
        build_group(1 << first_idx, w[first_idx], first_idx + 1)
        return found

