    # Precompute suffix sums for pruning in dfs_group1
    suffix_sum = [0] * (n + 1)
    for idx in range(n - 1, -1, -1):
        suffix_sum[idx] = suffix_sum[idx + 1] + w[idx]

    def dfs_group1(i, curr_sum, curr_cnt, curr_qe, mask1):
        nonlocal best_size, best_qe
        if curr_sum > target:
            return
        if curr_cnt > best_size:
