            if curr_cnt + 1 > best_size:
                continue
            dfs_group1(j + 1, curr_sum + w[j], curr_cnt + 1, curr_qe * w[j], mask1 | bit)

    dfs_group1(0, 0, 0, 1, 0)
    return best_qe

