import sys

def solve(line: str) -> int:
    line = line.strip()
    if not line:
        return 0

    parts = [p.strip() for p in line.split(',')]
    instructions = []
    for p in parts:
        turn = p[0]
        dist = int(p[1:].strip())
        instructions.append((turn, dist))

    # Part 2: first location visited twice
    # Directions: 0=N, 1=E, 2=S, 3=W
    x, y = 0, 0
    dir_idx = 0  # North
    visited = {(0, 0)}

    for turn, d in instructions:
        if turn == 'R':
            dir_idx = (dir_idx + 1) % 4
        else:  # 'L'
            dir_idx = (dir_idx + 3) % 4

        for _ in range(d):
            if dir_idx == 0:      # North
                y += 1
            elif dir_idx == 1:    # East
                x += 1
            elif dir_idx == 2:    # South
                y -= 1
            else:                 # West
                x -= 1

            if (x, y) in visited:
                return abs(x) + abs(y)
            visited.add((x, y))

    return abs(x) + abs(y)

def main():
    line = sys.stdin.readline()
    ans = solve(line)
    print(ans)

if __name__ == "__main__":
    main()

