def solve(lines):
    # Part Two keypad layout (diamond)
    # Coordinates: (r, c)
    keypad = {
        (0, 2): '1',
        (1, 1): '2', (1, 2): '3', (1, 3): '4',
        (2, 0): '5', (2, 1): '6', (2, 2): '7', (2, 3): '8', (2, 4): '9',
        (3, 1): 'A', (3, 2): 'B', (3, 3): 'C',
        (4, 2): 'D'
    }
    valid = set(keypad.keys())

    deltas = {
        'U': (-1, 0),
        'D': (1, 0),
        'L': (0, -1),
        'R': (0, 1)
    }

    current = (2, 0)  # starting at '5'
    code = []

    for s in lines:
        for ch in s:
            if ch not in deltas:
                continue
            dr, dc = deltas[ch]
            nxt = (current[0] + dr, current[1] + dc)
            if nxt in valid:
                current = nxt
        code.append(keypad[current])

    return ''.join(code)

def main():
    lines = []
    for line in sys.stdin:
        line = line.strip()
        if line:
            lines.append(line)
    result = solve(lines)
    sys.stdout.write(result + "\n")

