import sys
from collections import defaultdict

def decode(rows, part_two=False):
    if not rows:
        return ""
    n = len(rows[0])
    answer = []

    for j in range(n):
        count = defaultdict(int)
        for r in rows:
            count[r[j]] += 1

        # Deterministic tie-break: lexicographically smallest character
        best_char = None
        best_freq = None

        for ch, freq in count.items():
            if best_freq is None:
                best_char, best_freq = ch, freq
                continue

            if part_two:
                better = (freq < best_freq) or (freq == best_freq and ch < best_char)
            else:
                better = (freq > best_freq) or (freq == best_freq and ch < best_char)

            if better:
                best_char, best_freq = ch, freq

        answer.append(best_char)

    return "".join(answer)

def main():
    rows = [line.strip() for line in sys.stdin if line.strip() != ""]
    # Part Two: choose least common character per column
    result = decode(rows, part_two=True)
    sys.stdout.write(result + ("\n" if result != "" else ""))

if __name__ == "__main__":
    main()

