import sys

def supports_tls(s: str) -> bool:
    has_abba_outside = False
    has_abba_inside = False

    in_brackets = False
    start = 0

    def scan_segment(seg: str, inside: bool):
        nonlocal has_abba_outside, has_abba_inside
        m = len(seg)
        if m < 4:
            return
        for i in range(m - 3):
            a, b, c, d = seg[i], seg[i + 1], seg[i + 2], seg[i + 3]
            if a == d and b == c and a != b:
                if inside:
                    has_abba_inside = True
                else:
                    has_abba_outside = True

    for idx, ch in enumerate(s):
        if ch == '[':
            # Process supernet segment before '['
            scan_segment(s[start:idx], inside=in_brackets)
            in_brackets = True
            start = idx + 1
        elif ch == ']':
            # Process hypernet segment before ']'
            scan_segment(s[start:idx], inside=in_brackets)
            in_brackets = False
            start = idx + 1

    # Process trailing segment
    scan_segment(s[start:], inside=in_brackets)

    return has_abba_outside and not has_abba_inside


