import sys

def has_abba(s: str) -> bool:
    # ABBA: a b b a with a != b
    for i in range(len(s) - 3):
        a, b, c, d = s[i], s[i+1], s[i+2], s[i+3]
        if a == d and b == c and a != b:
            return True
    return False

def supports_tls(line: str) -> bool:
    supernets = []
    hypers = []
    buf = []
    in_brackets = False

    for ch in line.strip():
        if ch == '[':
            supernets.append(''.join(buf))
            buf = []
            in_brackets = True
        elif ch == ']':
            hypers.append(''.join(buf))
            buf = []
            in_brackets = False
        else:
            buf.append(ch)

    if in_brackets:
        hypers.append(''.join(buf))
    else:
        supernets.append(''.join(buf))

    has_outside = any(has_abba(seg) for seg in supernets)
    has_inside = any(has_abba(seg) for seg in hypers)
    return has_outside and not has_inside

def supports_ssl(line: str) -> bool:
    supernets = []
    hypers = []
    buf = []
    in_brackets = False

    for ch in line.strip():
        if ch == '[':
            supernets.append(''.join(buf))
            buf = []
            in_brackets = True
        elif ch == ']':
            hypers.append(''.join(buf))
            buf = []
            in_brackets = False
        else:
            buf.append(ch)

    if in_brackets:
        hypers.append(''.join(buf))
    else:
        supernets.append(''.join(buf))

    # Collect required BAB patterns from ABA in supernets.
    # If ABA is a b a, required BAB is b a b.
    required = set()
    for seg in supernets:
        for i in range(len(seg) - 2):
            a, b, c = seg[i], seg[i+1], seg[i+2]
            if a == c and a != b:
                required.add((b, a))  # (middle_char, outer_char) => BAB = b a b

    # Check for any matching BAB in hypers.
    for seg in hypers:
        for i in range(len(seg) - 2):
            a, b, c = seg[i], seg[i+1], seg[i+2]
            if a == c and a != b:
                # This is an ABA-like window; treat it as BAB candidate: b a b
                if (a, b) in required:  # because window is a b a, corresponds to BAB = b a b
                    return True
    return False

def solve(lines):
    tls_count = 0
    ssl_count = 0
    for line in lines:
        line = line.strip()
        if not line:
            continue
        if supports_tls(line):
            tls_count += 1
        if supports_ssl(line):
            ssl_count += 1
    # Output format: sample shows single number; choose SSL (Part Two) as default.
    # If you need TLS instead, change to print(tls_count).
    print(ssl_count)

if __name__ == "__main__":
    input_lines = sys.stdin.read().splitlines()
    solve(input_lines)

