import sys

def solve(commands, W=50, H=6):
    # grid[y][x] == True means pixel is lit
    grid = [[False] * W for _ in range(H)]

    for line in commands:
        line = line.strip()
        if not line:
            continue

        if line.startswith("rect "):
            # rect AxB
            dims = line[len("rect "):]
            a_str, b_str = dims.split('x')
            A = int(a_str)
            B = int(b_str)
            for y in range(B):
                for x in range(A):
                    grid[y][x] = True

        elif line.startswith("rotate row y="):
            # rotate row y=A by B
            rest = line[len("rotate row y="):]  # "A by B"
            a_part, b_part = rest.split(" by ")
            row = int(a_part)
            shift = int(b_part) % W

            old = grid[row][:]  # copy row
            for x in range(W):
                grid[row][x] = old[(x - shift) % W]

        elif line.startswith("rotate column x="):
            # rotate column x=A by B
            rest = line[len("rotate column x="):]  # "A by B"
            a_part, b_part = rest.split(" by ")
            col = int(a_part)
            shift = int(b_part) % H

            old = [grid[y][col] for y in range(H)]  # copy column
            for y in range(H):
                grid[y][col] = old[(y - shift) % H]

        else:
            # Unknown command; ignore (should not happen for valid inputs)
            continue

    # Count lit pixels
    return sum(1 for y in range(H) for x in range(W) if grid[y][x])


def main():
    commands = [line.rstrip("\n") for line in sys.stdin if line.strip() != ""]
    result = solve(commands)
    print(result)

if __name__ == "__main__":
    main()

