import sys
import re
from collections import deque
from itertools import combinations

def solve():
    text = sys.stdin.read().strip().splitlines()
    if not text:
        return

    # Regexes for robust parsing
    chip_re = re.compile(r'(\w+)-compatible microchip')
    gen_re = re.compile(r'(\w+) generator')

    floor_of_chip = {}
    floor_of_gen = {}

    for floor, line in enumerate(text):
        # chips
        for m in chip_re.finditer(line):
            elem = m.group(1)
            floor_of_chip[elem] = floor
        # generators
        for m in gen_re.finditer(line):
            elem = m.group(1)
            floor_of_gen[elem] = floor

    elems = sorted(set(floor_of_chip) | set(floor_of_gen))
    n = len(elems)

    # Build initial pairs (chip_floor, gen_floor)
    pairs = []
    for e in elems:
        pairs.append((floor_of_chip.get(e, -1), floor_of_gen.get(e, -1)))
    pairs.sort()
    start_pairs = tuple(pairs)
    start = (0, start_pairs)

    def is_safe(pairs_t):
        # pairs_t is sorted tuple of (chip_floor, gen_floor)
        for f in range(4):
            has_gen = any(g == f for _, g in pairs_t)
            if not has_gen:
                continue
            # if any generator on floor f, all chips on f must have their generator on f
            for c, g in pairs_t:
                if c == f and g != f:
                    return False
        return True

    def goal(pairs_t):
        return all(c == 3 and g == 3 for c, g in pairs_t)

    if not is_safe(start_pairs):
        print(-1)
        return

    def neighbors(elev, pairs_t):
        # items on elevator floor: ('c', idx) or ('g', idx)
        items = []
        for i, (c, g) in enumerate(pairs_t):
            if c == elev:
                items.append(('c', i))
            if g == elev:
                items.append(('g', i))

        if not items:
            return

        for de in (-1, 1):
            ne = elev + de
            if ne < 0 or ne > 3:
                continue

            m = len(items)
            for k in (1, 2):
                if m < k:
                    continue
                for chosen in combinations(items, k):
                    new_pairs = list(pairs_t)
                    for typ, idx in chosen:
                        c, g = new_pairs[idx]
                        if typ == 'c':
                            c = ne
                        else:
                            g = ne
                        new_pairs[idx] = (c, g)

                    new_pairs.sort()
                    new_pairs_t = tuple(new_pairs)
                    if is_safe(new_pairs_t):
                        yield (ne, new_pairs_t)

    q = deque([start])
    dist = {start: 0}

    while q:
        elev, pairs_t = q.popleft()
        d = dist[(elev, pairs_t)]
        if goal(pairs_t):
            print(d)
            return
        for nxt in neighbors(elev, pairs_t):
            if nxt not in dist:
                dist[nxt] = d + 1
                q.append(nxt)

    print(-1)

if __name__ == "__main__":
    solve()

