                        new_pairs[idx] = (c, g)

                    new_pairs.sort()
                    new_pairs_t = tuple(new_pairs)
                    if is_safe(new_pairs_t):
                        yield (ne, new_pairs_t)

    q = deque([start])
    dist = {start: 0}

    while q:
        elev, pairs_t = q.popleft()
        d = dist[(elev, pairs_t)]
        if goal(pairs_t):
            print(d)
            return
        for nxt in neighbors(elev, pairs_t):
            if nxt not in dist:
                dist[nxt] = d + 1
                q.append(nxt)

