import sys

def resolve(token, regs):
    if token in regs:
        return regs[token]
    return int(token)

def run(program_lines):
    # Parse program into structured instructions
    program = []
    for line in program_lines:
        line = line.strip()
        if not line:
            continue
        parts = line.split()
        op = parts[0]
        if op == "cpy":
            x, y = parts[1], parts[2]
            program.append(("cpy", x, y))
        elif op == "inc":
            x = parts[1]
            program.append(("inc", x))
        elif op == "dec":
            x = parts[1]
            program.append(("dec", x))
        elif op == "jnz":
            x, y = parts[1], parts[2]
            program.append(("jnz", x, y))
        else:
            raise ValueError(f"Unknown opcode: {op}")

    regs = {"a": 0, "b": 0, "c": 0, "d": 0}
    ip = 0
    n = len(program)

    # Execute until instruction pointer leaves program bounds
    while 0 <= ip < n:
        inst = program[ip]
        op = inst[0]

        if op == "cpy":
            _, x, y = inst
            v = resolve(x, regs)
            # In valid puzzle inputs, y is always a register
            if y in regs:
                regs[y] = v
            ip += 1

        elif op == "inc":
            _, x = inst
            regs[x] += 1
            ip += 1

        elif op == "dec":
            _, x = inst
            regs[x] -= 1
            ip += 1

        elif op == "jnz":
            _, x, y = inst
            if resolve(x, regs) != 0:
                ip += resolve(y, regs)  # relative jump from current instruction
            else:
                ip += 1

        else:
            raise ValueError(f"Unknown opcode: {op}")

    return regs["a"]

def main():
    lines = sys.stdin.read().splitlines()
    result = run(lines)
    sys.stdout.write(str(result) + "\n")

if __name__ == "__main__":
    main()

