import sys

def solve(n: int) -> int:
    # Largest power of 3 <= n
    p = 1
    while p * 3 <= n:
        p *= 3

    if n == p:
        return n
    elif n <= 2 * p:
        return n - p
    else:
        return 2 * n - 3 * p

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    print(solve(n))

if __name__ == "__main__":
    main()

