import sys

def lowest_unblocked(intervals, max_ip=4294967295):
    # Sort intervals by start, then end
    intervals.sort(key=lambda x: (x[0], x[1]))

    current = 0  # smallest IP not yet proven blocked

    for s, e in intervals:
        if e < current:
            continue  # interval entirely to the left of current

        if s > current:
            return current  # gap found

        # Overlaps or touches current (inclusive)
        if e >= current:
            current = e + 1
            if current > max_ip:
                break

    return current

def main():
    intervals = []
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        s_str, e_str = line.split('-')
        s = int(s_str)
        e = int(e_str)
        if s > e:  # defensive normalization
            s, e = e, s
        intervals.append((s, e))

    ans = lowest_unblocked(intervals)
    print(ans)

if __name__ == "__main__":
    main()

