import sys
import itertools

def parse_ops(lines):
    ops = []
    for line in lines:
        line = line.strip()
        if not line:
            continue
        if line.startswith("swap position"):
            # swap position X with position Y
            parts = line.split()
            x = int(parts[2])
            y = int(parts[5])
            ops.append(("swap_pos", x, y))
        elif line.startswith("swap letter"):
            # swap letter X with letter Y
            parts = line.split()
            a = parts[2]
            b = parts[5]
            ops.append(("swap_letter", a, b))
        elif line.startswith("rotate left"):
            parts = line.split()
            x = int(parts[2])
            ops.append(("rot_left", x))
        elif line.startswith("rotate right"):
            parts = line.split()
            x = int(parts[2])
            ops.append(("rot_right", x))
        elif line.startswith("rotate based on position of letter"):
            parts = line.split()
            a = parts[-1]
            ops.append(("rot_based", a))
        elif line.startswith("reverse positions"):
            parts = line.split()
            x = int(parts[2])
            y = int(parts[4])
            ops.append(("rev_pos", x, y))
        elif line.startswith("move position"):
            parts = line.split()
            x = int(parts[2])
            y = int(parts[5])
            ops.append(("move_pos", x, y))
        else:
            raise ValueError(f"Unknown operation: {line}")
    return ops

def rotate_left(s, k):
    n = len(s)
    k %= n
    if k == 0:
        return s
    return s[k:] + s[:k]

def rotate_right(s, k):
    n = len(s)
    k %= n
    if k == 0:
        return s
    return s[-k:] + s[:-k]

def apply_op(op, s):
    n = len(s)
    t = list(s)
    typ = op[0]

    if typ == "swap_pos":
        x, y = op[1], op[2]
        t[x], t[y] = t[y], t[x]
        return "".join(t)

    if typ == "swap_letter":
        a, b = op[1], op[2]
        # swap all occurrences of letters a and b (here it's a permutation, so exactly one each)
        for i, ch in enumerate(t):
            if ch == a:
                t[i] = b
            elif ch == b:
                t[i] = a
        return "".join(t)

    if typ == "rot_left":
        x = op[1]
        return rotate_left(s, x)

    if typ == "rot_right":
        x = op[1]
        return rotate_right(s, x)

    if typ == "rot_based":
        a = op[1]
        i = s.index(a)
        r = 1 + i + (1 if i >= 4 else 0)
        return rotate_right(s, r)

    if typ == "rev_pos":
        x, y = op[1], op[2]
        if x < y:
            t[x:y+1] = reversed(t[x:y+1])
        else:
            t[y:x+1] = reversed(t[y:x+1])
        return "".join(t)

    if typ == "move_pos":
        x, y = op[1], op[2]
        ch = t.pop(x)
        t.insert(y, ch)
        return "".join(t)

    raise ValueError(f"Unknown op type: {typ}")

def build_inverse_rot_based(ops, n, alphabet):
    # Precompute inverse mapping for each distinct letter used in rot_based operations.
    # inv_map[a][scrambled] = original
    letters = sorted({op[1] for op in ops if op[0] == "rot_based"})
    inv_map = {a: {} for a in letters}

    # Enumerate all permutations of the alphabet (n is small, typically 8).
    for perm in itertools.permutations(alphabet, n):
        s = "".join(perm)
        for a in letters:
            t = apply_op(("rot_based", a), s)
            inv_map[a][t] = s
    return inv_map

def unscramble(target, ops, alphabet):
    n = len(target)
    inv_rot_based = build_inverse_rot_based(ops, n, alphabet)

    s = target
    for op in reversed(ops):
        typ = op[0]
        if typ == "swap_pos":
            s = apply_op(op, s)  # self-inverse
        elif typ == "swap_letter":
            s = apply_op(op, s)  # self-inverse
        elif typ == "rot_left":
            x = op[1]
            s = rotate_right(s, x)
        elif typ == "rot_right":
            x = op[1]
            s = rotate_left(s, x)
        elif typ == "rot_based":
            a = op[1]
            s = inv_rot_based[a][s]
        elif typ == "rev_pos":
            s = apply_op(op, s)  # self-inverse
        elif typ == "move_pos":
            x, y = op[1], op[2]
            # inverse of move x->y is move y->x
            s = apply_op(("move_pos", y, x), s)
        else:
            raise ValueError(f"Unknown op type: {typ}")
    return s

def main():
    lines = sys.stdin.read().splitlines()
    ops = parse_ops(lines)

    # Part Two target is fixed by the prompt.
    target = "fbgdceah"

    # Determine alphabet from target (assumes it's a permutation of the intended letters).
    alphabet = sorted(set(target))
    if len(alphabet) != len(target):
        # Fallback: use unique letters in target in order (still should be a permutation).
        alphabet = list(dict.fromkeys(target))

    result = unscramble(target, ops, alphabet)
    sys.stdout.write(result)

if __name__ == "__main__":
    main()

