import sys
import re
from collections import deque

def solve(data: str) -> str:
    lines = [ln.rstrip("\n") for ln in data.splitlines() if ln.strip()]
    node_re = re.compile(r"^/dev/grid/node-x(\d+)-y(\d+)\s+(\d+)T\s+(\d+)T\s+(\d+)T\s+(\d+)%\s*$")

    nodes = {}  # (x,y) -> (size, used, avail)
    max_x = -1
    max_y = -1

    for ln in lines:
        m = node_re.match(ln)
        if not m:
            continue
        x, y = int(m.group(1)), int(m.group(2))
        size, used, avail = int(m.group(3)), int(m.group(4)), int(m.group(5))
        nodes[(x, y)] = (size, used, avail)
        max_x = max(max_x, x)
        max_y = max(max_y, y)

    if max_x < 0 or max_y < 0:
        return "0"

    W = max_x + 1
    H = max_y + 1

    used = [[0] * H for _ in range(W)]
    avail = [[0] * H for _ in range(W)]

    empty_pos = None
    goal_pos = None
    best_goal_x = -1

    for (x, y), (size, u, a) in nodes.items():
        used[x][y] = u
        avail[x][y] = a
        if u == 0:
            empty_pos = (x, y)
        if y == 0 and x > best_goal_x:
            best_goal_x = x
            goal_pos = (x, y)

    if empty_pos is None or goal_pos is None:
        return "0"

    target = (0, 0)
    if goal_pos == target:
        return "0"

    ex0, ey0 = empty_pos
    gx0, gy0 = goal_pos

    # Walls: nodes whose data cannot fit into the empty node's capacity.
    empty_cap = avail[ex0][ey0]
    wall = [[False] * H for _ in range(W)]
    for x in range(W):
        for y in range(H):
            if used[x][y] > empty_cap:
                wall[x][y] = True

    def neighbors(x, y):
        if x > 0:
            yield x - 1, y
        if x + 1 < W:
            yield x + 1, y
        if y > 0:
            yield x, y - 1
        if y + 1 < H:
            yield x, y + 1

    # State: (empty_x, empty_y, goal_x, goal_y)
    # Encode into a single integer for fast visited/dist.
    # id = (((ey*W + ex) * (H*W)) + (gy*W + gx))
    HW = H * W

    def sid(ex, ey, gx, gy):
        return ((ey * W + ex) * HW) + (gy * W + gx)

    start_id = sid(ex0, ey0, gx0, gy0)
    dist = {start_id: 0}
    q = deque([(ex0, ey0, gx0, gy0)])

    while q:
        ex, ey, gx, gy = q.popleft()
        cur_d = dist[sid(ex, ey, gx, gy)]
        if (gx, gy) == target:
            return str(cur_d)

        for nx, ny in neighbors(ex, ey):
            if wall[nx][ny]:
                continue

            # Swap empty with neighbor.
            new_ex, new_ey = nx, ny
            if (nx, ny) == (gx, gy):
                # Goal data moved into the old empty position.
                new_gx, new_gy = ex, ey
            else:
                new_gx, new_gy = gx, gy

            nid = sid(new_ex, new_ey, new_gx, new_gy)
            if nid not in dist:
                dist[nid] = cur_d + 1
                q.append((new_ex, new_ey, new_gx, new_gy))

    return "0"

if __name__ == "__main__":
    inp = sys.stdin.read()
    sys.stdout.write(solve(inp))

