import sys

def parse_operand(tok: str):
    tok = tok.strip()
    if len(tok) == 1 and tok.isalpha() and tok.islower():
        return ("reg", tok)
    return ("lit", int(tok))

def is_reg(opnd):
    return opnd[0] == "reg"

def get_value(opnd, regs):
    if opnd[0] == "lit":
        return opnd[1]
    return regs[opnd[1]]

def toggle_instruction(inst):
    op = inst["op"]
    args = inst["args"]
    argc = len(args)
    if argc == 1:
        if op == "inc":
            new_op = "dec"
        else:
            new_op = "inc"
    else:
        if op == "jnz":
            new_op = "cpy"
        else:
            new_op = "jnz"
    return {"op": new_op, "args": args}

def run(prog):
    regs = {"a": 7, "b": 0, "c": 0, "d": 0}
    ip = 0
    n = len(prog)

    while 0 <= ip < n:
        inst = prog[ip]
        op = inst["op"]
        args = inst["args"]

        if op == "cpy":
            x, y = args
            if is_reg(y):
                regs[y[1]] = get_value(x, regs)
            ip += 1

        elif op == "inc":
            x = args[0]
            if is_reg(x):
                regs[x[1]] += 1
            ip += 1

        elif op == "dec":
            x = args[0]
            if is_reg(x):
                regs[x[1]] -= 1
            ip += 1

        elif op == "jnz":
            x, y = args
            if get_value(x, regs) != 0:
                ip += get_value(y, regs)
            else:
                ip += 1

        elif op == "tgl":
            x = args[0]
            offset = get_value(x, regs)
            target = ip + offset
            if 0 <= target < n:
                prog[target] = toggle_instruction(prog[target])
            ip += 1

        else:
            # Unknown op; should not happen with valid input.
            ip += 1

    return regs["a"]

def main():
    lines = [line.rstrip("\n") for line in sys.stdin if line.strip() != ""]
    prog = []
    for line in lines:
        parts = line.split()
        op = parts[0]
        args = [parse_operand(p) for p in parts[1:]]
        prog.append({"op": op, "args": args})

    ans = run(prog)
    sys.stdout.write(str(ans) + "\n")

if __name__ == "__main__":
    main()

