import sys
from collections import deque

def solve():
    grid = [line.rstrip('\n') for line in sys.stdin if line.strip('\n') != '']
    if not grid:
        return
    R, C = len(grid), len(grid[0])

    # Collect all digit positions
    pos_by_digit = {}
    for r in range(R):
        for c in range(C):
            ch = grid[r][c]
            if ch.isdigit():
                pos_by_digit[int(ch)] = (r, c)

    if 0 not in pos_by_digit:
        print(0)
        return

    # Remap digits to indices 0..m-1, ensuring digit 0 becomes index 0
    digits = sorted(pos_by_digit.keys())
    if 0 in digits:
        digits.remove(0)
    digits = [0] + digits  # index 0 corresponds to digit 0
    m = len(digits)

    coords = [pos_by_digit[d] for d in digits]

    # BFS from each special point to compute pairwise shortest distances
    INF = 10**18
    D = [[INF] * m for _ in range(m)]

    traversable = [[grid[r][c] != '#' for c in range(C)] for r in range(R)]
    dirs = [(1, 0), (-1, 0), (0, 1), (0, -1)]

    for i in range(m):
        sr, sc = coords[i]
        dist = [[-1] * C for _ in range(R)]
        q = deque([(sr, sc)])
        dist[sr][sc] = 0
        while q:
            r, c = q.popleft()
            for dr, dc in dirs:
                nr, nc = r + dr, c + dc
                if 0 <= nr < R and 0 <= nc < C and traversable[nr][nc] and dist[nr][nc] == -1:
                    dist[nr][nc] = dist[r][c] + 1
                    q.append((nr, nc))
        for j in range(m):
            tr, tc = coords[j]
            d = dist[tr][tc]
            if d != -1:
                D[i][j] = d

    # Held-Karp DP for shortest path starting at 0 visiting all nodes (no need to return)
    start = 0
    ALL = (1 << m) - 1
    dp = [[INF] * m for _ in range(1 << m)]
    dp[1 << start][start] = 0

    for mask in range(1 << m):
        for i in range(m):
            cur = dp[mask][i]
            if cur == INF:
                continue
            if not (mask & (1 << i)):
                continue
            for j in range(m):
                if mask & (1 << j):
                    continue
                dij = D[i][j]
                if dij == INF:
                    continue
                mask2 = mask | (1 << j)
                val = cur + dij
                if val < dp[mask2][j]:
                    dp[mask2][j] = val

    ans = min(dp[ALL])
    print(ans if ans != INF else -1)

if __name__ == "__main__":
    solve()

