import sys
from collections import deque

def solve(data: str) -> str:
    lines = [line.rstrip("\n") for line in data.splitlines() if line.strip("\n") != ""]
    if not lines:
        return ""
    grid = [list(line) for line in lines]
    H, W = len(grid), len(grid[0])

    # Map digit characters to compact indices 0..k-1
    digit_to_idx = {}
    pos = []  # list of (r,c) for each compact index

    for r in range(H):
        for c in range(W):
            ch = grid[r][c]
            if ch.isdigit():
                if ch not in digit_to_idx:
                    digit_to_idx[ch] = len(pos)
                    pos.append((r, c))

    k = len(pos)
    if k == 0:
        return "0"

    # Ensure node '0' exists and is index 0
    if '0' not in digit_to_idx:
        # Problem statement says 0 exists; handle gracefully
        return "0"

    idx0 = digit_to_idx['0']
    if idx0 != 0:
        # Swap compact indices so that index 0 corresponds to digit '0'
        pos[0], pos[idx0] = pos[idx0], pos[0]
        # Update mapping
        for d, i in list(digit_to_idx.items()):
            if i == 0:
                digit_to_idx[d] = idx0
            elif i == idx0:
                digit_to_idx[d] = 0

    # Precompute BFS distances between all special nodes
    INF = 10**18
    dist = [[INF] * k for _ in range(k)]

    directions = [(1, 0), (-1, 0), (0, 1), (0, -1)]

    def bfs_from(start_idx: int):
        sr, sc = pos[start_idx]
        q = deque()
        q.append((sr, sc))
        dmap = [[-1] * W for _ in range(H)]
        dmap[sr][sc] = 0

        while q:
            r, c = q.popleft()
            for dr, dc in directions:
                nr, nc = r + dr, c + dc
                if 0 <= nr < H and 0 <= nc < W and dmap[nr][nc] == -1:
                    if grid[nr][nc] != '#':
                        dmap[nr][nc] = dmap[r][c] + 1
                        q.append((nr, nc))

        for j in range(k):
            tr, tc = pos[j]
            dd = dmap[tr][tc]
            if dd != -1:
                dist[start_idx][j] = dd

    for i in range(k):
        bfs_from(i)

    # If any pair is unreachable, DP will naturally fail; still compute safely.
    ALL = (1 << k) - 1
    dp = [[INF] * k for _ in range(1 << k)]
    dp[1 << 0][0] = 0

    for mask in range(1 << k):
        for i in range(k):
            cur = dp[mask][i]
            if cur >= INF:
                continue
            if not (mask & (1 << i)):
                continue
            for j in range(k):
                if mask & (1 << j):
                    continue
                dij = dist[i][j]
                if dij >= INF:
                    continue
                mask2 = mask | (1 << j)
                nd = cur + dij
                if nd < dp[mask2][j]:
                    dp[mask2][j] = nd

    ans = INF
    for i in range(k):
        if dp[ALL][i] >= INF:
            continue
        back = dist[i][0]
        if back >= INF:
            continue
        ans = min(ans, dp[ALL][i] + back)

    return str(ans if ans < INF else -1)

if __name__ == "__main__":
    data = sys.stdin.read()
    sys.stdout.write(solve(data) + "\n")

