import sys

def parse_program(lines):
    prog = []
    for line in lines:
        line = line.strip()
        if not line:
            continue
        parts = line.split()
        op = parts[0]
        if op == "out":
            prog.append((op, parts[1], None))
        elif op in ("inc", "dec"):
            prog.append((op, parts[1], None))
        elif op in ("cpy", "jnz"):
            prog.append((op, parts[1], parts[2]))
        else:
            raise ValueError(f"Unknown opcode: {op}")
    return prog

def is_register(x):
    return x in ("a", "b", "c", "d")

def value_of(x, regs):
    if is_register(x):
        return regs[x]
    return int(x)

def run_candidate(prog, a_init, max_steps, max_outputs, verify_len):
    regs = {"a": a_init, "b": 0, "c": 0, "d": 0}
    ip = 0
    outs = 0

    # Early stopping: verify strict alternation as we generate outputs.
    # Expected bit at output index k (0-based) is k % 2.
    while 0 <= ip < len(prog) and outs < verify_len:
        if max_steps <= 0:
            return False
        max_steps -= 1

        op, x, y = prog[ip]

        if op == "cpy":
            if is_register(y):
                regs[y] = value_of(x, regs)
            ip += 1

        elif op == "inc":
            regs[x] += 1
            ip += 1

        elif op == "dec":
            regs[x] -= 1
            ip += 1

        elif op == "jnz":
            if value_of(x, regs) != 0:
                ip += value_of(y, regs)
            else:
                ip += 1

        elif op == "out":
            bit = value_of(x, regs) & 1
            expected = outs & 1
            if bit != expected:
                return False
            outs += 1
            ip += 1

        else:
            raise ValueError(f"Unknown opcode: {op}")

    if outs < verify_len:
        return False

    # Optional extra verification for confidence (still bounded).
    # If verify_len already large enough, this is cheap.
    if max_outputs > verify_len:
        # Continue a bit more to reduce false positives.
        while 0 <= ip < len(prog) and outs < max_outputs:
            if max_steps <= 0:
                return False
            max_steps -= 1

            op, x, y = prog[ip]

            if op == "cpy":
                if is_register(y):
                    regs[y] = value_of(x, regs)
                ip += 1

            elif op == "inc":
                regs[x] += 1
                ip += 1

            elif op == "dec":
                regs[x] -= 1
                ip += 1

            elif op == "jnz":
                if value_of(x, regs) != 0:
                    ip += value_of(y, regs)
                else:
                    ip += 1

            elif op == "out":
                bit = value_of(x, regs) & 1
                expected = outs & 1
                if bit != expected:
                    return False
                outs += 1
                ip += 1

            else:
                raise ValueError(f"Unknown opcode: {op}")

        if outs < max_outputs:
            return False

    return True

def solve():
    lines = sys.stdin.read().splitlines()
    prog = parse_program(lines)

    # Conservative bounds; wrong candidates fail quickly due to early mismatch.
    verify_len = 300
    max_outputs = 600
    max_steps = 2_000_000

    a = 1
    while True:
        if run_candidate(prog, a, max_steps=max_steps, max_outputs=max_outputs, verify_len=verify_len):
            print(a)
            return
        a += 1

if __name__ == "__main__":
    solve()

