import sys
from typing import List, Tuple, Union, Optional

Operand = Union[int, str]
Instr = Tuple[str, Operand, Optional[Operand]]

def parse_program(lines: List[str]) -> List[Instr]:
    prog: List[Instr] = []
    for line in lines:
        line = line.strip()
        if not line:
            continue
        parts = line.split()
        op = parts[0]
        if op == "cpy":
            x = parts[1]
            y = parts[2]
            prog.append(("cpy", parse_operand(x), y))
        elif op == "inc":
            prog.append(("inc", parts[1], None))
        elif op == "dec":
            prog.append(("dec", parts[1], None))
        elif op == "jnz":
            x = parts[1]
            y = parts[2]
            prog.append(("jnz", parse_operand(x), parse_operand(y)))
        elif op == "out":
            prog.append(("out", parse_operand(parts[1]), None))
        else:
            raise ValueError(f"Unknown opcode: {op}")
    return prog

def parse_operand(tok: str) -> Operand:
    # AoC uses literals and registers; no labels in this puzzle input.
    if tok.lstrip("-").isdigit():
        return int(tok)
    return tok

def val(operand: Operand, regs: List[int]) -> int:
    if isinstance(operand, int):
        return operand
    idx = reg_index(operand)
    return regs[idx]

def reg_index(name: str) -> int:
    # Registers are a,b,c,d
    return ord(name) - ord('a')

def run_and_check(prog: List[Instr], a_init: int, need_outputs: int) -> bool:
    regs = [0, 0, 0, 0]
    regs[0] = a_init  # a
    ip = 0
    out_count = 0

    # Safety bound to avoid infinite loops for wrong candidates.
    # Typically outputs are frequent; this is generous.
    max_steps = 2000000

    while 0 <= ip < len(prog) and out_count < need_outputs and max_steps > 0:
        max_steps -= 1
        op, x, y = prog[ip]

        if op == "cpy":
            # y must be a register; if not, treat as no-op.
            if isinstance(y, str):
                yi = reg_index(y)
                regs[yi] = val(x, regs)
            ip += 1
        elif op == "inc":
            ri = reg_index(x)  # type: ignore[arg-type]
            regs[ri] += 1
            ip += 1
        elif op == "dec":
            ri = reg_index(x)  # type: ignore[arg-type]
            regs[ri] -= 1
            ip += 1
        elif op == "jnz":
            # x is value, y is offset (literal or register)
            if val(x, regs) != 0:
                ip += val(y, regs)  # type: ignore[arg-type]
            else:
                ip += 1
        elif op == "out":
            v = val(x, regs)
            expected = out_count % 2
            if v != expected:
                return False
            out_count += 1
            ip += 1
        else:
            raise ValueError(f"Unknown opcode: {op}")

    return out_count == need_outputs

def solve(need_outputs: int) -> int:
    lines = sys.stdin.read().strip().splitlines()
    prog = parse_program(lines)

    # Search smallest positive integer a.
    a = 1
    while True:
        if run_and_check(prog, a, need_outputs):
            return a
        a += 1

def main():
    # Part Two requires 50 outputs.
    ans = solve(50)
    sys.stdout.write(str(ans) + "\n")

if __name__ == "__main__":
    main()

