def inverse_captcha_sum(s: str) -> int:
    s = s.strip()
    n = len(s)
    total = 0
    for i in range(n):
        j = (i + 1) % n  # circular next index
        if s[i] == s[j]:
            total += ord(s[i]) - ord('0')
    return total

