def solve(banks):
    n = len(banks)
    seen = {tuple(banks): 0}
    cycle = 0

    while True:
        cycle += 1

        # Find index of bank with most blocks (ties -> lowest index)
        max_blocks = max(banks)
        i = 0
        for idx, v in enumerate(banks):
            if v == max_blocks:
                i = idx
                break

        x = banks[i]
        banks[i] = 0

        # Distribute x blocks starting from next bank, wrapping around
        q, r = divmod(x, n)
        if q:
            for j in range(n):
                banks[j] += q
        for k in range(1, r + 1):
