import sys
import operator

def solve(data: str) -> str:
    regs = {}
    max_ever = 0

    cmp_ops = {
        ">": operator.gt,
        "<": operator.lt,
        ">=": operator.ge,
        "<=": operator.le,
        "==": operator.eq,
        "!=": operator.ne,
    }

    for line in data.splitlines():
        line = line.strip()
        if not line:
            continue
        parts = line.split()
        if len(parts) != 7:
            continue  # Graceful handling for unexpected lines

        target, op, amount_s, _, cond_left, cond_cmp, cond_right_s = parts
        amount = int(amount_s)
        cond_right = int(cond_right_s)

        left_val = regs.get(cond_left, 0)
        if not cmp_ops[cond_cmp](left_val, cond_right):
            continue

        delta = amount if op == "inc" else -amount
        new_val = regs.get(target, 0) + delta
        regs[target] = new_val
        if new_val > max_ever:
            max_ever = new_val

    return str(max_ever)

def main():
    data = sys.stdin.read()
    sys.stdout.write(solve(data))

if __name__ == "__main__":
    main()

