import sys

def knot_product(lengths, n=256):
    arr = list(range(n))
    current = 0
    skip = 0

    for L in lengths:
        # Reverse L elements starting at current (circularly)
        for i in range(L // 2):
            a = (current + i) % n
            b = (current + L - 1 - i) % n
            arr[a], arr[b] = arr[b], arr[a]

        current = (current + L + skip) % n
        skip += 1

    return arr[0] * arr[1]

