import sys

def knot_hash(s: str) -> str:
    # Convert input to ASCII codes and append the fixed suffix
    lengths = [ord(c) for c in s] + [17, 31, 73, 47, 23]

    # Initialize circular list
    nums = list(range(256))
    pos = 0
    skip = 0

    # 64 rounds of the knotting process
    for _ in range(64):
        for L in lengths:
            if L > 1:
                # Reverse sublist of length L starting at pos on the circular list
                for i in range(L // 2):
                    a = (pos + i) % 256
                    b = (pos + L - 1 - i) % 256
                    nums[a], nums[b] = nums[b], nums[a]
            pos = (pos + L + skip) % 256
            skip += 1

    # Dense hash: XOR blocks of 16 numbers
    dense = []
    for i in range(0, 256, 16):
        x = 0
        for v in nums[i:i+16]:
            x ^= v
        dense.append(x)

    # Convert to 32 lowercase hex digits
    return ''.join(f'{x:02x}' for x in dense)

def solve() -> None:
    key = sys.stdin.readline().strip()

    hex_to_bits = {
        '0': "0000", '1': "0001", '2': "0010", '3': "0011",
        '4': "0100", '5': "0101", '6': "0110", '7': "0111",
        '8': "1000", '9': "1001", 'a': "1010", 'b': "1011",
        'c': "1100", 'd': "1101", 'e': "1110", 'f': "1111",
    }

    used_count = 0
    for r in range(128):
        row_key = f"{key}-{r}"
        h = knot_hash(row_key)
        for ch in h:
            used_count += hex_to_bits[ch].count('1')

    print(used_count)

if __name__ == "__main__":
    solve()

