import sys
from collections import deque

def knot_hash(s: str) -> str:
    # Convert input to ASCII codes and append the standard suffix
    lengths = [ord(ch) for ch in s] + [17, 31, 73, 47, 23]

    nums = list(range(256))
    pos = 0
    skip = 0

    # 64 rounds of the knotting process
    for _ in range(64):
        for L in lengths:
            if L > 1:
                # Reverse sublist of length L starting at pos (wrapping around)
                idxs = [(pos + i) % 256 for i in range(L)]
                vals = [nums[i] for i in idxs][::-1]
                for i, v in zip(idxs, vals):
                    nums[i] = v
            pos = (pos + L + skip) % 256
            skip += 1

    # Dense hash: XOR blocks of 16 numbers
    dense = []
    for i in range(0, 256, 16):
        x = 0
        for v in nums[i:i+16]:
            x ^= v
        dense.append(x)

    # Convert to 32 hex digits
    return ''.join(f'{b:02x}' for b in dense)

def solve(key: str) -> int:
    used = [[False] * 128 for _ in range(128)]

    # Build the 128x128 grid
    for r in range(128):
        h = knot_hash(f"{key}-{r}")  # 32 hex chars => 128 bits
        c = 0
        for ch in h:
            v = int(ch, 16)
            # High-bit first: 4 bits per hex digit
            for shift in (3, 2, 1, 0):
                used[r][c] = ((v >> shift) & 1) == 1
                c += 1

    visited = [[False] * 128 for _ in range(128)]
    regions = 0

    # Count connected regions using BFS
    for i in range(128):
        for j in range(128):
            if not used[i][j] or visited[i][j]:
                continue
            regions += 1
            visited[i][j] = True
            q = deque([(i, j)])

            while q:
                x, y = q.popleft()
                if x > 0 and used[x - 1][y] and not visited[x - 1][y]:
                    visited[x - 1][y] = True
                    q.append((x - 1, y))
                if x < 127 and used[x + 1][y] and not visited[x + 1][y]:
                    visited[x + 1][y] = True
                    q.append((x + 1, y))
                if y > 0 and used[x][y - 1] and not visited[x][y - 1]:
