                    q.append((x, y - 1))
                if y < 127 and used[x][y + 1] and not visited[x][y + 1]:
                    visited[x][y + 1] = True
                    q.append((x, y + 1))

    return regions

def main():
    key = sys.stdin.readline().strip()
    print(solve(key))

if __name__ == "__main__":
    main()

