import sys

def solve():
    line = sys.stdin.readline().strip()
    if not line:
        return
    moves = line.split(',')

    # Decide N:
    # The sample "baedc" is from the 5-program example (a..e).
    # If partner moves only reference up to 'e', use N=5; else default to 16.
    max_letter = 'a'
    for mv in moves:
        if mv[0] == 'p':
            a, b = mv[1:].split('/')
            if a > max_letter:
                max_letter = a
            if b > max_letter:
                max_letter = b

    N = 5 if max_letter <= 'e' else 16

    arr = [chr(ord('a') + i) for i in range(N)]

    for mv in moves:
        t = mv[0]
        if t == 's':
            x = int(mv[1:]) % N
            if x:
                arr = arr[-x:] + arr[:-x]
        elif t == 'x':
            a, b = mv[1:].split('/')
            i, j = int(a), int(b)
            arr[i], arr[j] = arr[j], arr[i]
        elif t == 'p':
            a, b = mv[1:].split('/')
            i = arr.index(a)
            j = arr.index(b)
            arr[i], arr[j] = arr[j], arr[i]
        else:
            raise ValueError(f"Unknown move: {mv}")

    sys.stdout.write(''.join(arr))

if __name__ == "__main__":
    solve()

