import sys

def main():
    program = []
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        parts = line.split()
        op = parts[0]
        if len(parts) == 2:
            x = parts[1]
            y = None
        else:
            x = parts[1]
            y = parts[2]
        program.append((op, x, y))

    regs = {}
    def val(tok):
        if tok is None:
            return 0
        # Register names are single letters
        if len(tok) == 1 and tok.isalpha():
            return regs.get(tok, 0)
        return int(tok)

    ip = 0
    last_sound = 0

    while 0 <= ip < len(program):
        op, x, y = program[ip]

        if op == "snd":
            last_sound = val(x)
            ip += 1
        elif op == "set":
            regs[x] = val(y)
            ip += 1
        elif op == "add":
            regs[x] = val(x) + val(y)
            ip += 1
        elif op == "mul":
            regs[x] = val(x) * val(y)
            ip += 1
        elif op == "mod":
            regs[x] = val(x) % val(y)
            ip += 1
        elif op == "rcv":
            if val(x) != 0:
                sys.stdout.write(str(last_sound) + "\n")
                return
            ip += 1
        elif op == "jgz":
            if val(x) > 0:
                ip += val(y)
            else:
                ip += 1
        else:
            # Unknown instruction; terminate safely
            break

if __name__ == "__main__":
    main()

