import sys
from collections import deque, defaultdict

def parse_instructions(lines):
    instrs = []
    for line in lines:
        line = line.strip()
        if not line:
            continue
        parts = line.split()
        op = parts[0]
        if op in ("snd", "rcv"):
            x = parts[1]
            instrs.append((op, x, None))
        else:
            x, y = parts[1], parts[2]
            instrs.append((op, x, y))
    return instrs

def is_register(tok):
    return tok is not None and len(tok) == 1 and tok.isalpha()

def value(tok, regs):
    if is_register(tok):
        return regs[tok]
    return int(tok)

def run_duet(instructions):
    n = len(instructions)

    regs0 = defaultdict(int)
    regs1 = defaultdict(int)
    regs0['p'] = 0
    regs1['p'] = 1

    q0 = deque()
    q1 = deque()

    ip0 = 0
    ip1 = 0
    waiting0 = False
    waiting1 = False
    terminated0 = False
    terminated1 = False

    send_count_1 = 0

    while True:
        # Execute one step for program 0
        if not terminated0:
            if ip0 < 0 or ip0 >= n:
                terminated0 = True
            else:
                op, x, y = instructions[ip0]
                if op == "snd":
                    v = value(x, regs0)
                    q1.append(v)
                    ip0 += 1
                elif op == "set":
                    regs0[x] = value(y, regs0)
                    ip0 += 1
                elif op == "add":
                    regs0[x] += value(y, regs0)
                    ip0 += 1
                elif op == "mul":
                    regs0[x] *= value(y, regs0)
                    ip0 += 1
                elif op == "mod":
                    regs0[x] %= value(y, regs0)
                    ip0 += 1
                elif op == "rcv":
                    if not q0:
                        waiting0 = True
                    else:
                        regs0[x] = q0.popleft()
                        waiting0 = False
                        ip0 += 1
                elif op == "jgz":
                    if value(x, regs0) > 0:
                        ip0 += value(y, regs0)
                    else:
                        ip0 += 1

        # Execute one step for program 1
        if not terminated1:
            if ip1 < 0 or ip1 >= n:
                terminated1 = True
            else:
                op, x, y = instructions[ip1]
                if op == "snd":
                    v = value(x, regs1)
                    q0.append(v)
                    ip1 += 1
                    send_count_1 += 1
                elif op == "set":
                    regs1[x] = value(y, regs1)
                    ip1 += 1
                elif op == "add":
                    regs1[x] += value(y, regs1)
                    ip1 += 1
                elif op == "mul":
                    regs1[x] *= value(y, regs1)
                    ip1 += 1
                elif op == "mod":
                    regs1[x] %= value(y, regs1)
                    ip1 += 1
                elif op == "rcv":
                    if not q1:
                        waiting1 = True
                    else:
                        regs1[x] = q1.popleft()
                        waiting1 = False
                        ip1 += 1
                elif op == "jgz":
                    if value(x, regs1) > 0:
                        ip1 += value(y, regs1)
                    else:
                        ip1 += 1

        # Deadlock detection: both waiting on rcv with empty queues
        if (not terminated0 and waiting0 and not q0) and (not terminated1 and waiting1 and not q1):
            break
        if terminated0 and terminated1:
            break

        # If one terminated, the other may still be able to proceed; continue loop.
        # waiting flags should remain true only when blocked; they are set only when queue empty.

    return send_count_1

def main():
    instructions = parse_instructions(sys.stdin.read().splitlines())
    ans = run_duet(instructions)
    print(ans)

if __name__ == "__main__":
    main()

