import sys

def solve():
    lines = sys.stdin.read().splitlines()
    if not lines:
        return

    h = len(lines)
    w = max(len(line) for line in lines) if lines else 0
    grid = [list(line.ljust(w)) for line in lines]

    # Find starting column: the only '|' in the top row
    start_c = None
    for c, ch in enumerate(grid[0]):
        if ch == '|':
            start_c = c
            break
    if start_c is None:
        print("")
        return

    r, c = 0, start_c
    dr, dc = 1, 0  # initial direction: down

    ans = []

    def in_bounds(rr, cc):
        return 0 <= rr < h and 0 <= cc < w

    while True:
        r += dr
        c += dc
        if not in_bounds(r, c):
            break

        ch = grid[r][c]
        if ch == ' ':
            break
        if 'A' <= ch <= 'Z':
            ans.append(ch)

        if ch == '+':
            # Turn left/right (if moving vertically) or up/down (if moving horizontally)
            if dr != 0:  # moving vertically, perpendicular are left/right
                candidates = [(0, -1), (0, 1)]
            else:  # moving horizontally, perpendicular are up/down
                candidates = [(-1, 0), (1, 0)]

            chosen = None
            for ndr, ndc in candidates:
                nr, nc = r + ndr, c + ndc
                if in_bounds(nr, nc) and grid[nr][nc] != ' ':
                    chosen = (ndr, ndc)
                    break
            if chosen is None:
                break
            dr, dc = chosen

    sys.stdout.write("".join(ans))

if __name__ == "__main__":
    solve()

