import sys

def solve():
    lines = [line.strip() for line in sys.stdin.read().splitlines()]
    instructions = []
    for line in lines:
        if not line:
            continue
        parts = line.split()
        if len(parts) != 3:
            continue
        instructions.append((parts[0], parts[1], parts[2]))

    registers = {}

    def value(tok: str) -> int:
        if len(tok) == 1 and tok.isalpha():
            return registers.get(tok, 0)
        return int(tok)

    ip = 0
    mul_count = 0

    while 0 <= ip < len(instructions):
        op, x, y = instructions[ip]

        if op == "set":
            registers[x] = value(y)
            ip += 1
        elif op == "sub":
            registers[x] = value(x) - value(y)
            ip += 1
        elif op == "mul":
            registers[x] = value(x) * value(y)
            mul_count += 1
            ip += 1
        elif op == "jnz":
            if value(x) != 0:
                ip += value(y)
            else:
                ip += 1
        else:
            ip += 1

    sys.stdout.write(str(mul_count))

