from functools import lru_cache

def solve_part2(components):
    n = len(components)
    if n == 0:
        return 0

    # Build adjacency: for each port value, list component indices that contain it
    by_port = {}
    for i, (a, b) in enumerate(components):
        by_port.setdefault(a, []).append(i)
        by_port.setdefault(b, []).append(i)

    @lru_cache(maxsize=None)
    def dfs(cur, mask):
        best_len = 0
        best_strength = 0

        for i in by_port.get(cur, []):
            if (mask >> i) & 1:
                continue
            a, b = components[i]
            next_cur = b if a == cur else a
            new_mask = mask | (1 << i)

            len2, str2 = dfs(next_cur, new_mask)
            cand_len = 1 + len2
            cand_strength = (a + b) + str2

            if cand_len > best_len or (cand_len == best_len and cand_strength > best_strength):
                best_len = cand_len
                best_strength = cand_strength

        return best_len, best_strength

    _, ans_strength = dfs(0, 0)
    return ans_strength

