    comps = []
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        a_str, b_str = line.split('/')
        comps.append((int(a_str), int(b_str)))

    print(solve_part2(comps))

if __name__ == "__main__":
    main()

