import sys
import re

def solve(log_text: str) -> int:
    logs = [line.strip() for line in log_text.splitlines() if line.strip()]
    records = []

    # Example:
    # [1518-11-01 00:00] Guard #10 begins shift
    # [1518-11-01 00:05] falls asleep
    # [1518-11-01 00:25] wakes up
    line_re = re.compile(
        r"\[(\d+)-(\d+)-(\d+)\s+(\d+):(\d+)\]\s+(.*)$"
    )
    guard_re = re.compile(r"Guard #(\d+) begins shift")

    for line in logs:
        m = line_re.match(line)
        if not m:
            continue
        year, month, day, hour, minute = map(int, m.group(1, 2, 3, 4, 5))
        rest = m.group(6)

        time_key = (year, month, day, hour, minute)

        if "begins shift" in rest:
            gm = guard_re.search(rest)
            guard_id = int(gm.group(1)) if gm else None
            records.append({"time": time_key, "type": "begins", "guard": guard_id, "minute": None})
        elif "falls asleep" in rest:
            records.append({"time": time_key, "type": "sleep", "guard": None, "minute": minute})
        elif "wakes up" in rest:
            records.append({"time": time_key, "type": "wake", "guard": None, "minute": minute})

    records.sort(key=lambda r: r["time"])

    totalSleep = {}
    freq = {}

    def ensure_guard(gid: int):
        if gid not in totalSleep:
            totalSleep[gid] = 0
            freq[gid] = [0] * 60

    currentGuard = None
    sleepStartMinute = None

    for r in records:
        if r["type"] == "begins":
            currentGuard = r["guard"]
            ensure_guard(currentGuard)
        elif r["type"] == "sleep":
            sleepStartMinute = r["minute"]
        elif r["type"] == "wake":
            wakeMinute = r["minute"]
            ensure_guard(currentGuard)
            for m in range(sleepStartMinute, wakeMinute):
                freq[currentGuard][m] += 1
                totalSleep[currentGuard] += 1

    # Strategy 1: guard with most total minutes asleep
    guardBest = None
    bestTotal = -1
    for gid, t in totalSleep.items():
        if t > bestTotal:
            bestTotal = t
            guardBest = gid

    # Minute most frequently asleep for that guard
    minuteBest = 0
    bestFreq = -1
    for m in range(60):
        if freq[guardBest][m] > bestFreq:
            bestFreq = freq[guardBest][m]
            minuteBest = m

    return guardBest * minuteBest


if __name__ == "__main__":
    input_text = sys.stdin.read()
    print(solve(input_text))

