import sys

def fully_react(polymer: str) -> int:
    stack = []
    for ch in polymer:
        if stack:
            top = stack[-1]
            # React if same letter ignoring case and opposite polarity (case differs)
            if top != ch and top.lower() == ch.lower() and (top.islower() != ch.islower()):
                stack.pop()
            else:
                stack.append(ch)
        else:
            stack.append(ch)
    return len(stack)

