import sys

def reacts(a: str, b: str) -> bool:
    # React if same type ignoring case, but opposite polarity (one upper, one lower)
    return a.lower() == b.lower() and (a.isupper() != b.isupper())

def fully_reduce_skip_type(s: str, skip_type: str) -> int:
    st = []
    for ch in s:
        if ch.lower() == skip_type:
            continue
