                    d = 'U'
                    track[y][x] = '|'
                elif c == 'v':
                    d = 'D'
                    track[y][x] = '|'
                elif c == '<':
                    d = 'L'
                    track[y][x] = '-'
                else:  # '>'
                    d = 'R'
                    track[y][x] = '-'
                carts.append([x, y, d, 0])  # turn=0 means left first
            else:
                if c in '|-/\\+':
                    track[y][x] = c
                else:
                    track[y][x] = ' '

    # Occupancy map: occ[y][x] = cart id or -1
    occ = [[-1 for _ in range(w)] for _ in range(h)]
    for i, (x, y, _, _) in enumerate(carts):
        occ[y][x] = i

    def turn_left(d):
        return {'U': 'L', 'L': 'D', 'D': 'R', 'R': 'U'}[d]

    def turn_right(d):
        return {'U': 'R', 'R': 'D', 'D': 'L', 'L': 'U'}[d]

    def move_delta(d):
        return dir_map[d]

    while True:
        order = sorted(range(len(carts)), key=lambda i: (carts[i][1], carts[i][0]))
        for i in order:
            x, y, d, t = carts[i]

            # Remove from occupancy before moving
            occ[y][x] = -1

            dx, dy = move_delta(d)
            nx, ny = x + dx, y + dy

            # Collision check
            if occ[ny][nx] != -1:
                print(f"{nx},{ny}")
                return

            # Move cart
            carts[i][0] = nx
            carts[i][1] = ny

            piece = track[ny][nx]
            if piece == '/':
                # U->R, R->U, D->L, L->D
                d = {'U': 'R', 'R': 'U', 'D': 'L', 'L': 'D'}[d]
            elif piece == '\\':
                # U->L, L->U, D->R, R->D
                d = {'U': 'L', 'L': 'U', 'D': 'R', 'R': 'D'}[d]
            elif piece == '+':
                # turn: 0 left, 1 straight, 2 right
                if t == 0:
                    d = turn_left(d)
                elif t == 2:
                    d = turn_right(d)
                t = (t + 1) % 3
                carts[i][3] = t
            # else: '|' or '-' keep direction

            carts[i][2] = d
            occ[ny][nx] = i

