import sys

def solve():
    lines = [line.rstrip("\n") for line in sys.stdin.readlines()]
    if not lines:
        return

    H = len(lines)
    W = max(len(s) for s in lines)

    # Build track grid (pad with spaces for ragged input)
    track = [[' ' for _ in range(W)] for _ in range(H)]
    carts = []  # each cart: dict with x,y,dir,turn,alive
    dir_map = {'^': 'U', 'v': 'D', '<': 'L', '>': 'R'}

    for y in range(H):
        row = lines[y]
        for x in range(len(row)):
            ch = row[x]
            if ch in dir_map:
                carts.append({
                    'x': x, 'y': y,
                    'dir': dir_map[ch],
                    'turn': 0,  # 0=left,1=straight,2=right
                    'alive': True
                })
                # Normalize underlying track
                if ch in '^v':
                    track[y][x] = '|'
                else:
                    track[y][x] = '-'
            else:
                track[y][x] = ch

    # Movement deltas
    delta = {
        'U': (0, -1),
        'D': (0, 1),
        'L': (-1, 0),
        'R': (1, 0),
    }

    # Curve mappings
    # '/' : U->R, R->U, D->L, L->D
    curve_slash = {'U': 'R', 'R': 'U', 'D': 'L', 'L': 'D'}
    # '\' : U->L, L->U, D->R, R->D
    curve_back = {'U': 'L', 'L': 'U', 'D': 'R', 'R': 'D'}

    # Intersection turn: left, straight, right repeating
    # We'll implement by rotating direction accordingly.
    left_turn = {'U': 'L', 'L': 'D', 'D': 'R', 'R': 'U'}
    right_turn = {'U': 'R', 'R': 'D', 'D': 'L', 'L': 'U'}

    occupied = {}  # (x,y) -> cart index
    for i, c in enumerate(carts):
        occupied[(c['x'], c['y'])] = i

    alive_count = sum(1 for c in carts if c['alive'])

    while alive_count > 1:
        # Reading order: top to bottom, then left to right
        order = sorted(
            (i for i, c in enumerate(carts) if c['alive']),
            key=lambda i: (carts[i]['y'], carts[i]['x'])
        )

        for i in order:
            c = carts[i]
            if not c['alive']:
                continue

            # Remove current position from occupied
            pos = (c['x'], c['y'])
            occupied.pop(pos, None)

            dx, dy = delta[c['dir']]
            nx, ny = c['x'] + dx, c['y'] + dy
            npos = (nx, ny)

            if npos in occupied:
                # Collision: remove both carts immediately
                j = occupied.pop(npos)
                carts[j]['alive'] = False
                c['alive'] = False
                alive_count -= 2
                continue

            # No collision: move cart
            c['x'], c['y'] = nx, ny
            occupied[npos] = i

            piece = track[ny][nx]
            if piece == '+':
                if c['turn'] == 0:
                    c['dir'] = left_turn[c['dir']]
                elif c['turn'] == 2:
                    c['dir'] = right_turn[c['dir']]
                # turn_state 1 => straight (no change)
                c['turn'] = (c['turn'] + 1) % 3
            elif piece == '/':
                c['dir'] = curve_slash[c['dir']]
            elif piece == '\\':
                c['dir'] = curve_back[c['dir']]
            # else: '-' or '|' => direction unchanged

    # Find remaining cart
    for c in carts:
        if c['alive']:
            sys.stdout.write(f"{c['x']},{c['y']}")
            return

if __name__ == "__main__":
    solve()

