import sys
from collections import deque

DIRS = [(-1, 0), (0, -1), (0, 1), (1, 0)]  # up, left, right, down for reading-order tie behavior
ADJ4 = [(-1, 0), (0, -1), (0, 1), (1, 0)]


def reading_order(pos):
    r, c = pos
    return (r, c)


class Unit:
    __slots__ = ("uid", "typ", "r", "c", "hp", "atk", "alive")

    def __init__(self, uid, typ, r, c, hp=200, atk=3):
        self.uid = uid
        self.typ = typ
        self.r = r
        self.c = c
        self.hp = hp
        self.atk = atk
        self.alive = True


def bfs_dist(start_r, start_c, grid_open, occupied, R, C):
    """BFS distances from (start_r,start_c) over open cells, treating occupied as blocked except start."""
    INF = -1
    dist = [[INF] * C for _ in range(R)]
    q = deque()
    dist[start_r][start_c] = 0
    q.append((start_r, start_c))

    while q:
        r, c = q.popleft()
        nd = dist[r][c] + 1
        for dr, dc in ADJ4:
            nr, nc = r + dr, c + dc
            if not (0 <= nr < R and 0 <= nc < C):
                continue
            if not grid_open[nr][nc]:
                continue
            if dist[nr][nc] != INF:
                continue
            # occupied blocks movement, except the start cell itself
            if occupied[nr][nc] is not None and not (nr == start_r and nc == start_c):
                continue
            dist[nr][nc] = nd
            q.append((nr, nc))
    return dist


def adjacent_enemies(unit, units, occupied, R, C):
    enemies = []
    for dr, dc in ADJ4:
        nr, nc = unit.r + dr, unit.c + dc
        if 0 <= nr < R and 0 <= nc < C:
            idx = occupied[nr][nc]
            if idx is not None:
                v = units[idx]
                if v.alive and v.typ != unit.typ:
                    enemies.append(v)
    return enemies


def in_range_squares(units, unit, grid_open, occupied, R, C):
    """Return set of open squares adjacent to any enemy."""
    targets = set()
    for v in units:
        if v.alive and v.typ != unit.typ:
            for dr, dc in ADJ4:
                nr, nc = v.r + dr, v.c + dc
                if 0 <= nr < R and 0 <= nc < C and grid_open[nr][nc] and occupied[nr][nc] is None:
                    targets.add((nr, nc))
    return targets


def simulate(grid_lines):
    R = len(grid_lines)
    C = len(grid_lines[0].rstrip("\n"))

    grid_open = [[False] * C for _ in range(R)]
    units = []
    occupied = [[None] * C for _ in range(R)]

    uid = 0
    for r, line in enumerate(grid_lines):
        line = line.rstrip("\n")
        for c, ch in enumerate(line):
            if ch == "#":
                grid_open[r][c] = False
            else:
                grid_open[r][c] = True
                if ch in ("E", "G"):
                    u = Unit(uid, ch, r, c)
                    units.append(u)
                    occupied[r][c] = uid
                    uid += 1

    def alive_units_of_type(t):
        return [u for u in units if u.alive and u.typ == t]

    rounds_completed = 0
    while True:
        # snapshot turn order at start of round
        turn_list = [u for u in units if u.alive]
        if not turn_list:
            break
        turn_list.sort(key=lambda u: reading_order((u.r, u.c)))

        # check combat end at start of each unit's turn
        for u in turn_list:
            if not u.alive:
                continue
            enemies_exist = any(v.alive and v.typ != u.typ for v in units)
            if not enemies_exist:
                # combat ends immediately; do not count this partial round
                remaining_hp = sum(v.hp for v in units if v.alive)
                return rounds_completed * remaining_hp

            # determine if already adjacent to an enemy
            enemies = adjacent_enemies(u, units, occupied, R, C)
            if not enemies:
                # movement
                targets = in_range_squares(units, u, grid_open, occupied, R, C)
                if targets:
                    dist = bfs_dist(u.r, u.c, grid_open, occupied, R, C)
                    # choose destination
                    best_d = None
                    best_dest = None
                    for tr, tc in targets:
                        d = dist[tr][tc]
                        if d == -1:
                            continue
                        if best_d is None or d < best_d or (d == best_d and reading_order((tr, tc)) < reading_order(best_dest)):
                            best_d = d
                            best_dest = (tr, tc)

                    if best_dest is not None:
                        # choose step: run BFS from destination to compute dist2
                        dr, dc = best_dest
                        dist2 = bfs_dist(dr, dc, grid_open, occupied, R, C)
                        # among neighbors of u, pick one that minimizes dist2 (closest to destination)
                        candidates = []
                        for nr, nc in ADJ4:
                            pass
                        # Use reading order for step tie-breaking: up, left, right, down corresponds to reading order
                        best_step_d2 = None
                        best_step = None
                        for dr2, dc2 in ADJ4:
                            nr, nc = u.r + dr2, u.c + dc2
                            if not (0 <= nr < R and 0 <= nc < C):
                                continue
                            if not grid_open[nr][nc]:
                                continue
                            if occupied[nr][nc] is not None:
                                continue
                            d2 = dist2[nr][nc]
                            if d2 == -1:
                                continue
                            if best_step_d2 is None or d2 < best_step_d2 or (d2 == best_step_d2 and reading_order((nr, nc)) < reading_order(best_step)):
                                best_step_d2 = d2
                                best_step = (nr, nc)

                        if best_step is not None:
                            nr, nc = best_step
                            occupied[u.r][u.c] = None
                            u.r, u.c = nr, nc
                            occupied[u.r][u.c] = u.uid

                # after movement, update enemies
                enemies = adjacent_enemies(u, units, occupied, R, C)

            # attack if possible
            if enemies:
                # choose target: min hp, then reading order
                enemies.sort(key=lambda v: (v.hp, v.r, v.c))
                target = enemies[0]
                target.hp -= u.atk
                if target.hp <= 0:
                    target.alive = False
                    occupied[target.r][target.c] = None

        rounds_completed += 1


def main():
    lines = sys.stdin.read().splitlines()
    if not lines:
        return
    print(simulate(lines))


if __name__ == "__main__":
    main()

