import sys

def solve(pattern: str) -> int:
    p = [ord(c) - 48 for c in pattern.strip()]
    m = len(p)

    scores = [3, 7]
    i1, i2 = 0, 1

    def check_start(start: int) -> bool:
        if start < 0 or start + m > len(scores):
            return False
        for k in range(m):
            if scores[start + k] != p[k]:
                return False
        return True

    while True:
        s = scores[i1] + scores[i2]
        if s >= 10:
            scores.append(s // 10)
            # After appending first digit, only matches ending at the last digit could be new,
            # but the pattern length is fixed; we check candidate starts that could have just completed.
            if len(scores) >= m:
                start = len(scores) - m
                if check_start(start):
                    return start

            scores.append(s % 10)
            if len(scores) >= m:
                # Match ending at last digit
                start1 = len(scores) - m
                if check_start(start1):
                    return start1
                # Match ending at second-last digit (only possible because we appended two digits)
                start2 = len(scores) - m - 1
                if check_start(start2):
                    return start2
        else:
            scores.append(s)
            if len(scores) >= m:
                start = len(scores) - m
                if check_start(start):
                    return start

        i1 = (i1 + 1 + scores[i1]) % len(scores)
        i2 = (i2 + 1 + scores[i2]) % len(scores)

def main():
    pattern = sys.stdin.readline().strip()
    print(solve(pattern))

if __name__ == "__main__":
    main()

