import sys
from collections import deque

def solve(regex: str):
    regex = regex.strip()
    if regex.startswith('^'):
        regex = regex[1:]
    if regex.endswith('$'):
        regex = regex[:-1]

    # Adjacency list for the implicit graph of rooms (coordinates).
    adj = {}  # (x,y) -> set of neighboring (x,y)

    def add_edge(a, b):
        if a not in adj:
            adj[a] = set()
        if b not in adj:
            adj[b] = set()
        adj[a].add(b)
        adj[b].add(a)

    # Direction deltas
    delta = {
        'N': (0, -1),
        'S': (0, 1),
        'E': (1, 0),
        'W': (-1, 0),
    }

    start = (0, 0)
    current = {start}

    # Stack frames for groups: (start_set, accum_set)
    stack = []

    for ch in regex:
        if ch in delta:
            dx, dy = delta[ch]
            nxt = set()
            for (x, y) in current:
                a = (x, y)
                b = (x + dx, y + dy)
                add_edge(a, b)
                nxt.add(b)
            current = nxt
        elif ch == '(':
            stack.append((current, set()))
        elif ch == '|':
            # Finish current alternative: add its end positions to accum,
            # then reset to the group's start positions.
            start_set, accum_set = stack[-1]
            accum_set.update(current)
            current = set(start_set)
            stack[-1] = (start_set, accum_set)
        elif ch == ')':
            # Finish last alternative and close group.
            start_set, accum_set = stack.pop()
            accum_set.update(current)
            current = accum_set
        else:
            # Should not happen for valid inputs (only N,S,E,W,(,),|)
            pass

    # BFS for shortest paths from start
    dist = {start: 0}
    q = deque([start])

    while q:
        u = q.popleft()
        du = dist[u]
        for v in adj.get(u, ()):
            if v not in dist:
                dist[v] = du + 1
                q.append(v)

    ans1 = max(dist.values()) if dist else 0
    ans2 = sum(1 for d in dist.values() if d >= 1000)
    return ans1, ans2

def main():
    data = sys.stdin.read().strip()
    if not data:
        return
    ans1, ans2 = solve(data)
    sys.stdout.write(f"{ans1}\n{ans2}\n")

if __name__ == "__main__":
    main()

