def parse_input():
    lines = [line.strip() for line in sys.stdin.read().splitlines() if line.strip()]
    depth = None
    tx = ty = None
    for line in lines:
        if line.startswith("depth:"):
            depth = int(line.split(":")[1].strip())
        elif line.startswith("target:"):
            rest = line.split(":")[1].strip()
            a, b = rest.split(",")
            tx, ty = int(a), int(b)
    return depth, tx, ty

def solve(depth, tx, ty):
    # Conservative bounds: optimal path is known to stay within a limited region.
    # Use a robust margin; if needed, increase.
    margin = 200
    maxX = tx + margin
    maxY = ty + margin

    MOD = 20183

    # Precompute erosion and region type for all cells in bounds.
    erosion = [[0] * (maxX + 1) for _ in range(maxY + 1)]
    rtype = [[0] * (maxX + 1) for _ in range(maxY + 1)]  # 0 rocky, 1 wet, 2 narrow

    for y in range(maxY + 1):
        for x in range(maxX + 1):
            if (x == 0 and y == 0) or (x == tx and y == ty):
                gi = 0
            elif y == 0:
                gi = x * 16807
            elif x == 0:
                gi = y * 48271
            else:
                gi = erosion[y][x - 1] * erosion[y - 1][x]
            e = (gi + depth) % MOD
            erosion[y][x] = e
            rtype[y][x] = e % 3

    # Tools: 0=Torch, 1=Climbing gear, 2=Neither
    TORCH, GEAR, NEITHER = 0, 1, 2

    # Allowed tools per region type:
    # rocky(0): Torch or Gear
    # wet(1): Gear or Neither
    # narrow(2): Torch or Neither
    allowed = {
        0: (TORCH, GEAR),
        1: (GEAR, NEITHER),
        2: (TORCH, NEITHER),
    }

    def tool_allowed(tool, region_type):
        # region_type in {0,1,2}
        return tool in allowed[region_type]

    INF = 10**18
    dist = [[[INF] * 3 for _ in range(maxX + 1)] for __ in range(maxY + 1)]
    dist[0][0][TORCH] = 0

    pq = [(0, 0, 0, TORCH)]  # (time, x, y, tool)

    # Dijkstra
    dirs = [(1, 0), (-1, 0), (0, 1), (0, -1)]
    while pq:
        d, x, y, tool = heapq.heappop(pq)
        if d != dist[y][x][tool]:
            continue
        if x == tx and y == ty and tool == TORCH:
            return d

        # Move to adjacent cells
        for dx, dy in dirs:
            nx, ny = x + dx, y + dy
            if 0 <= nx <= maxX and 0 <= ny <= maxY:
                if tool_allowed(tool, rtype[ny][nx]):
                    nd = d + 1
                    if nd < dist[ny][nx][tool]:
                        dist[ny][nx][tool] = nd
                        heapq.heappush(pq, (nd, nx, ny, tool))

        # Switch tools in the same cell (cost 7)
        cur_type = rtype[y][x]
        for new_tool in (TORCH, GEAR, NEITHER):
            if new_tool != tool and tool_allowed(new_tool, cur_type):
                nd = d + 7
                if nd < dist[y][x][new_tool]:
                    dist[y][x][new_tool] = nd
                    heapq.heappush(pq, (nd, x, y, new_tool))

    # Should always find within bounds; if not, increase bounds and retry.
    # Fallback (rare): expand and rerun once.
    margin2 = 400
    maxX2 = tx + margin2
    maxY2 = ty + margin2
    erosion2 = [[0] * (maxX2 + 1) for _ in range(maxY2 + 1)]
    rtype2 = [[0] * (maxX2 + 1) for _ in range(maxY2 + 1)]
    for y in range(maxY2 + 1):
        for x in range(maxX2 + 1):
            if (x == 0 and y == 0) or (x == tx and y == ty):
                gi = 0
            elif y == 0:
                gi = x * 16807
            elif x == 0:
                gi = y * 48271
            else:
                gi = erosion2[y][x - 1] * erosion2[y - 1][x]
            e = (gi + depth) % MOD
            erosion2[y][x] = e
            rtype2[y][x] = e % 3

    dist2 = [[[INF] * 3 for _ in range(maxX2 + 1)] for __ in range(maxY2 + 1)]
    dist2[0][0][TORCH] = 0
    pq = [(0, 0, 0, TORCH)]
    while pq:
        d, x, y, tool = heapq.heappop(pq)
        if d != dist2[y][x][tool]:
            continue
        if x == tx and y == ty and tool == TORCH:
            return d
        for dx, dy in dirs:
            nx, ny = x + dx, y + dy
            if 0 <= nx <= maxX2 and 0 <= ny <= maxY2:
                if tool_allowed(tool, rtype2[ny][nx]):
                    nd = d + 1
                    if nd < dist2[ny][nx][tool]:
                        dist2[ny][nx][tool] = nd
                        heapq.heappush(pq, (nd, nx, ny, tool))
        cur_type = rtype2[y][x]
        for new_tool in (TORCH, GEAR, NEITHER):
            if new_tool != tool and tool_allowed(new_tool, cur_type):
                nd = d + 7
                if nd < dist2[y][x][new_tool]:
                    dist2[y][x][new_tool] = nd
                    heapq.heappush(pq, (nd, x, y, new_tool))

    return None

