                nd = d + 7
                if nd < dist2[y][x][new_tool]:
                    dist2[y][x][new_tool] = nd
                    heapq.heappush(pq, (nd, x, y, new_tool))

    return None

def main():
    depth, tx, ty = parse_input()
    ans = solve(depth, tx, ty)
    print(ans)

