import re

def solve(data: str) -> str:
    nanobots = []
    pattern = re.compile(r'pos=<\s*(-?\d+)\s*,\s*(-?\d+)\s*,\s*(-?\d+)\s*>\s*,\s*r=\s*(-?\d+)\s*')

    for line in data.splitlines():
