import sys
import re
from dataclasses import dataclass
from typing import List, Tuple

ATTACK_TYPES = ["radiation", "bludgeoning", "slashing", "fire", "cold"]
TYPE_TO_BIT = {t: 1 << i for i, t in enumerate(ATTACK_TYPES)}

@dataclass
class Group:
    units: int
    hp: int
    atk: int
    atk_type_bit: int
    init: int
    weak_mask: int
    immune_mask: int

def parse_input(data: str) -> Tuple[List[Group], List[Group]]:
    lines = [ln.rstrip() for ln in data.splitlines() if ln.strip()]
    immune_groups: List[Group] = []
    infection_groups: List[Group] = []

    army = None
    pat = re.compile(
        r"(\d+) units each with (\d+) hit points(?: \(([^)]*)\))? with an attack that does (\d+) (\w+) damage at initiative (\d+)"
    )

    for ln in lines:
        if ln.startswith("Immune System:"):
            army = 0
            continue
        if ln.startswith("Infection:"):
            army = 1
            continue

        m = pat.match(ln)
        if not m:
            continue

        units = int(m.group(1))
        hp = int(m.group(2))
        special = m.group(3)
        atk = int(m.group(4))
        atk_type = m.group(5)
        init = int(m.group(6))

        weak_mask = 0
        immune_mask = 0
        if special:
            parts = [p.strip() for p in special.split(";")]
            for p in parts:
                if p.startswith("weak to "):
                    for x in p[len("weak to "):].split(","):
                        weak_mask |= TYPE_TO_BIT[x.strip()]
                elif p.startswith("immune to "):
                    for x in p[len("immune to "):].split(","):
                        immune_mask |= TYPE_TO_BIT[x.strip()]

        g = Group(
            units=units,
            hp=hp,
            atk=atk,
            atk_type_bit=TYPE_TO_BIT[atk_type],
            init=init,
            weak_mask=weak_mask,
            immune_mask=immune_mask,
        )
        if army == 0:
            immune_groups.append(g)
        else:
            infection_groups.append(g)

    return immune_groups, infection_groups

def simulate(immune0: List[Group], infection0: List[Group], boost: int) -> Tuple[bool, int]:
    immune = [
        Group(g.units, g.hp, g.atk + boost, g.atk_type_bit, g.init, g.weak_mask, g.immune_mask)
        for g in immune0
    ]
    infection = [
        Group(g.units, g.hp, g.atk, g.atk_type_bit, g.init, g.weak_mask, g.immune_mask)
        for g in infection0
    ]

    def damage_multiplier(att_type_bit: int, defender: Group) -> int:
        if defender.immune_mask & att_type_bit:
            return 0
        if defender.weak_mask & att_type_bit:
            return 2
        return 1

    while True:
        imm_alive = [i for i, g in enumerate(immune) if g.units > 0]
        inf_alive = [i for i, g in enumerate(infection) if g.units > 0]

        if not imm_alive:
            return False, 0
        if not inf_alive:
            return True, sum(immune[i].units for i in imm_alive)

        # Effective powers precomputed for alive groups
        imm_ep = {i: immune[i].units * immune[i].atk for i in imm_alive}
        inf_ep = {i: infection[i].units * infection[i].atk for i in inf_alive}

        # Target selection
        # Attackers sorted by (effective power desc, initiative desc)
        attackers = []
        for i in imm_alive:
            attackers.append((imm_ep[i], immune[i].init, 0, i))
        for i in inf_alive:
            attackers.append((inf_ep[i], infection[i].init, 1, i))
        attackers.sort(key=lambda x: (x[0], x[1]), reverse=True)

        chosen_def = set()  # defender indices across both sides, encoded as (side, idx)
        target = {}         # (att_side, att_idx) -> (def_side, def_idx)

        for _, _, att_side, att_idx in attackers:
            if att_side == 0:
                att = immune[att_idx]
                att_ep = imm_ep[att_idx]
                best = None  # (dmg, def_ep, def_init, def_side, def_idx)
                for didx in inf_alive:
                    if ("I", didx) in chosen_def:
                        continue
                    mult = damage_multiplier(att.atk_type_bit, infection[didx])
                    if mult == 0:
                        continue
                    dmg = att_ep * mult
                    cand = (dmg, inf_ep[didx], infection[didx].init, 1, didx)
                    if best is None or cand > best:
                        best = cand
                if best is not None:
                    _, _, _, def_side, def_idx = best
                    chosen_def.add(("I", def_idx))
                    target[(0, att_idx)] = (def_side, def_idx)
            else:
                att = infection[att_idx]
                att_ep = inf_ep[att_idx]
                best = None
                for didx in imm_alive:
                    if ("M", didx) in chosen_def:
                        continue
                    mult = damage_multiplier(att.atk_type_bit, immune[didx])
                    if mult == 0:
                        continue
                    dmg = att_ep * mult
                    cand = (dmg, imm_ep[didx], immune[didx].init, 0, didx)
                    if best is None or cand > best:
                        best = cand
                if best is not None:
                    _, _, _, def_side, def_idx = best
                    chosen_def.add(("M", def_idx))
                    target[(1, att_idx)] = (def_side, def_idx)

        # Attacking phase
        # Groups attack in decreasing initiative across both armies
        attack_order = []
        for i in imm_alive:
            attack_order.append((immune[i].init, 0, i))
        for i in inf_alive:
            attack_order.append((infection[i].init, 1, i))
        attack_order.sort(key=lambda x: x[0], reverse=True)

        total_killed = 0

        for _, att_side, att_idx in attack_order:
            # Attacker might have died earlier in the round
            if att_side == 0:
                if immune[att_idx].units <= 0:
                    continue
                att = immune[att_idx]
                att_ep = att.units * att.atk
            else:
                if infection[att_idx].units <= 0:
                    continue
                att = infection[att_idx]
                att_ep = att.units * att.atk

            if (att_side, att_idx) not in target:
                continue

            def_side, def_idx = target[(att_side, att_idx)]
            if def_side == 0:
                deff = immune[def_idx]
            else:
                deff = infection[def_idx]

            if deff.units <= 0:
                continue

            mult = damage_multiplier(att.atk_type_bit, deff)
            if mult == 0:
                continue

            dmg = att_ep * mult
            killed = dmg // deff.hp
            if killed > deff.units:
                killed = deff.units

            if killed > 0:
                deff.units -= killed
                total_killed += killed

        # Stalemate detection
        if total_killed == 0:
            return False, 0

def find_min_boost(immune: List[Group], infection: List[Group]) -> int:
    def immune_wins(b: int) -> bool:
        win, _ = simulate(immune, infection, b)
        return win

    lo = 0
    hi = 1
    while not immune_wins(hi):
        hi *= 2

    while lo < hi:
        mid = (lo + hi) // 2
        if immune_wins(mid):
            hi = mid
        else:
            lo = mid + 1
    return lo

def main():
    data = sys.stdin.read()
    immune, infection = parse_input(data)
    boost = find_min_boost(immune, infection)
    win, remaining = simulate(immune, infection, boost)
    print(remaining if win else 0)

if __name__ == "__main__":
    main()

