import sys

class DSU:
    def __init__(self, n: int):
        self.parent = list(range(n))
        self.size = [1] * n

    def find(self, x: int) -> int:
        while self.parent[x] != x:
            self.parent[x] = self.parent[self.parent[x]]
            x = self.parent[x]
        return x

    def union(self, a: int, b: int) -> None:
        ra = self.find(a)
        rb = self.find(b)
        if ra == rb:
            return
        if self.size[ra] < self.size[rb]:
            ra, rb = rb, ra
        self.parent[rb] = ra
        self.size[ra] += self.size[rb]

def solve(points):
    n = len(points)
    if n == 0:
        return 0

    dsu = DSU(n)

    for i in range(n):
        x1, y1, z1, w1 = points[i]
        for j in range(i + 1, n):
            x2, y2, z2, w2 = points[j]
            dist = abs(x1 - x2) + abs(y1 - y2) + abs(z1 - z2) + abs(w1 - w2)
            if dist <= 3:
                dsu.union(i, j)

    roots = set()
    for i in range(n):
        roots.add(dsu.find(i))
    return len(roots)

def main():
    points = []
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        parts = line.split(',')
        if len(parts) != 4:
            continue
        x, y, z, w = map(int, parts)
        points.append((x, y, z, w))

    result = solve(points)
    print(result)

if __name__ == "__main__":
    main()

