import sys

def one_step_fuel(m: int) -> int:
    # Fuel required for a module of mass m: floor(m/3) - 2, clamped to 0
    return max(0, m // 3 - 2)

def total_fuel_with_fuel(masses):
    total = 0
    for m in masses:
        current = m
        module_total = 0
        while True:
            fuel = one_step_fuel(current)
            if fuel == 0:
                break
            module_total += fuel
            current = fuel
        total += module_total
    return total

def main():
    # Read all non-empty lines from stdin as module masses
    data = sys.stdin.read().strip().splitlines()
    masses = [int(line.strip()) for line in data if line.strip() != ""]
    print(total_fuel_with_fuel(masses))

if __name__ == "__main__":
    main()

