import sys

def run_intcode(memory):
    ip = 0
    while True:
        opcode = memory[ip]
        if opcode == 99:
            return memory[0]
        if opcode == 1 or opcode == 2:
            a_pos = memory[ip + 1]
            b_pos = memory[ip + 2]
            out_pos = memory[ip + 3]
            a = memory[a_pos]
            b = memory[b_pos]
            memory[out_pos] = a + b if opcode == 1 else a * b
            ip += 4
        else:
            raise ValueError(f"Unknown opcode {opcode} at position {ip}")

def main():
    data = sys.stdin.read().strip()
    if not data:
        return
    program = [int(x) for x in data.replace('\n', '').split(',')]

    target = 19690720
    for noun in range(100):
        for verb in range(100):
            memory = program.copy()
            memory[1] = noun
            memory[2] = verb
            if run_intcode(memory) == target:
                print(100 * noun + verb)
                return

    # If not found (shouldn't happen for valid inputs)
    print(-1)

if __name__ == "__main__":
