import sys

def parse_moves(line: str):
    line = line.strip()
    if not line:
        return []
    tokens = line.split(',')
    moves = []
    for t in tokens:
        t = t.strip()
        if not t:
            continue
        d = t[0]
        n = int(t[1:])
        moves.append((d, n))
    return moves

def solve():
    data = [line.strip() for line in sys.stdin.read().splitlines() if line.strip() != ""]
    if len(data) < 2:
        return
    lineA, lineB = data[0], data[1]

    movesA = parse_moves(lineA)
    movesB = parse_moves(lineB)

    # Walk wire A and store all visited points (excluding origin)
    visitedA = set()
    x = y = 0
    for d, n in movesA:
        for _ in range(n):
            if d == 'R':
                x += 1
            elif d == 'L':
                x -= 1
            elif d == 'U':
                y += 1
            elif d == 'D':
                y -= 1
            if (x, y) != (0, 0):
                visitedA.add((x, y))

    # Walk wire B and find closest intersection by Manhattan distance
    best = None
    x = y = 0
    for d, n in movesB:
        for _ in range(n):
            if d == 'R':
                x += 1
            elif d == 'L':
                x -= 1
            elif d == 'U':
                y += 1
            elif d == 'D':
                y -= 1

            if (x, y) == (0, 0):
                continue  # origin does not count

            if (x, y) in visitedA:
                dist = abs(x) + abs(y)
                if best is None or dist < best:
                    best = dist

    if best is None:
        best = 0
    print(best)

if __name__ == "__main__":
    solve()

