def parse_wire(line: str):
    line = line.strip()
    if not line:
        return []
    return line.split(',')

def solve():
    lines = [ln.strip() for ln in sys.stdin.read().splitlines() if ln.strip() != ""]
    if len(lines) < 2:
        return

    wire1 = parse_wire(lines[0])
    wire2 = parse_wire(lines[1])

    # Part Two: fewest combined steps to an intersection
    visited1_first_steps = {}  # (x,y) -> first steps to reach
    x = y = 0
    steps = 0

    dir_map = {
        'R': (1, 0),
        'L': (-1, 0),
        'U': (0, 1),
        'D': (0, -1),
    }

    for token in wire1:
        d = token[0]
        n = int(token[1:])
        dx, dy = dir_map[d]
        for _ in range(n):
            x += dx
            y += dy
            steps += 1
            if (x, y) != (0, 0) and (x, y) not in visited1_first_steps:
                visited1_first_steps[(x, y)] = steps

    visited2_first_steps = {}
    x = y = 0
    steps = 0
    best = float('inf')

    for token in wire2:
        d = token[0]
        n = int(token[1:])
        dx, dy = dir_map[d]
        for _ in range(n):
            x += dx
            y += dy
            steps += 1
            if (x, y) == (0, 0):
                continue
            if (x, y) not in visited2_first_steps:
                visited2_first_steps[(x, y)] = steps
                if (x, y) in visited1_first_steps:
                    total = visited1_first_steps[(x, y)] + steps
                    if total < best:
                        best = total

    if best == float('inf'):
        best = 0
    print(best)

