import sys
from functools import lru_cache

def count_valid(bound: int) -> int:
    if bound < 0:
        return 0

    digits = list(map(int, f"{bound:06d}"))  # pad to 6 digits
    n = 6

    @lru_cache(maxsize=None)
    def dp(pos: int, last: int, run_len: int, has_exact_two: int, started: int, tight: int) -> int:
        if pos == n:
            if not started:
                return 0  # ignore 0 (not a 6-digit password in the given range)
            # close the last run
            if run_len == 2:
                return 1 if has_exact_two or 1 else 0
            return 1 if has_exact_two else 0

        limit = digits[pos] if tight else 9
        total = 0

        for d in range(0, limit + 1):
            ntight = 1 if (tight and d == limit) else 0

            if not started:
                if d == 0:
                    # still not started; keep run tracking neutral
                    total += dp(pos + 1, 0, 0, has_exact_two, 0, ntight)
                else:
                    # start number
                    total += dp(pos + 1, d, 1, has_exact_two, 1, ntight)
            else:
                # non-decreasing constraint
                if d < last:
                    continue

                if d == last:
                    total += dp(pos + 1, last, run_len + 1, has_exact_two, 1, ntight)
                else:
                    # run ended; check if it was exactly 2
                    new_has = has_exact_two or (1 if run_len == 2 else 0)
                    total += dp(pos + 1, d, 1, new_has, 1, ntight)

        return total

    return dp(0, 0, 0, 0, 0, 1)

def solve():
    line = sys.stdin.readline().strip()
    if not line:
        return
    low_s, high_s = line.split('-')
    L = int(low_s)
    R = int(high_s)
    if L > R:
        L, R = R, L

    ans = count_valid(R) - count_valid(L - 1)
    sys.stdout.write(str(ans))

if __name__ == "__main__":
    solve()

