import sys

def solve():
    parent = {}
    nodes = set()

    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        a, b = line.split(')')
        parent[b] = a
        nodes.add(a)
        nodes.add(b)

    dist = {"COM": 0}

    # Compute distance to COM for each node using iterative walk + memoization
    for node in nodes:
        if node in dist:
            continue
        path = []
        cur = node
        while cur not in dist:
            path.append(cur)
            if cur == "COM":
                dist[cur] = 0
                break
            cur = parent[cur]
        # Back-propagate distances along the walked path
        base = dist[cur] if cur in dist else 0
        for i in range(len(path) - 1, -1, -1):
            base += 1
            dist[path[i]] = base

    total = 0
    for node in nodes:
        total += dist.get(node, 0)

    sys.stdout.write(str(total))

if __name__ == "__main__":
    solve()

