import sys
from collections import deque
from itertools import permutations


class IntcodeComputer:
    def __init__(self, program):
        self.mem = program[:]  # private memory
        self.ip = 0
        self.halted = False
        self.input_q = deque()
        self.output_last = None

    def add_input(self, value: int):
        self.input_q.append(value)

    def _get_param(self, offset: int, mode: int) -> int:
        val = self.mem[self.ip + offset]
        if mode == 0:  # position
            return self.mem[val]
        elif mode == 1:  # immediate
            return val
        elif mode == 2:  # relative (not needed for Day 7, but harmless)
            return self.mem[self.rel_base + val]
        else:
            raise ValueError("Unknown parameter mode")

    def _get_write_addr(self, offset: int, mode: int) -> int:
        val = self.mem[self.ip + offset]
        if mode == 0:  # position
            return val
        elif mode == 2:  # relative
            return self.rel_base + val
        else:
            raise ValueError("Invalid mode for write parameter")

    def run_until_output_or_halt(self):
        # Day 7 uses only position/immediate, but keep relative base support.
        if not hasattr(self, "rel_base"):
            self.rel_base = 0

        while True:
            instr = self.mem[self.ip]
            opcode = instr % 100
            modes = instr // 100

            def mode_at(k: int) -> int:
                return (modes // (10 ** (k - 1))) % 10

            if opcode == 99:
                self.halted = True
                return None

            if opcode in (1, 2, 7, 8):
                a = self._get_param(1, mode_at(1))
                b = self._get_param(2, mode_at(2))
                out_addr = self._get_write_addr(3, mode_at(3))
                if opcode == 1:
                    self.mem[out_addr] = a + b
                elif opcode == 2:
                    self.mem[out_addr] = a * b
                elif opcode == 7:
                    self.mem[out_addr] = 1 if a < b else 0
                else:  # opcode == 8
                    self.mem[out_addr] = 1 if a == b else 0
                self.ip += 4

            elif opcode == 3:
                if not self.input_q:
                    return None  # need more input
                out_addr = self._get_write_addr(1, mode_at(1))
                self.mem[out_addr] = self.input_q.popleft()
                self.ip += 2

            elif opcode == 4:
                out = self._get_param(1, mode_at(1))
                self.output_last = out
                self.ip += 2
                return out

            elif opcode in (5, 6):
                a = self._get_param(1, mode_at(1))
                b = self._get_param(2, mode_at(2))
                if opcode == 5:
                    self.ip = b if a != 0 else self.ip + 3
                else:
                    self.ip = b if a == 0 else self.ip + 3

            else:
                raise ValueError(f"Unknown opcode {opcode} at ip={self.ip}")


def solve_part2(program):
    best = -10**18
    for phases in permutations(range(5, 10), 5):
        amps = [IntcodeComputer(program) for _ in range(5)]
        for i, p in enumerate(phases):
            amps[i].add_input(p)
        amps[0].add_input(0)

        last_e_output = None
        halted = [False] * 5

        while True:
            for i in range(5):
                if halted[i]:
                    continue
                out = amps[i].run_until_output_or_halt()
                if out is None:
                    if amps[i].halted:
                        halted[i] = True
                    continue
