                    continue
                nxt = (i + 1) % 5
                amps[nxt].add_input(out)
                if i == 4:
                    last_e_output = out

            if halted[4]:
                break

        if last_e_output is not None and last_e_output > best:
            best = last_e_output

    return best


def main():
    data = sys.stdin.read().strip()
    if not data:
        return
    program = list(map(int, data.split(",")))
    ans = solve_part2(program)
    print(ans)


