def solve():
    s = sys.stdin.read().strip()
    if not s:
        return

    candidates = [(25, 6), (3, 2)]
    chosen = None
    for W, H in candidates:
        layerSize = W * H
        if len(s) % layerSize == 0:
            chosen = (W, H)
            break

    # If none divide evenly, default to the real puzzle dimensions.
    if chosen is None:
        W, H = 25, 6
    else:
        W, H = chosen

    layerSize = W * H

    # If input is shorter than one full layer, treat it as one layer.
    if len(s) < layerSize:
        numLayers = 1
    else:
        numLayers = len(s) // layerSize

    bestZeroCount = float('inf')
    bestLayerStart = 0

    for i in range(numLayers):
        start = i * layerSize
        end = min(start + layerSize, len(s))
        zeroCount = sum(1 for ch in s[start:end] if ch == '0')
        if zeroCount < bestZeroCount:
            bestZeroCount = zeroCount
            bestLayerStart = start

    end = min(bestLayerStart + layerSize, len(s))
    count1 = sum(1 for ch in s[bestLayerStart:end] if ch == '1')
    count2 = sum(1 for ch in s[bestLayerStart:end] if ch == '2')

    print(count1 * count2)

if __name__ == "__main__":
    solve()

