import sys
from collections import defaultdict, deque

# ---------------- Intcode Computer ----------------

class Intcode:
    def __init__(self, program):
        self.mem = defaultdict(int)
        for i, v in enumerate(program):
            self.mem[i] = v
        self.ip = 0
        self.rb = 0
        self.halted = False

    def _get(self, mode, param):
        if mode == 0:   # position
            return self.mem[param]
        elif mode == 1: # immediate
            return param
        elif mode == 2: # relative
            return self.mem[self.rb + param]
        else:
            raise ValueError("Unknown mode")

    def _addr(self, mode, param):
        if mode == 0:
            return param
        elif mode == 2:
            return self.rb + param
        else:
            raise ValueError("Invalid address mode")

    def run(self, inputs):
        """
        inputs: iterable of ints
        returns: list of outputs
        """
        inp = deque(inputs)
        out = []

        while True:
            op = self.mem[self.ip]
            opcode = op % 100
            modes = [(op // 100) % 10, (op // 1000) % 10, (op // 10000) % 10]

            if opcode == 99:
                self.halted = True
                break

            if opcode in (1, 2, 7, 8):
                a = self._get(modes[0], self.mem[self.ip + 1])
                b = self._get(modes[1], self.mem[self.ip + 2])
                dest = self._addr(modes[2], self.mem[self.ip + 3])
                if opcode == 1:
                    self.mem[dest] = a + b
                elif opcode == 2:
                    self.mem[dest] = a * b
                elif opcode == 7:
                    self.mem[dest] = 1 if a < b else 0
                elif opcode == 8:
                    self.mem[dest] = 1 if a == b else 0
                self.ip += 4

            elif opcode == 3:
                dest = self._addr(modes[0], self.mem[self.ip + 1])
                if not inp:
                    # If input is missing, pause-like behavior isn't required by this puzzle.
                    # But to be safe, treat as 0.
                    val = 0
                else:
                    val = inp.popleft()
                self.mem[dest] = val
                self.ip += 2

            elif opcode == 4:
                val = self._get(modes[0], self.mem[self.ip + 1])
                out.append(val)
                self.ip += 2

            elif opcode in (5, 6):
                a = self._get(modes[0], self.mem[self.ip + 1])
                b = self._get(modes[1], self.mem[self.ip + 2])
                if opcode == 5:
                    self.ip = b if a != 0 else self.ip + 3
                else:
                    self.ip = b if a == 0 else self.ip + 3

            elif opcode == 9:
                a = self._get(modes[0], self.mem[self.ip + 1])
                self.rb += a
                self.ip += 2

            else:
                raise ValueError(f"Unknown opcode {opcode} at ip {self.ip}")

        return out


# ---------------- Parsing camera output ----------------

DIRS = {
    '^': (0, -1),
    'v': (0, 1),
    '<': (-1, 0),
    '>': (1, 0),
}

def parse_camera_output(outputs):
    grid = {}
    robot_pos = None
    robot_dir = None

    x = 0
    y = 0
    for v in outputs:
        if v == 10:  # newline
            y += 1
            x = 0
            continue
        ch = chr(v)
        if ch in DIRS:
            robot_pos = (x, y)
            robot_dir = ch
            grid[(x, y)] = '#'
        elif ch == '#':
            grid[(x, y)] = '#'
        elif ch == '.':
            grid[(x, y)] = '.'
        else:
            # Unexpected ASCII; ignore
            grid[(x, y)] = '.'
        x += 1

    return grid, robot_pos, robot_dir


def alignment_sum(grid):
    # intersections: scaffold with all 4 neighbors scaffold
    xs = [p[0] for p in grid.keys()]
    ys = [p[1] for p in grid.keys()]
    if not xs or not ys:
        return 0
    minx, maxx = min(xs), max(xs)
    miny, maxy = min(ys), max(ys)

    def is_scaffold(p):
        return grid.get(p) == '#'

    s = 0
    for y in range(miny, maxy + 1):
        for x in range(minx, maxx + 1):
            if is_scaffold((x, y)) and is_scaffold((x - 1, y)) and is_scaffold((x + 1, y)) and is_scaffold((x, y - 1)) and is_scaffold((x, y + 1)):
                s += x * y
    return s


# ---------------- Path extraction ----------------

def turn_left(dch):
    # order: up, left, down, right (counterclockwise)
    return {'^': '<', '<': 'v', 'v': '>', '>': '^'}[dch]

def turn_right(dch):
    return {'^': '>', '>': 'v', 'v': '<', '<': '^'}[dch]

def move_forward(pos, dch):
    dx, dy = DIRS[dch]
    return (pos[0] + dx, pos[1] + dy)

def extract_tokens(grid, robot_pos, robot_dir):
    # Follow scaffold path deterministically
    def is_scaffold(p):
        return grid.get(p) == '#'

    pos = robot_pos
    dch = robot_dir
    tokens = []

    while True:
        nxt = move_forward(pos, dch)
        if is_scaffold(nxt):
            # count forward steps
            cnt = 0
            while True:
                nxt2 = move_forward(pos, dch)
                if is_scaffold(nxt2):
                    pos = nxt2
                    cnt += 1
                else:
                    break
            tokens.append(str(cnt))
            continue

        # try left
        ld = turn_left(dch)
        lpos = move_forward(pos, ld)
        if is_scaffold(lpos):
            tokens.append('L')
            dch = ld
            continue

        # try right
        rd = turn_right(dch)
        rpos = move_forward(pos, rd)
        if is_scaffold(rpos):
            tokens.append('R')
            dch = rd
            continue

        break

    return tokens


# ---------------- Compression (A/B/C) ----------------

def tokens_to_str(tok_slice):
    return ",".join(tok_slice)

def find_routines(tokens):
    # Backtracking with pruning based on 20-char limit for each routine and main routine.
    n = len(tokens)
    limit = 20

    def rec(pos, defA, defB, defC, mainCalls):
        if pos == n:
            # verify expansion
            if not mainCalls:
                return None
            main_str = ",".join(mainCalls)
            if len(main_str) > limit:
                return None
            # Expand
            expanded = []
            for c in mainCalls:
                if c == 'A':
                    expanded.extend(defA)
                elif c == 'B':
                    expanded.extend(defB)
                else:
                    expanded.extend(defC)
            if expanded == tokens:
                return defA, defB, defC, mainCalls
            return None

        # prune main length
        if mainCalls:
            if len(",".join(mainCalls)) > limit:
                return None

        # Try matching existing definitions
        for letter, d in (('A', defA), ('B', defB), ('C', defC)):
            if d is not None:
                L = len(d)
                if pos + L <= n and tokens[pos:pos+L] == d:
                    res = rec(pos + L, defA, defB, defC, mainCalls + [letter])
                    if res is not None:
                        return res

        # Define new one if needed
        # Choose next undefined in order A, B, C
        for letter in ('A', 'B', 'C'):
            if (letter == 'A' and defA is None) or (letter == 'B' and defB is None) or (letter == 'C' and defC is None):
                # generate candidates starting at pos
                # candidate slice must fit within 20 chars when comma-joined
                for end in range(pos + 1, n + 1):
                    cand = tokens[pos:end]
                    s = tokens_to_str(cand)
                    if len(s) > limit:
                        break
                    if letter == 'A':
                        res = rec(end, cand, defB, defC, mainCalls + ['A'])
                    elif letter == 'B':
                        res = rec(end, defA, cand, defC, mainCalls + ['B'])
                    else:
                        res = rec(end, defA, defB, cand, mainCalls + ['C'])
                    if res is not None:
                        return res
                # only define one new letter at a time
                return None

        return None

    # Start recursion
    return rec(0, None, None, None, [])


# ---------------- Main solve ----------------

def ascii_input_line(s):
    return [ord(ch) for ch in s]  # no newline

def ascii_line_with_newline(s):
    return [ord(ch) for ch in s] + [10]

def main():
    program_text = sys.stdin.read().strip()
    if not program_text:
        return
    program = list(map(int, program_text.split(',')))

    # Part 1: camera mode
    comp1 = Intcode(program)
    out1 = comp1.run([])

    grid, robot_pos, robot_dir = parse_camera_output(out1)
    part1 = alignment_sum(grid)

    # Part 2: movement mode
    # Wake robot: set address 0 to 2
    program2 = program[:]
    program2[0] = 2

    tokens = extract_tokens(grid, robot_pos, robot_dir)

    sol = find_routines(tokens)
    if sol is None:
        # If no solution found, still output part1 and exit
        print(part1)
        return

    defA, defB, defC, mainCalls = sol
    main_str = ",".join(mainCalls)
    A_str = tokens_to_str(defA)
    B_str = tokens_to_str(defB)
    C_str = tokens_to_str(defC)

    # Build ASCII input: main routine, A, B, C, video feed choice
    inputs = []
    inputs += ascii_line_with_newline(main_str)
    inputs += ascii_line_with_newline(A_str)
    inputs += ascii_line_with_newline(B_str)
    inputs += ascii_line_with_newline(C_str)
    inputs += ascii_line_with_newline('n')

    comp2 = Intcode(program2)
    out2 = comp2.run(inputs)

    dust = None
    for v in out2:
        if v > 255:
            dust = v
    if dust is None:
        # Sometimes dust might be last output
        dust = out2[-1] if out2 else 0

    # Output only Part 2 as typical AoC expects; but keep Part 1 if needed.
    # We'll print Part 2 only.
    print(dust)

if __name__ == "__main__":
    main()

