import sys

def solve():
    lines = [line.strip() for line in sys.stdin.read().splitlines() if line.strip() != ""]
    if len(lines) < 5:
        return
    grid = lines[:5]

    # Convert grid to 25-bit mask (row-major): bit i corresponds to (r=i//5, c=i%5)
    cur_mask = 0
    for r in range(5):
        for c in range(5):
            if grid[r][c] == '#':
                cur_mask |= 1 << (r * 5 + c)

    seen = {cur_mask}

    # Precompute neighbor indices for each cell to speed up adjacency counting
    neighbors = [[] for _ in range(25)]
    for r in range(5):
        for c in range(5):
            idx = r * 5 + c
            if r > 0:
                neighbors[idx].append((r - 1) * 5 + c)
            if r < 4:
                neighbors[idx].append((r + 1) * 5 + c)
            if c > 0:
                neighbors[idx].append(r * 5 + (c - 1))
            if c < 4:
                neighbors[idx].append(r * 5 + (c + 1))

    while True:
        next_mask = 0
        for i in range(25):
            adj = 0
            for j in neighbors[i]:
                if (cur_mask >> j) & 1:
                    adj += 1

            cur_bit = (cur_mask >> i) & 1
            if cur_bit == 1:
                # Bug dies unless exactly one adjacent bug
                if adj == 1:
                    next_mask |= 1 << i
            else:
                # Empty becomes bug if exactly one or two adjacent bugs
                if adj == 1 or adj == 2:
                    next_mask |= 1 << i

        if next_mask in seen:
            # Biodiversity rating equals the mask value with this bit mapping
            print(next_mask)
            return

        seen.add(next_mask)
        cur_mask = next_mask

if __name__ == "__main__":
    solve()

