import sys

CENTER = 12  # (2,2) in 0..24
DIRS = [(-1, 0), (1, 0), (0, -1), (0, 1)]  # up, down, left, right

def solve():
    lines = [line.strip() for line in sys.stdin if line.strip()]
    grid = lines

    init = 0
    for r in range(5):
        for c in range(5):
            if grid[r][c] == '#':
                idx = r * 5 + c
                if idx != CENTER:
                    init |= 1 << idx

    # Safe depth range for 200 minutes
    dmin, dmax = -210, 210
    offset = -dmin
    size = dmax - dmin + 1

    cur = [0] * size
    cur[offset] = init

    def idx_of(r, c):
        return r * 5 + c

    # Precompute recursive neighbors:
    # For each cell idx (except center), store list of (depth_delta, target_idx)
    neighbors = [[] for _ in range(25)]

    for r in range(5):
        for c in range(5):
            idx = idx_of(r, c)
            if idx == CENTER:
                continue

            for dr, dc in DIRS:
                nr, nc = r + dr, c + dc

                # Into center => child depth, 5 tiles along corresponding edge
                if nr == 2 and nc == 2:
                    # From above center: (1,2) -> child top row (0,0..4)
                    if dr == -1 and dc == 0:
                        for cc in range(5):
                            neighbors[idx].append((+1, idx_of(0, cc)))
                    # From below center: (3,2) -> child bottom row (4,0..4)
                    elif dr == 1 and dc == 0:
                        for cc in range(5):
                            neighbors[idx].append((+1, idx_of(4, cc)))
                    # From left of center: (2,1) -> child left column (0..4,0)
                    elif dr == 0 and dc == -1:
                        for rr in range(5):
                            neighbors[idx].append((+1, idx_of(rr, 0)))
                    # From right of center: (2,3) -> child right column (0..4,4)
                    elif dr == 0 and dc == 1:
                        for rr in range(5):
                            neighbors[idx].append((+1, idx_of(rr, 4)))
                    continue

                # Outside grid => parent depth, 1 tile adjacent to center
                if nr < 0 or nr > 4 or nc < 0 or nc > 4:
                    if nr < 0:
                        # above top edge -> parent cell (1,2)
                        neighbors[idx].append((-1, idx_of(1, 2)))
                    elif nr > 4:
                        # below bottom edge -> parent cell (3,2)
                        neighbors[idx].append((-1, idx_of(3, 2)))
                    elif nc < 0:
                        # left of left edge -> parent cell (2,1)
                        neighbors[idx].append((-1, idx_of(2, 1)))
                    else:
                        # right of right edge -> parent cell (2,3)
                        neighbors[idx].append((-1, idx_of(2, 3)))
                    continue

                # Normal neighbor within same depth
                nidx = idx_of(nr, nc)
                # nidx cannot be CENTER here because that case was handled above
                neighbors[idx].append((0, nidx))

    # Simulate 200 minutes
    for _ in range(200):
        nxt = [0] * size
        for di in range(size):
            old = cur[di]
            new_mask = 0

            for idx in range(25):
                if idx == CENTER:
                    continue
                bug = (old >> idx) & 1

                cnt = 0
                for dd, tidx in neighbors[idx]:
                    dj = di + dd
                    if 0 <= dj < size:
                        cnt += (cur[dj] >> tidx) & 1

                if bug:
                    if cnt == 1:
                        new_mask |= 1 << idx
                else:
                    if cnt == 1 or cnt == 2:
                        new_mask |= 1 << idx

            # Ensure center is empty
            new_mask &= ~(1 << CENTER)
            nxt[di] = new_mask

        cur = nxt

    ans = sum(m.bit_count() for m in cur)
    print(ans)

if __name__ == "__main__":
    solve()

