import sys

TARGET = 2020

def solve_part_two(nums, target=TARGET):
    nums.sort()
    n = len(nums)
    for i in range(n - 2):
        first = nums[i]
        target2 = target - first
        left, right = i + 1, n - 1
        while left < right:
            s = nums[left] + nums[right]
            if s == target2:
                return first * nums[left] * nums[right]
            if s < target2:
                left += 1
            else:
                right -= 1
    return None

