import sys

def count_valid_passports(text: str) -> int:
    # Step 2: Normalize whitespace to make blank-line splitting reliable
    text = text.strip()
    if not text:
        return 0

    # Step 4: Required fields (cid is optional)
    REQUIRED = {"byr", "iyr", "eyr", "hgt", "hcl", "ecl", "pid"}

    # Step 3: Split input into passport blocks separated by blank lines
    blocks = text.split("\n\n")

    valid_count = 0
    for block in blocks:
        block = block.strip()
        if not block:
            continue

        # Step 5: Extract field keys
        seen_fields = set()
        for token in block.split():
            if ":" in token:
                key, _ = token.split(":", 1)
                seen_fields.add(key)

        # Step 6: Validate passport
        if REQUIRED.issubset(seen_fields):
            valid_count += 1

    return valid_count

def main():
    data = sys.stdin.read()
    print(count_valid_passports(data))

if __name__ == "__main__":
