EYE_COLORS = {"amb", "blu", "brn", "gry", "grn", "hzl", "oth"}


def is_year_valid(s: str, lo: int, hi: int) -> bool:
    if len(s) != 4 or not s.isdigit():
        return False
    v = int(s)
    return lo <= v <= hi


def is_hgt_valid(s: str) -> bool:
    if s.endswith("cm"):
        num = s[:-2]
        if not num.isdigit():
            return False
        v = int(num)
        return 150 <= v <= 193
    if s.endswith("in"):
        num = s[:-2]
        if not num.isdigit():
            return False
        v = int(num)
        return 59 <= v <= 76
    return False


def is_hcl_valid(s: str) -> bool:
    if len(s) != 7 or s[0] != "#":
