import sys

def decode(code: str, low: int, high: int, lower_char: str, upper_char: str) -> int:
    """Decode a binary space partitioning string into an integer index."""
    for ch in code:
        mid = (low + high) // 2
        if ch == lower_char:
            high = mid
        elif ch == upper_char:
            low = mid + 1
        else:
            # Invalid character; ignore by returning current low (shouldn't happen for valid inputs)
            return low
    return low  # low == high at the end

def solve(passes):
    ids = set()
    max_id = -1
    min_id = 10**18

    for s in passes:
        s = s.strip()
        if not s:
            continue
        if len(s) != 10:
            continue  # ignore invalid lines

        row_code = s[:7]
        col_code = s[7:]

        row = decode(row_code, 0, 127, 'F', 'B')
        col = decode(col_code, 0, 7, 'L', 'R')
        seat_id = row * 8 + col

        ids.add(seat_id)
        if seat_id > max_id:
            max_id = seat_id
        if seat_id < min_id:
            min_id = seat_id

    # Part 2: find the missing seat whose neighbors exist
    missing_id = None
    for x in range(min_id + 1, max_id):
        if x not in ids and (x - 1) in ids and (x + 1) in ids:
            missing_id = x
            break

    return max_id, missing_id

def main():
    passes = []
    for line in sys.stdin:
        line = line.strip()
        if line:
            passes.append(line)

    part1, part2 = solve(passes)
    if part1 is None:
        return
    print(part1)
    if part2 is not None:
        print(part2)

if __name__ == "__main__":
    main()

