import sys
from collections import deque, defaultdict

def solve(data: str) -> int:
    lines = [line.strip() for line in data.splitlines() if line.strip()]
    if not lines:
        return 0

    reverse = defaultdict(set)  # inner_color -> set of outer_colors that can contain it

    for line in lines:
        outer, rhs = line.split(" bags contain ")
        outer = outer.strip()

        if rhs.startswith("no other bags"):
            continue

        parts = rhs.split(", ")
        for part in parts:
            part = part.strip().rstrip(".")
            # part format: "<qty> <two-word color> bag(s)"
            qty_str, rest = part.split(" ", 1)
            _qty = int(qty_str)  # quantity not needed for part 1
            # rest: "<color words> bag" or "<color words> bags"
            if rest.endswith(" bags"):
                color = rest[:-5]
            elif rest.endswith(" bag"):
                color = rest[:-4]
            else:
                color = rest
            color = color.strip()
            reverse[color].add(outer)

    target = "shiny gold"
    visited = set()
    q = deque()

    for outer in reverse.get(target, set()):
        if outer not in visited:
            visited.add(outer)
            q.append(outer)

    while q:
        cur = q.popleft()
        for prev_outer in reverse.get(cur, set()):
            if prev_outer not in visited:
                visited.add(prev_outer)
                q.append(prev_outer)

    return len(visited)

if __name__ == "__main__":
    data = sys.stdin.read()
    ans = solve(data)
    print(ans)

