import sys
from collections import Counter

def find_first_invalid(nums, preamble):
    if len(nums) <= preamble:
        return None

    window = Counter(nums[:preamble])

    for i in range(preamble, len(nums)):
        target = nums[i]
        valid = False

        for x, cx in window.items():
            y = target - x
            if y not in window:
                continue
            if x != y:
                valid = True
                break
            # x == y: need two different indices => count >= 2
            if cx >= 2:
                valid = True
                break

        if not valid:
            return target

        # slide window
        out_val = nums[i - preamble]
        window[out_val] -= 1
        if window[out_val] == 0:
            del window[out_val]
        window[target] += 1

    return None

def main():
    data = sys.stdin.read().split()
    if not data:
        return
    nums = list(map(int, data))

    # The prompt's sample corresponds to preamble length 5.
    # Use 5 for small sample-like inputs; otherwise use 25 for the real problem.
    preamble = 5 if len(nums) <= 30 else 25

    ans = find_first_invalid(nums, preamble)
    if ans is not None:
        print(ans)

if __name__ == "__main__":
    main()

