from collections import Counter

def find_invalid(a, preamble):
    for i in range(preamble, len(a)):
        target = a[i]
        window = a[i - preamble:i]
        freq = Counter(window)

        ok = False
        for x, cnt in freq.items():
            y = target - x
            if y not in freq:
                continue
            if x != y:
                ok = True
                break
            else:
                if cnt >= 2:
                    ok = True
                    break

        if not ok:
            return target
    return None

def find_weakness(a, X):
    left = 0
    s = 0
    for right in range(len(a)):
        s += a[right]
        while s > X and left <= right:
            s -= a[left]
            left += 1
        if s == X and right - left + 1 >= 2:
            sub = a[left:right+1]
            return min(sub) + max(sub)
    return None

