    a = [int(x) for x in data.strip().split()]
    if not a:
        return ""

    # Try standard AoC preamble first (25). If not found, try 5 (matches the known sample).
    invalid = find_invalid(a, 25)
    if invalid is None:
        invalid = find_invalid(a, 5)

    if invalid is None:
        return ""

    weakness = find_weakness(a, invalid)
    return str(weakness) if weakness is not None else ""

