        for r, c in seats:
            occ = 0
            for vr, vc in visible[(r, c)]:
                if current[vr][vc] == '#':
                    occ += 1

            if current[r][c] == 'L' and occ == 0:
                next_grid[r][c] = '#'
                if current[r][c] != next_grid[r][c]:
                    changed = True
            elif current[r][c] == '#' and occ >= 5:
                next_grid[r][c] = 'L'
                if current[r][c] != next_grid[r][c]:
                    changed = True
            else:
                next_grid[r][c] = current[r][c]

        # Check for changes and swap buffers
        if not changed:
            # In case we didn't detect due to assignment logic, do a quick compare on seats
            for r, c in seats:
                if next_grid[r][c] != current[r][c]:
                    changed = True
                    break

        current, next_grid = next_grid, current

    return sum(1 for r in range(R) for c in range(C) if current[r][c] == '#')


