import sys

def solve(lines):
    sx, sy = 0, 0          # ship position
    wx, wy = 10, 1         # waypoint relative to ship

    for line in lines:
        line = line.strip()
        if not line:
            continue
        action = line[0]
        value = int(line[1:])

        if action == 'N':
            wy += value
        elif action == 'S':
            wy -= value
        elif action == 'E':
            wx += value
        elif action == 'W':
            wx -= value
        elif action in ('L', 'R'):
            v = value % 360
            if action == 'R':
                turns = (v // 90) % 4  # clockwise quarter-turns
            else:  # 'L'
                turns = ((360 - v) // 90) % 4  # convert left to clockwise
            for _ in range(turns):
                # 90° clockwise rotation: (x, y) -> (y, -x)
                wx, wy = wy, -wx
        elif action == 'F':
            sx += value * wx
            sy += value * wy

    return abs(sx) + abs(sy)

def main():
    lines = sys.stdin.read().splitlines()
    print(solve(lines))

if __name__ == "__main__":
