import sys

def solve():
    lines = [line.strip() for line in sys.stdin if line.strip()]

    mem1 = {}
    mem2 = {}

    and_mask = (1 << 36) - 1  # for part 1
    or_mask = 0               # for part 1

    ones_mask = 0             # for part 2
    floating_positions = []  # bit indices (0..35) where mask has 'X'

    for line in lines:
        if line.startswith("mask = "):
            mask = line.split(" = ")[1]

            # Part 1 preprocessing: value masking
            and_mask = (1 << 36) - 1
            or_mask = 0
            for i, ch in enumerate(mask):
                bit = 35 - i
                if ch == '0':
                    and_mask &= ~(1 << bit)
                elif ch == '1':
                    or_mask |= (1 << bit)

            # Part 2 preprocessing: address masking
            ones_mask = 0
            floating_positions = []
            for i, ch in enumerate(mask):
                bit = 35 - i
                if ch == '1':
                    ones_mask |= (1 << bit)
                elif ch == 'X':
                    floating_positions.append(bit)

        else:
            # mem[addr] = value
            left, right = line.split(" = ")
            addr = int(left[left.find('[') + 1:left.find(']')])
            value = int(right)

            # Part 1 write
            masked_value = (value & and_mask) | or_mask
            mem1[addr] = masked_value

            # Part 2 write (expand floating bits)
            base_addr = addr | ones_mask
            f = len(floating_positions)
            for combo in range(1 << f):
                a = base_addr
                for j, bitpos in enumerate(floating_positions):
                    if (combo >> j) & 1:
                        a |= (1 << bitpos)
                    else:
                        a &= ~(1 << bitpos)
                mem2[a] = value

    print(sum(mem2.values()))

if __name__ == "__main__":
    solve()

