import sys

def solve(start, target=2020):
    n = len(start)
    if n >= target:
        return start[target - 1]

    last = {}  # most recent turn spoken
    prev = {}  # previous turn spoken before the most recent

    # Initialize with starting numbers (turns are 1-indexed)
    for i, x in enumerate(start):
        t = i + 1
        if x in last:
            prev[x] = last[x]
        else:
            prev[x] = None
        last[x] = t

    current = start[-1]
    turn = n  # current is spoken at 'turn'

    while turn < target:
        # Determine next number based on whether current was spoken before
        if prev[current] is None:
            next_num = 0
        else:
            next_num = last[current] - prev[current]

        turn += 1  # next_num will be spoken on this turn

        # Update state for next_num
        if next_num in last:
            prev[next_num] = last[next_num]
        else:
            prev[next_num] = None
        last[next_num] = turn

        current = next_num

    return current

def main():
    line = sys.stdin.readline().strip()
    if not line:
        return
    start = [int(x) for x in line.split(',') if x != '']
    print(solve(start, 2020))

if __name__ == "__main__":
    main()

