import sys

def solve(data: str) -> str:
    lines = [line.strip() for line in data.splitlines()]
    # Remove trailing empty lines but keep internal structure
    while lines and lines[-1] == "":
        lines.pop()

    # Split into sections by blank lines
    sections = []
    cur = []
    for line in lines:
        if line == "":
            if cur:
                sections.append(cur)
                cur = []
        else:
            cur.append(line)
    if cur:
        sections.append(cur)

    rules_section = sections[0]
    my_section = sections[1] if len(sections) > 1 else []
    nearby_section = sections[2] if len(sections) > 2 else []

    rules = []
    maxV = 0

    # Parse rules: "name: a-b or c-d"
    for line in rules_section:
        name_part, ranges_part = line.split(":")
        name = name_part.strip()
        r1, r2 = ranges_part.strip().split(" or ")
        a, b = map(int, r1.split("-"))
        c, d = map(int, r2.split("-"))
        rules.append((name, a, b, c, d))
        maxV = max(maxV, b, d)

    # Parse "your ticket" (skip the header line)
    myTicket = []
    if my_section:
        # my_section[0] is "your ticket:"
        for line in my_section[1:]:
            if line:
                myTicket = list(map(int, line.split(",")))
                break

    # Parse nearby tickets (skip the header line)
    nearbyTickets = []
    if nearby_section:
        # nearby_section[0] is "nearby tickets:"
        for line in nearby_section[1:]:
            if line:
                nearbyTickets.append(list(map(int, line.split(","))))

    # Precompute validAny[v] for v in [0..maxV]
    validAny = [False] * (maxV + 1)
    for _, a, b, c, d in rules:
        for x in range(a, b + 1):
            if 0 <= x <= maxV:
                validAny[x] = True
        for x in range(c, d + 1):
            if 0 <= x <= maxV:
                validAny[x] = True

    # Scan nearby tickets and sum invalid values
    errorRate = 0
    for ticket in nearbyTickets:
        for v in ticket:
            if v < 0 or v > maxV or not validAny[v]:
                errorRate += v

    return str(errorRate)

def main():
    data = sys.stdin.read()
    sys.stdout.write(solve(data))

if __name__ == "__main__":
    main()

