import sys

def simulate_6_cycles(initial_active):
    # Precompute 26 neighbor offsets (all combinations of -1,0,1 excluding (0,0,0))
    offsets = []
    for dx in (-1, 0, 1):
        for dy in (-1, 0, 1):
            for dz in (-1, 0, 1):
                if dx == 0 and dy == 0 and dz == 0:
                    continue
                offsets.append((dx, dy, dz))

    active = set(initial_active)

    for _ in range(6):
        neighbor_count = {}  # (x,y,z) -> number of active neighbors

        # Count active neighbors for all cells adjacent to active cubes
        for (x, y, z) in active:
            for dx, dy, dz in offsets:
                nx, ny, nz = x + dx, y + dy, z + dz
                key = (nx, ny, nz)
                neighbor_count[key] = neighbor_count.get(key, 0) + 1

        next_active = set()
        # Decide next state based on neighbor counts
        for cell, cnt in neighbor_count.items():
            if cell in active:
                if cnt == 2 or cnt == 3:
                    next_active.add(cell)
            else:
                if cnt == 3:
                    next_active.add(cell)

        active = next_active

    return len(active)

