                neighbor_count[q] = neighbor_count.get(q, 0) + 1

        next_active = set()
        # Apply rules based on neighbor counts
        for q, cnt in neighbor_count.items():
            if q in active:
                if cnt == 2 or cnt == 3:
                    next_active.add(q)
            else:
                if cnt == 3:
                    next_active.add(q)

        active = next_active

    print(len(active))

if __name__ == "__main__":
