        nonlocal i
        skip_spaces()
        if i >= n:
            return 0

        if s[i] == '(':
            i += 1  # consume '('
            val = parse_expression()
            skip_spaces()
            if i < n and s[i] == ')':
                i += 1  # consume ')'
            return val

        # parse integer
        val = 0
        while i < n and s[i].isdigit():
            val = val * 10 + (ord(s[i]) - ord('0'))
            i += 1
        return val

