import sys
from functools import lru_cache

def solve(data: str) -> str:
    lines = [line.rstrip("\n") for line in data.splitlines()]
    rules = {}
    messages = []
    parsing_rules = True

    for line in lines:
        if line.strip() == "":
            parsing_rules = False
            continue
        if parsing_rules:
            # Format: id: "a"  OR  id: 1 2 | 3 4
            left, right = line.split(": ", 1)
            rid = int(left)
            right = right.strip()
            if right.startswith('"') and right.endswith('"'):
                rules[rid] = right[1]  # terminal char
            else:
                alts = []
                for part in right.split(" | "):
                    seq = [int(x) for x in part.split()]
                    alts.append(seq)
                rules[rid] = alts
        else:
            if line.strip() != "":
                messages.append(line.strip())

    # Determine which rule is terminal/non-terminal by type
    def is_terminal(rule_id: int) -> bool:
        return isinstance(rules[rule_id], str)

    total = 0
    for msg in messages:
        n = len(msg)

        @lru_cache(maxsize=None)
        def match(rule_id: int, i: int):
            # Returns a set of end indices j such that rule_id matches msg[i:j]
            if i > n:
                return frozenset()

            if is_terminal(rule_id):
                ch = rules[rule_id]
                if i < n and msg[i] == ch:
                    return frozenset((i + 1,))
                return frozenset()

            result = set()
            for seq in rules[rule_id]:
                current = {i}
                for sub in seq:
                    nxt = set()
                    for p in current:
                        nxt.update(match(sub, p))
                    current = nxt
                    if not current:
                        break
                result.update(current)
            return frozenset(result)

        ends = match(0, 0)
        if n in ends:
            total += 1

    return str(total)

def main():
    data = sys.stdin.read()
    sys.stdout.write(solve(data))

if __name__ == "__main__":
    main()

