import sys
import math
from collections import defaultdict

def rotate_grid(g):
    # g: list[str], square
    n = len(g)
    return [''.join(g[n - 1 - r][c] for r in range(n)) for c in range(n)]

def flip_grid(g):
    # horizontal flip (mirror left-right)
    return [row[::-1] for row in g]

def all_orientations(grid):
    # Generate 8 orientations: 4 rotations of original, then 4 rotations of flipped
    seen = []
    cur = grid
    for _ in range(4):
        seen.append(cur)
        cur = rotate_grid(cur)
    cur = flip_grid(grid)
    for _ in range(4):
        seen.append(cur)
        cur = rotate_grid(cur)
    # Ensure uniqueness (in case of symmetric tiles)
    uniq = []
    for x in seen:
        if not any(x == y for y in uniq):
            uniq.append(x)
    return uniq

def borders_of(grid):
    n = len(grid)
    top = grid[0]
    bottom = grid[-1]
    left = ''.join(grid[i][0] for i in range(n))
    right = ''.join(grid[i][-1] for i in range(n))
    return top, right, bottom, left  # (top, right, bottom, left)

def reverse_border(b):
    return b[::-1]

def parse_input(lines):
    tiles = {}
    i = 0
    while i < len(lines):
        line = lines[i].strip()
        if not line:
            i += 1
            continue
        if not line.startswith("Tile "):
            raise ValueError("Unexpected input line: " + line)
        tid = int(line[5:-1])
        i += 1
        grid = []
        while i < len(lines) and lines[i].strip() != "":
            grid.append(lines[i].strip())
            i += 1
        tiles[tid] = grid
    return tiles

def solve_part2(tiles):
    T = len(tiles)
    side = int(math.isqrt(T))
    # AoC guarantees square
    any_tile = next(iter(tiles.values()))
    S = len(any_tile)

    # Precompute orientations and borders
    # orientations[tid] = list of oriented grids
    orientations = {}
    borders = {}  # borders[tid][k] = (top, right, bottom, left)
    for tid, grid in tiles.items():
        ori = all_orientations(grid)
        orientations[tid] = ori
        b_list = []
        for g in ori:
            b_list.append(borders_of(g))
        borders[tid] = b_list

    # border_map[border_string] = set of (tid, k)
    border_map = defaultdict(set)
    for tid in tiles.keys():
        for k, b in enumerate(borders[tid]):
            top, right, bottom, left = b
            for s in (top, right, bottom, left):
                border_map[s].add((tid, k))
                border_map[reverse_border(s)].add((tid, k))

    # Determine corners for assembly start
    # A border is "unique" if it appears in border_map only for this tile (across all orientations)
    # We'll compute uniqueness by checking whether any other tile can match that border.
    # For each tile, for each orientation, count unique borders.
    tile_ids = list(tiles.keys())
    corner_candidates = []
    for tid in tile_ids:
        for k in range(len(orientations[tid])):
            top, right, bottom, left = borders[tid][k]
            uniq_count = 0
            for s in (top, right, bottom, left):
                candidates = border_map[s]
                # Determine if any candidate belongs to a different tile
                other_tiles = {t for (t, kk) in candidates if t != tid}
                if not other_tiles:
                    uniq_count += 1
            if uniq_count == 2:
                corner_candidates.append((tid, k))
    if not corner_candidates:
        raise RuntimeError("No corner candidates found")

    # Choose a starting corner orientation with unique top and left borders
    start = None
    for tid, k in corner_candidates:
        top, right, bottom, left = borders[tid][k]
        if len({t for (t, kk) in border_map[top] if t != tid}) == 0 and len({t for (t, kk) in border_map[left] if t != tid}) == 0:
            start = (tid, k)
            break
    if start is None:
        start = corner_candidates[0]

    # Assembly with backtracking + pruning
    used = {tid: False for tid in tile_ids}
    placement = [[None for _ in range(side)] for _ in range(side)]  # (tid, k)

    # Precompute for each tid,k its borders for quick access
    def get_b(tid, k):
        return borders[tid][k]

    # Candidate generation helper
    def candidates_for(pos_r, pos_c, req_top, req_left):
        # Filter by required top and left if present
        cand = None
        if req_top is not None:
            cand = set(border_map[req_top])
        else:
            cand = {(tid, k) for tid in tile_ids for k in range(len(orientations[tid]))}
        if req_left is not None:
            cand2 = set(border_map[req_left])
            cand = cand & cand2
        # Remove used tiles
        cand = {(tid, k) for (tid, k) in cand if not used[tid]}
        # Edge constraints
        for (tid, k) in list(cand):
            top, right, bottom, left = get_b(tid, k)
            if pos_r == 0:
                if len({t for (t, kk) in border_map[top] if t != tid}) != 0:
                    cand.discard((tid, k))
                    continue
            if pos_c == 0:
                if len({t for (t, kk) in border_map[left] if t != tid}) != 0:
                    cand.discard((tid, k))
                    continue
            if pos_r == side - 1:
                if len({t for (t, kk) in border_map[bottom] if t != tid}) != 0:
                    cand.discard((tid, k))
                    continue
            if pos_c == side - 1:
                if len({t for (t, kk) in border_map[right] if t != tid}) != 0:
                    cand.discard((tid, k))
                    continue
        return list(cand)

    # Backtracking
    sys.setrecursionlimit(1000000)

    def backtrack(idx):
        if idx == side * side:
            return True
        r = idx // side
        c = idx % side

        if placement[r][c] is not None:
            return backtrack(idx + 1)

        req_top = None
        req_left = None
        if r > 0:
            tid_up, k_up = placement[r - 1][c]
            _, _, bottom_up, _ = get_b(tid_up, k_up)
            req_top = bottom_up
        if c > 0:
            tid_left, k_left = placement[r][c - 1]
            _, right_left, _, _ = get_b(tid_left, k_left)
            req_left = right_left

        cand = candidates_for(r, c, req_top, req_left)
        # Deterministic ordering: try orientations with matching borders already implied
        # (no further scoring needed)
        for tid, k in cand:
            # Verify exact adjacency matches (safety)
            if r > 0:
                tid_up, k_up = placement[r - 1][c]
                top, right, bottom, left = get_b(tid, k)
                _, _, bottom_up, _ = get_b(tid_up, k_up)
                if top != bottom_up:
                    continue
            if c > 0:
                tid_l, k_l = placement[r][c - 1]
                top, right, bottom, left = get_b(tid, k)
                _, right_l, _, _ = get_b(tid_l, k_l)
                if left != right_l:
                    continue

            placement[r][c] = (tid, k)
            used[tid] = True
            if backtrack(idx + 1):
                return True
            used[tid] = False
            placement[r][c] = None
        return False

    tid0, k0 = start
    placement[0][0] = (tid0, k0)
    used[tid0] = True
    ok = backtrack(1)
    if not ok:
        raise RuntimeError("Failed to assemble jigsaw")

    # Stitch full image removing borders
    inner = S - 2
    H = side * inner
    W = side * inner
    image = [['.' for _ in range(W)] for _ in range(H)]
    for r in range(side):
        for c in range(side):
            tid, k = placement[r][c]
            g = orientations[tid][k]
            for ir in range(1, S - 1):
                for ic in range(1, S - 1):
                    image[r * inner + (ir - 1)][c * inner + (ic - 1)] = g[ir][ic]

    image = [''.join(row) for row in image]

    # Sea monster pattern
    monster = [
        "                  # ",
        "#    ##    ##    ###",
        " #  #  #  #  #  #   ",
    ]
    mh = len(monster)
    mw = len(monster[0])
    monster_cells = []
    for dr in range(mh):
        for dc in range(mw):
            if monster[dr][dc] == '#':
                monster_cells.append((dr, dc))

    def count_hash(img):
        return sum(row.count('#') for row in img)

    total_hash = count_hash(image)

    # Search in all 8 orientations
    for img in all_orientations(image):
        H2 = len(img)
        W2 = len(img[0])
        marked = [[False] * W2 for _ in range(H2)]
        found = 0
        for r0 in range(H2 - mh + 1):
            for c0 in range(W2 - mw + 1):
                okm = True
                for dr, dc in monster_cells:
                    if img[r0 + dr][c0 + dc] != '#':
                        okm = False
                        break
                if okm:
                    found += 1
                    for dr, dc in monster_cells:
                        marked[r0 + dr][c0 + dc] = True
        if found > 0:
            marked_hash = sum(1 for r in range(H2) for c in range(W2) if marked[r][c] and img[r][c] == '#')
            roughness = total_hash - marked_hash
            return roughness

    raise RuntimeError("No sea monsters found")

def main():
    lines = sys.stdin.read().splitlines()
    tiles = parse_input(lines)
    ans = solve_part2(tiles)
    print(ans)

if __name__ == "__main__":
    main()

