import sys
from collections import defaultdict

def solve(lines):
    candidates = {}  # allergen -> set of possible ingredients
    freq = defaultdict(int)

    foods = []  # list of (set(ingredients), list(allergens))
    for line in lines:
        line = line.strip()
        if not line:
            continue
        left, right = line.split(" (contains ")
        ingredients = left.split()
        allergens = right[:-1].split(", ") if right.endswith(")") else right.split(", ")

        ing_set = set(ingredients)
        for ing in ingredients:
            freq[ing] += 1

        foods.append((ing_set, allergens))

        for a in allergens:
            if a not in candidates:
                candidates[a] = set(ing_set)
            else:
                candidates[a] &= ing_set

    # Constraint propagation to resolve allergen -> ingredient uniquely
    resolved = {}  # allergen -> ingredient
    # Work on mutable copies
    cand = {a: set(s) for a, s in candidates.items()}

    while len(resolved) < len(cand):
        progress = False
        for a in sorted(cand.keys()):
            if a in resolved:
                continue
            if len(cand[a]) == 1:
                ing = next(iter(cand[a]))
                resolved[a] = ing
                progress = True
                # Remove this ingredient from all other allergen candidate sets
                for a2 in cand.keys():
                    if a2 != a and a2 not in resolved:
                        cand[a2].discard(ing)
        if not progress:
            # Should not happen with valid inputs; break to avoid infinite loop
            break

    # Canonical dangerous ingredient list: ingredients ordered by allergen alphabetically
    out = ",".join(resolved[a] for a in sorted(resolved.keys()))
    return out

def main():
    lines = sys.stdin.read().splitlines()
    print(solve(lines))

if __name__ == "__main__":
    main()

