import sys

def parse_directions(line: str):
    i = 0
    n = len(line)
    tokens = []
    while i < n:
        c = line[i]
        if c == 'e' or c == 'w':
            tokens.append(c)
            i += 1
        else:
            # c is 'n' or 's', next char completes the token
            tokens.append(c + line[i + 1])
            i += 2
    return tokens

def solve(lines):
    # Axial coordinates (q, r) with neighbor vectors:
    # e  -> (+1, 0)
    # w  -> (-1, 0)
    # ne -> (+1, -1)
    # nw -> (0, -1)
    # se -> (0, +1)
    # sw -> (-1, +1)
    dirs = {
        'e': (1, 0),
        'w': (-1, 0),
        'ne': (1, -1),
        'nw': (0, -1),
        'se': (0, 1),
        'sw': (-1, 1),
    }

    black = set()

    # Part 1: apply flips
    for line in lines:
        q = r = 0
        for tok in parse_directions(line):
            dq, dr = dirs[tok]
            q += dq
            r += dr
        coord = (q, r)
        if coord in black:
            black.remove(coord)
        else:
            black.add(coord)

    # Part 2: simulate 100 days
    for _ in range(100):
        cnt = {}
        # Count black neighbors for all tiles adjacent to black tiles
        for q, r in black:
            for dq, dr in dirs.values():
                nq, nr = q + dq, r + dr
                cnt[(nq, nr)] = cnt.get((nq, nr), 0) + 1

        next_black = set()
        for coord, k in cnt.items():
            if coord in black:
                if k == 1 or k == 2:
                    next_black.add(coord)
            else:
                if k == 2:
                    next_black.add(coord)
        black = next_black

    return len(black)

def main():
    lines = [line.strip() for line in sys.stdin.read().splitlines() if line.strip()]
    print(solve(lines))

if __name__ == "__main__":
    main()

