import sys

def solve(nums):
    if not nums:
        return 0

    n = len(nums)
    m = len(nums[0])

    ones_count = [0] * m

    # Count number of '1's in each bit position
    for s in nums:
        for i, ch in enumerate(s):
            if ch == '1':
                ones_count[i] += 1

    gamma = 0
    epsilon = 0

    # Determine gamma (most common) and epsilon (least common) per position
    for i in range(m):
        ones = ones_count[i]
        zeros = n - ones
        bit_weight = 1 << (m - 1 - i)

        if ones > zeros:
            gamma += bit_weight
        else:
            # Tie or zeros more common => gamma bit is 0, epsilon bit is 1
            epsilon += bit_weight

    return gamma * epsilon

def main():
    nums = [line.strip() for line in sys.stdin if line.strip()]
    result = solve(nums)
    print(result)

