import sys

def parse_input(lines):
    lines = [line.rstrip("\n") for line in lines]
    # Find first non-empty line for draws
    i = 0
    while i < len(lines) and lines[i].strip() == "":
        i += 1
    draws = list(map(int, lines[i].strip().split(",")))
    i += 1

    boards = []
    while i < len(lines):
        # Skip blank lines
        while i < len(lines) and lines[i].strip() == "":
            i += 1
        if i >= len(lines):
            break

        grid = []
        for _ in range(5):
            if i >= len(lines):
                break
            row = list(map(int, lines[i].split()))
            grid.append(row)
            i += 1
        if len(grid) == 5 and all(len(r) == 5 for r in grid):
            boards.append(grid)
        else:
            # In case of malformed input, stop parsing
            break

    return draws, boards

def solve():
    draws, boards = parse_input(sys.stdin.readlines())

    board_states = []
    for grid in boards:
        pos_map = {}
        unmarked_sum = 0
        for r in range(5):
            for c in range(5):
                val = grid[r][c]
                pos_map[val] = (r, c)
                unmarked_sum += val
        state = {
            "pos": pos_map,
            "row": [0] * 5,
            "col": [0] * 5,
            "sum": unmarked_sum,
            "won": False
        }
        board_states.append(state)

    for x in draws:
        for state in board_states:
            if state["won"]:
                continue
            if x not in state["pos"]:
                continue
            r, c = state["pos"][x]
            state["row"][r] += 1
            state["col"][c] += 1
            state["sum"] -= x

            if state["row"][r] == 5 or state["col"][c] == 5:
                print(state["sum"] * x)
                return

if __name__ == "__main__":
    solve()

