def simulate_lanternfish(timers, days):
    # count[t] = number of fish with internal timer value t (0..8)
    count = [0] * 9
    for t in timers:
        count[t] += 1

    for _ in range(days):
        births = count[0]
        nxt = [0] * 9
        # Shift timers down by 1
        for t in range(8):
            nxt[t] = count[t + 1]
        # Timer 6 resets from births; timer 8 are new fish
        nxt[6] += births
