import sys
from collections import deque

def solve():
    lines = [line.strip() for line in sys.stdin if line.strip() != ""]
    if not lines:
        return

    grid = [[int(ch) for ch in line] for line in lines]
    R = len(grid)
    C = len(grid[0])

    # Ensure rectangular input
    for row in grid:
        if len(row) != C:
            raise ValueError("Invalid input: non-rectangular grid")

    def neighbors(r, c):
        if r > 0:
            yield r - 1, c
        if r + 1 < R:
            yield r + 1, c
        if c > 0:
            yield r, c - 1
        if c + 1 < C:
            yield r, c + 1

    # Find low points
    low_points = []
    for r in range(R):
        for c in range(C):
            h = grid[r][c]
            if all(h < grid[nr][nc] for nr, nc in neighbors(r, c)):
                low_points.append((r, c))

    # Flood fill basins from each low point, excluding height 9
    visited = [[False] * C for _ in range(R)]
    basin_sizes = []

    for sr, sc in low_points:
        if visited[sr][sc]:
            continue
        q = deque([(sr, sc)])
        visited[sr][sc] = True
        size = 0

        while q:
            r, c = q.popleft()
            size += 1
            for nr, nc in neighbors(r, c):
                if visited[nr][nc]:
                    continue
                if grid[nr][nc] == 9:
                    continue
                visited[nr][nc] = True
                q.append((nr, nc))

        basin_sizes.append(size)

    basin_sizes.sort(reverse=True)
    a, b, c = basin_sizes[0], basin_sizes[1], basin_sizes[2]
    print(a * b * c)

if __name__ == "__main__":
    solve()

