import sys

def solve(lines):
    open_to_close = {'(': ')', '[': ']', '{': '}', '<': '>'}
    close_to_score_part1 = {')': 3, ']': 57, '}': 1197, '>': 25137}
    close_to_score_part2 = {')': 1, ']': 2, '}': 3, '>': 4}

    part1_total = 0  # not required for final output, but computed per plan
    completion_scores = []

    for line in lines:
        st = []
        corrupted = False
        first_illegal = None

        for ch in line:
            if ch in open_to_close:
                st.append(ch)
            else:
                if not st:
                    corrupted = True
                    first_illegal = ch
                    break
                expected = open_to_close[st[-1]]
                if ch != expected:
                    corrupted = True
                    first_illegal = ch
                    break
                st.pop()

        if corrupted:
            part1_total += close_to_score_part1[first_illegal]
            continue

        # Incomplete (not corrupted) => compute autocomplete score if stack not empty
        if st:
            score = 0
            while st:
                top = st.pop()
                needed_close = open_to_close[top]
                score = score * 5 + close_to_score_part2[needed_close]
            completion_scores.append(score)

    completion_scores.sort()
    answer = completion_scores[len(completion_scores) // 2]
    return answer

