import sys
import re

def parse_target(line: str):
    # Example: "target area: x=20..30, y=-10..-5"
    nums = list(map(int, re.findall(r"-?\d+", line)))
    # nums should be [x_min, x_max, y_min, y_max]
    if len(nums) != 4:
        raise ValueError("Unexpected input format")
    x_min, x_max, y_min, y_max = nums
    if x_min > x_max:
        x_min, x_max = x_max, x_min
    if y_min > y_max:
        y_min, y_max = y_max, y_min
    return x_min, x_max, y_min, y_max

def max_height_for_target(x_min, x_max, y_min, y_max):
    # Determine vx search bounds
    # If target is to the right (common case), vx0 must be positive.
    # If target includes x=0 or is left, extend to negative velocities.
    if x_min >= 0:
        vx_low = 1
        vx_high = x_max
    elif x_max <= 0:
        vx_low = x_min
        vx_high = -1
    else:
        # Target spans origin; allow both directions
        vx_low = x_min
        vx_high = x_max

    # Determine vy search bounds
    # Classic safe bound for AoC: vy0 in [y_min .. -y_min-1] when y_max < 0.
    # For generality, use a conservative bound.
    if y_max < 0:
        vy_low = y_min
        vy_high = -y_min - 1
    else:
        # If target is at/above y=0, still bound vy0 to something safe.
        # This is conservative and keeps brute force feasible.
        bound = max(abs(y_min), abs(y_max)) + 2
        vy_low = -bound
        vy_high = bound

    def hits(vx0, vy0):
        x = 0
        y = 0
        vx = vx0
        vy = vy0
        max_y = y

        while True:
            x += vx
            y += vy
            if y > max_y:
                max_y = y

            # Check hit
            if x_min <= x <= x_max and y_min <= y <= y_max:
                return True, max_y

            # Prune: if x is beyond target and moving away, or y is below target and falling away
            # For x:
            if vx == 0:
                # If vx is 0, x will never change again; if not in range, cannot hit.
                if not (x_min <= x <= x_max):
                    return False, None
            else:
                # If target is to the right and we've passed it, we can stop.
                if x_min >= 0 and x > x_max and vx >= 0:
                    return False, None
                # If target is to the left and we've passed it, we can stop.
                if x_max <= 0 and x < x_min and vx <= 0:
                    return False, None
                # If target spans origin, pruning on x is less straightforward; rely on y pruning.

            # For y:
            # If y is below the target's lower bound and vy is decreasing further, it will never come back.
            if y < y_min and vy <= 0:
                return False, None

            # Apply drag and gravity
            if vx > 0:
                vx -= 1
            elif vx < 0:
                vx += 1
            vy -= 1

    best = None
    for vx0 in range(vx_low, vx_high + 1):
        for vy0 in range(vy_low, vy_high + 1):
            ok, m = hits(vx0, vy0)
            if ok:
                if best is None or m > best:
                    best = m

    return best if best is not None else 0

def main():
    line = sys.stdin.readline().strip()
    x_min, x_max, y_min, y_max = parse_target(line)
    ans = max_height_for_target(x_min, x_max, y_min, y_max)
    print(ans)

if __name__ == "__main__":
    main()

