import sys
import re

def solve(data: str) -> int:
    s = data.strip()
    if not s:
        return 0

    m = re.search(r"x=(-?\d+)\.\.(-?\d+), y=(-?\d+)\.\.(-?\d+)", s)
    if not m:
        raise ValueError("Invalid input format")

    x_min, x_max, y_min, y_max = map(int, m.groups())
    if x_min > x_max:
        x_min, x_max = x_max, x_min
    if y_min > y_max:
        y_min, y_max = y_max, y_min

    # Compute minimal vx0 such that triangular number reaches x_min
    # vx0(vx0+1)/2 >= x_min
    if x_min <= 0:
        vx0_min = -abs(x_min)  # not expected for AoC input; keep safe
    else:
        # ceil((sqrt(1+8*x_min)-1)/2)
        disc = 1 + 8 * x_min
        root = int(disc ** 0.5)
        while root * root < disc:
            root += 1
        while (root - 1) * (root - 1) >= disc:
            root -= 1
        vx0_min = (root - 1) // 2
        if vx0_min * (vx0_min + 1) // 2 < x_min:
            vx0_min += 1

    vx0_min = max(vx0_min, 0)
    vx0_max = x_max  # safe for typical AoC where x_min,x_max are positive

    vy0_min = y_min
    vy0_max = -y_min - 1  # standard safe upper bound for AoC

    ans = 0

    for vx0 in range(vx0_min, vx0_max + 1):
        for vy0 in range(vy0_min, vy0_max + 1):
            x = 0
            y = 0
            vx = vx0
            vy = vy0

            while True:
                x += vx
                y += vy

                if x_min <= x <= x_max and y_min <= y <= y_max:
                    ans += 1
                    break

                # Early stopping: once x is beyond target and vx cannot increase again
                if x > x_max:
                    break
                # Once y is below target's lower bound, it will only decrease further
                if y < y_min:
                    break

                # Apply drag and gravity
                if vx > 0:
                    vx -= 1
                elif vx < 0:
                    vx += 1
                vy -= 1

    return ans

def main():
    data = sys.stdin.read()
    print(solve(data))

if __name__ == "__main__":
