import sys
from collections import deque

def parse_input(data: str):
    scanners = []
    cur = None
    for line in data.splitlines():
        line = line.strip()
        if not line:
            continue
        if line.startswith('--- scanner'):
            cur = []
        elif line.startswith('---'):
            continue
        else:
            x, y, z = map(int, line.split(','))
            cur.append((x, y, z))
            # If next line is a scanner header, cur will be appended then.
        # Detect end of scanner block by peeking next line isn't possible here;
        # Instead, append when we see a new header or EOF.
        if line.startswith('--- scanner'):
            # shouldn't happen due to earlier branch
            pass
        # We'll append at EOF and when encountering a header; easiest is to re-parse with state.
    # Re-parse with proper state machine
    scanners = []
    cur = None
    for line in data.splitlines():
        line = line.strip()
        if not line:
            continue
        if line.startswith('--- scanner'):
            if cur is not None:
                scanners.append(cur)
            cur = []
        elif line.startswith('---'):
            continue
        else:
            x, y, z = map(int, line.split(','))
            cur.append((x, y, z))
    if cur is not None:
        scanners.append(cur)
    return scanners

def generate_rotations():
    # 24 right-handed rotations: all permutations of axes with sign flips
    # such that determinant is +1.
    rots = []
    axes = [0, 1, 2]
    # For each permutation of axes, choose signs for each axis
    # and keep only those with det +1.
    import itertools
    for perm in itertools.permutations(axes):
        for signs in itertools.product([1, -1], repeat=3):
            # Build matrix columns as images of basis vectors
            # rotation(x,y,z) = (signs[0]*v[perm[0]], signs[1]*v[perm[1]], signs[2]*v[perm[2]])
            # Matrix rows:
            # row0 has 1 at perm[0] with sign signs[0], etc.
            m = [[0, 0, 0] for _ in range(3)]
            for i in range(3):
                m[i][perm[i]] = signs[i]
            # determinant
            det = (
                m[0][0] * (m[1][1] * m[2][2] - m[1][2] * m[2][1]) -
                m[0][1] * (m[1][0] * m[2][2] - m[1][2] * m[2][0]) +
                m[0][2] * (m[1][0] * m[2][1] - m[1][1] * m[2][0])
            )
            if det == 1:
                rots.append((perm, signs))
    # Deduplicate (should already be 24)
    uniq = []
    seen = set()
    for perm, signs in rots:
        key = (perm, signs)
        if key not in seen:
            seen.add(key)
            uniq.append((perm, signs))
    return uniq

def apply_rotation(rot, p):
    perm, signs = rot
    x, y, z = p
    v = (x, y, z)
    return (signs[0] * v[perm[0]], signs[1] * v[perm[1]], signs[2] * v[perm[2]])

def try_align(A_points, A_set, B_points, rotations, K=12):
    # Attempt to find rotation+translation aligning B to A with at least K overlaps.
    # Returns (rotation, translation) or None.
    for rot in rotations:
        B_rot = [apply_rotation(rot, p) for p in B_points]
        counts = {}
        # Translation voting
        for a in A_points:
            ax, ay, az = a
            for bx, by, bz in B_rot:
                t = (ax - bx, ay - by, az - bz)
                c = counts.get(t, 0) + 1
                if c >= K:
                    # Verify
                    tx, ty, tz = t
                    overlap = 0
                    for br in B_rot:
                        p = (br[0] + tx, br[1] + ty, br[2] + tz)
                        if p in A_set:
                            overlap += 1
                    if overlap >= K:
                        return rot, t
                else:
                    counts[t] = c
    return None

def solve(scanners):
    rotations = generate_rotations()
    n = len(scanners)

    aligned = [False] * n
    scanner_pos = [None] * n
    scanner_rot = [None] * n

    # Global beacon set/list
    global_set = set(scanners[0])
    global_list = list(global_set)

    aligned[0] = True
    scanner_pos[0] = (0, 0, 0)
    scanner_rot[0] = rotations[0]  # identity rotation should be included; but ensure identity exists
    # Find identity rotation
    for rot in rotations:
        if apply_rotation(rot, (1, 2, 3)) == (1, 2, 3):
            scanner_rot[0] = rot
            break

    q = deque([0])

    while q:
        i = q.popleft()
        A_points = global_list
        A_set = global_set
        for j in range(n):
            if aligned[j]:
                continue
            res = try_align(A_points, A_set, scanners[j], rotations, K=12)
            if res is None:
                continue
            rot, t = res
            aligned[j] = True
            scanner_pos[j] = t
            scanner_rot[j] = rot

            tx, ty, tz = t
            for p in scanners[j]:
                rp = apply_rotation(rot, p)
                gp = (rp[0] + tx, rp[1] + ty, rp[2] + tz)
                if gp not in global_set:
                    global_set.add(gp)
                    global_list.append(gp)
            q.append(j)

    # Part 2: max Manhattan distance between scanners
    maxd = 0
    for i in range(n):
        xi, yi, zi = scanner_pos[i]
        for j in range(i + 1, n):
            xj, yj, zj = scanner_pos[j]
