    # Attempt to find rotation+translation aligning B to A with at least K overlaps.
    # Returns (rotation, translation) or None.
    for rot in rotations:
        B_rot = [apply_rotation(rot, p) for p in B_points]
        counts = {}
        # Translation voting
        for a in A_points:
            ax, ay, az = a
            for bx, by, bz in B_rot:
                t = (ax - bx, ay - by, az - bz)
                c = counts.get(t, 0) + 1
                if c >= K:
                    # Verify
                    tx, ty, tz = t
                    overlap = 0
                    for br in B_rot:
                        p = (br[0] + tx, br[1] + ty, br[2] + tz)
                        if p in A_set:
                            overlap += 1
                    if overlap >= K:
                        return rot, t
                else:
                    counts[t] = c
    return None

def solve(scanners):
    rotations = generate_rotations()
    n = len(scanners)

    aligned = [False] * n
    scanner_pos = [None] * n
    scanner_rot = [None] * n

    # Global beacon set/list
    global_set = set(scanners[0])
    global_list = list(global_set)

    aligned[0] = True
    scanner_pos[0] = (0, 0, 0)
    scanner_rot[0] = rotations[0]  # identity rotation should be included; but ensure identity exists
    # Find identity rotation
    for rot in rotations:
        if apply_rotation(rot, (1, 2, 3)) == (1, 2, 3):
            scanner_rot[0] = rot
            break

    q = deque([0])

    while q:
        i = q.popleft()
        A_points = global_list
        A_set = global_set
        for j in range(n):
            if aligned[j]:
                continue
            res = try_align(A_points, A_set, scanners[j], rotations, K=12)
            if res is None:
                continue
            rot, t = res
            aligned[j] = True
            scanner_pos[j] = t
            scanner_rot[j] = rot

            tx, ty, tz = t
            for p in scanners[j]:
                rp = apply_rotation(rot, p)
                gp = (rp[0] + tx, rp[1] + ty, rp[2] + tz)
                if gp not in global_set:
                    global_set.add(gp)
                    global_list.append(gp)
            q.append(j)

    # Part 2: max Manhattan distance between scanners
    maxd = 0
    for i in range(n):
        xi, yi, zi = scanner_pos[i]
        for j in range(i + 1, n):
            xj, yj, zj = scanner_pos[j]
            d = abs(xi - xj) + abs(yi - yj) + abs(zi - zj)
            if d > maxd:
                maxd = d
    return maxd

def main():
    data = sys.stdin.read()
    scanners = parse_input(data)
    ans = solve(scanners)
    sys.stdout.write(str(ans))

if __name__ == "__main__":
    main()

