def parse_start_positions(lines):
    p = []
    for line in lines:
        line = line.strip()
        if not line:
            continue
        # Format: "Player X starting position: N"
        n = int(line.split(":")[1].strip())
        p.append(n)
    return p[0], p[1]

def solve_quantum(p1_start, p2_start):
    # Precompute multiplicities of sums when rolling three 3-sided dice (1..3)
    # Sums 3..9 with counts: 1,3,6,7,6,3,1
    roll_sums = [(3, 1), (4, 3), (5, 6), (6, 7), (7, 6), (8, 3), (9, 1)]

    @lru_cache(maxsize=None)
    def dp(p1, p2, s1, s2, turn):
        # Base cases: someone already reached 21+
        if s1 >= 21:
            return (1, 0)
        if s2 >= 21:
            return (0, 1)

        wins1 = 0
        wins2 = 0

        if turn == 0:  # Player 1 to move
            for t, cnt in roll_sums:
                new_p1 = ((p1 - 1 + t) % 10) + 1
                new_s1 = s1 + new_p1
                w1, w2 = dp(new_p1, p2, new_s1, s2, 1)
                wins1 += cnt * w1
                wins2 += cnt * w2
        else:  # Player 2 to move
            for t, cnt in roll_sums:
                new_p2 = ((p2 - 1 + t) % 10) + 1
                new_s2 = s2 + new_p2
                w1, w2 = dp(p1, new_p2, s1, new_s2, 0)
                wins1 += cnt * w1
                wins2 += cnt * w2

        return (wins1, wins2)

    w1, w2 = dp(p1_start, p2_start, 0, 0, 0)
    return max(w1, w2)

