import sys
import re
from dataclasses import dataclass
from typing import Optional, List, Tuple

@dataclass(frozen=True)
class Cuboid:
    x1: int
    x2: int
    y1: int
    y2: int
    z1: int
    z2: int

    def volume(self) -> int:
        # inclusive ranges
        return (self.x2 - self.x1 + 1) * (self.y2 - self.y1 + 1) * (self.z2 - self.z1 + 1)

def intersect(a: Cuboid, b: Cuboid) -> Optional[Cuboid]:
    x1 = max(a.x1, b.x1)
    x2 = min(a.x2, b.x2)
    y1 = max(a.y1, b.y1)
    y2 = min(a.y2, b.y2)
    z1 = max(a.z1, b.z1)
    z2 = min(a.z2, b.z2)
    if x1 > x2 or y1 > y2 or z1 > z2:
        return None
    return Cuboid(x1, x2, y1, y2, z1, z2)

def parse_steps(lines: List[str]) -> List[Tuple[bool, Cuboid]]:
    num_re = re.compile(r"-?\d+")
    steps: List[Tuple[bool, Cuboid]] = []
    for line in lines:
        line = line.strip()
        if not line:
            continue
        turn_on = line.startswith("on")
        nums = list(map(int, num_re.findall(line)))
        if len(nums) != 6:
            raise ValueError(f"Bad input line: {line} -> extracted {nums}")
        x1, x2, y1, y2, z1, z2 = nums
        steps.append((turn_on, Cuboid(x1, x2, y1, y2, z1, z2)))
    return steps

def solve(steps: List[Tuple[bool, Cuboid]]) -> int:
    # Initialization region only: [-50, 50] in all dimensions
    init = Cuboid(-50, 50, -50, 50, -50, 50)

    signed: List[Tuple[Cuboid, int]] = []  # (cuboid, sign)

    for turn_on, c in steps:
        c = intersect(c, init)
        if c is None:
            continue

        additions: List[Tuple[Cuboid, int]] = []
        for ec, esign in signed:
            inter = intersect(ec, c)
            if inter is not None:
                additions.append((inter, -esign))  # inclusion-exclusion
        if turn_on:
            additions.append((c, 1))
        signed.extend(additions)

    total = 0
    for cub, sgn in signed:
        total += sgn * cub.volume()
    return total

def main():
    lines = sys.stdin.read().splitlines()
    if not lines:
        return
    steps = parse_steps(lines)
    print(solve(steps))

if __name__ == "__main__":
    main()

