def solve(grid):
    H = len(grid)
    W = len(grid[0]) if H else 0

    step = 0
    while True:
        moved = False

        # East-facing phase
        next_grid = [row[:] for row in grid]
        for r in range(H):
            for c in range(W):
                if grid[r][c] == '>':
                    nc = (c + 1) % W
                    if grid[r][nc] == '.':
                        next_grid[r][c] = '.'
                        next_grid[r][nc] = '>'
                        moved = True
        grid = next_grid

        # South-facing phase
        next_grid = [row[:] for row in grid]
        for r in range(H):
            for c in range(W):
                if grid[r][c] == 'v':
                    nr = (r + 1) % H
                    if grid[nr][c] == '.':
                        next_grid[r][c] = '.'
                        next_grid[nr][c] = 'v'
                        moved = True
        grid = next_grid

        step += 1
        if not moved:
            return step

