import sys

def first_step_no_movement(grid):
    H = len(grid)
    W = len(grid[0]) if H else 0

    # Work with lists of lists for mutability
    cur = [list(row) for row in grid]

    step = 0
    while True:
        step += 1
        moved = False

        # Phase A: move east-facing '>' based on cur
        phase_a = [row[:] for row in cur]
        for r in range(H):
            for c in range(W):
                if cur[r][c] == '>':
                    nc = (c + 1) % W
                    if cur[r][nc] == '.':
                        phase_a[r][c] = '.'
                        phase_a[r][nc] = '>'
                        moved = True

        # Phase B: move south-facing 'v' based on phase_a
        final = [row[:] for row in phase_a]
        for r in range(H):
            for c in range(W):
                if phase_a[r][c] == 'v':
                    nr = (r + 1) % H
                    if phase_a[nr][c] == '.':
                        final[r][c] = '.'
                        final[nr][c] = 'v'
                        moved = True

        cur = final
        if not moved:
            return step

def main():
    lines = [line.rstrip('\n') for line in sys.stdin if line.strip('\n') != '']
    if not lines:
        return
    print(first_step_no_movement(lines))

if __name__ == "__main__":
    main()

