import sys

def solve() -> None:
    # Map opponent tokens to move IDs: Rock=0, Paper=1, Scissors=2
    opp_map = {'A': 0, 'B': 1, 'C': 2}
    # Map our response tokens to move IDs: Rock=0, Paper=1, Scissors=2
    our_map = {'X': 0, 'Y': 1, 'Z': 2}

    total_score = 0

    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue

        parts = line.split()
        if len(parts) != 2:
            continue  # defensive: ignore malformed lines

        opp_tok, our_tok = parts
        if opp_tok not in opp_map or our_tok not in our_map:
            continue  # defensive: ignore unknown tokens

        opp = opp_map[opp_tok]
        our = our_map[our_tok]

        # Shape score: Rock=1, Paper=2, Scissors=3
        shape_score = our + 1

        # Outcome score using modular arithmetic:
        # (our - opp) mod 3 == 0 -> draw, == 1 -> win, == 2 -> lose
        diff = (our - opp) % 3
        if diff == 0:
            outcome_score = 3
        elif diff == 1:
            outcome_score = 6
        else:
            outcome_score = 0

        total_score += shape_score + outcome_score

    print(total_score)

if __name__ == "__main__":
