import sys
from collections import defaultdict

def first_marker_position(s: str, n: int) -> int:
    L = len(s)
    if L < n:
        return -1  # No marker possible

    freq = defaultdict(int)
    distinct = 0

    # Initialize first window [0 .. n-1]
    for i in range(n):
        ch = s[i]
        freq[ch] += 1
        if freq[ch] == 1:
            distinct += 1

    # Check initial window
    if distinct == n:
        return n  # processed characters count (1-based)

    # Slide window
    for end in range(n, L):
        out_ch = s[end - n]
        freq[out_ch] -= 1
        if freq[out_ch] == 0:
            distinct -= 1

        in_ch = s[end]
        freq[in_ch] += 1
        if freq[in_ch] == 1:
            distinct += 1

        if distinct == n:
            return end + 1  # processed characters count (1-based)

    return -1  # No marker found

def main():
    s = sys.stdin.readline().strip()
    n = 14  # Part Two: start-of-message marker length
    ans = first_marker_position(s, n)
    print(ans)

