    lines = [line.strip() for line in sys.stdin if line.strip() != ""]
    if not lines:
        print(0)
        return

    grid = [[ord(ch) - 48 for ch in line] for line in lines]
    R, C = len(grid), len(grid[0])

    leftDist = [[0] * C for _ in range(R)]
    rightDist = [[0] * C for _ in range(R)]
    upDist = [[0] * C for _ in range(R)]
    downDist = [[0] * C for _ in range(R)]

    # Left distances
    for r in range(R):
        stack = []  # indices of columns
        for c in range(C):
            h = grid[r][c]
            while stack and grid[r][stack[-1]] < h:
                stack.pop()
            if not stack:
                leftDist[r][c] = c
            else:
                leftDist[r][c] = c - stack[-1]
            stack.append(c)

    # Right distances
