def solve(n_knots: int) -> None:
    knots = [[0, 0] for _ in range(n_knots)]  # knots[0]=head, knots[-1]=tail
    visited = {(0, 0)}  # tail positions visited at least once

    def sign(v: int) -> int:
        if v < 0:
            return -1
        if v > 0:
            return 1
        return 0

    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        d, k = line.split()
        k = int(k)

