import sys

def solve(program_lines):
    # Parse instructions into (duration, delta)
    instructions = []
    for line in program_lines:
        line = line.strip()
        if not line:
            continue
        if line == "noop":
            instructions.append((1, 0))
        else:
            op, val = line.split()
            if op != "addx":
                continue
            instructions.append((2, int(val)))

    targets = {20, 60, 100, 140, 180, 220}
    sum_strength = 0
    X = 1
    cycle = 0

    for duration, delta in instructions:
        for i in range(1, duration + 1):
            cycle += 1
            if cycle in targets:
                sum_strength += cycle * X
                # Early stop once we've passed the last target cycle
                if cycle >= 220 and len(targets) == 6:
                    # Still safe to stop because we only need up to 220
                    pass
            if i == duration:
                X += delta

        if cycle >= 220:
            break

    return sum_strength

def main():
    program_lines = sys.stdin.read().splitlines()
    result = solve(program_lines)
    print(result)

if __name__ == "__main__":
    main()

