import sys
from dataclasses import dataclass
from typing import List, Union, Optional

@dataclass(frozen=True)
class IntNode:
    value: int

@dataclass(frozen=True)
class ListNode:
    items: List["Node"]

Node = Union[IntNode, ListNode]

LESS = -1
EQUAL = 0
GREATER = 1

def parse_packet(s: str) -> Node:
    """
    Stack-based parser for the packet grammar.
    Produces an AST where integers are IntNode and lists are ListNode.
    """
    stack: List[ListNode] = []
    num: Optional[int] = None
    in_number = False

    def flush_number():
        nonlocal num, in_number
        if in_number:
            stack[-1].items.append(IntNode(num))  # type: ignore[index]
            num = None
            in_number = False

    for ch in s.strip():
        if ch.isdigit():
            if not in_number:
                num = int(ch)
                in_number = True
            else:
                num = num * 10 + int(ch)  # type: ignore[operator]
        elif ch == '[':
            # Starting a new list; flush any pending number (shouldn't happen in valid input)
            flush_number()
            stack.append(ListNode(items=[]))
        elif ch == ',':
            flush_number()
        elif ch == ']':
            flush_number()
            completed = stack.pop()
            if not stack:
                return completed
            stack[-1].items.append(completed)
        else:
            # Ignore any unexpected whitespace
            continue

    # Should never reach here for valid input
    raise ValueError(f"Invalid packet string: {s}")

def compare(left: Node, right: Node) -> int:
    """
    Tri-state comparator following the puzzle rules.
    Returns:
      LESS    if left < right (in right order)
      GREATER if left > right
      EQUAL   if indistinguishable under comparison
    """
    if isinstance(left, IntNode) and isinstance(right, IntNode):
        if left.value < right.value:
            return LESS
        if left.value > right.value:
            return GREATER
        return EQUAL

    if isinstance(left, ListNode) and isinstance(right, ListNode):
        li, ri = left.items, right.items
        for i in range(min(len(li), len(ri))):
            res = compare(li[i], ri[i])
            if res != EQUAL:
                return res
        if len(li) < len(ri):
            return LESS
        if len(li) > len(ri):
            return GREATER
        return EQUAL

    # Mixed types: coerce integer to single-element list and retry
    if isinstance(left, IntNode):
        return compare(ListNode([left]), right)
    else:
        return compare(left, ListNode([right]))  # type: ignore[arg-type]

def solve() -> None:
    lines = [line.rstrip("\n") for line in sys.stdin.readlines()]

    pairs = []
    i = 0
    while i < len(lines):
        # Skip blank lines
        while i < len(lines) and lines[i].strip() == "":
            i += 1
        if i >= len(lines):
            break
        left_str = lines[i].strip()
        i += 1
        while i < len(lines) and lines[i].strip() == "":
            i += 1
        if i >= len(lines):
            break
        right_str = lines[i].strip()
        i += 1
        pairs.append((left_str, right_str))

    sum_indices = 0
    for idx, (lstr, rstr) in enumerate(pairs, start=1):
        left = parse_packet(lstr)
        right = parse_packet(rstr)
        if compare(left, right) == LESS:
            sum_indices += idx

    sys.stdout.write(str(sum_indices) + "\n")

if __name__ == "__main__":
    solve()

