def parse_packet(s: str):
    """Parse a packet string into nested Python lists/ints."""
    i = 0

    def parse_value():
        nonlocal i
        if s[i] == '[':
            i += 1  # skip '['
            lst = []
            if s[i] == ']':
                i += 1  # skip ']'
                return lst
            while True:
                lst.append(parse_value())
                if s[i] == ',':
                    i += 1
                    continue
                if s[i] == ']':
                    i += 1
                    break
            return lst
        else:
            # integer (problem inputs are non-negative, but handle optional '-')
            sign = 1
            if s[i] == '-':
                sign = -1
                i += 1
            num = 0
            while i < len(s) and s[i].isdigit():
                num = num * 10 + (ord(s[i]) - 48)
                i += 1
            return sign * num

    result = parse_value()
    # Ensure full consumption
    while i < len(s) and s[i].isspace():
        i += 1
    return result

def compare(left, right):
    """Return -1 if left < right (in right order), +1 if left > right, else 0."""
    if isinstance(left, int) and isinstance(right, int):
        if left < right:
            return -1
        if left > right:
            return 1
        return 0

    if isinstance(left, list) and isinstance(right, list):
        m = min(len(left), len(right))
        for idx in range(m):
            c = compare(left[idx], right[idx])
            if c != 0:
                return c
        if len(left) < len(right):
            return -1
        if len(left) > len(right):
            return 1
        return 0

    # Mixed types: promote int to singleton list
    if isinstance(left, int):
        return compare([left], right)
    else:
        return compare(left, [right])

