import sys

def solve(data: str) -> int:
    lines = [line.strip() for line in data.splitlines() if line.strip()]
    blocked = set()
    max_y = 0

    def add_cell(x, y):
        nonlocal max_y
        blocked.add((x, y))
        if y > max_y:
            max_y = y

    # Parse and rasterize rock paths
    for line in lines:
        parts = [p.strip() for p in line.split("->")]
        pts = []
        for p in parts:
            x_str, y_str = p.split(",")
            pts.append((int(x_str), int(y_str)))

        for (x1, y1), (x2, y2) in zip(pts, pts[1:]):
            if x1 == x2:
                step = 1 if y2 >= y1 else -1
                for y in range(y1, y2 + step, step):
                    add_cell(x1, y)
            else:
                step = 1 if x2 >= x1 else -1
                for x in range(x1, x2 + step, step):
                    add_cell(x, y1)

    source_x, source_y = 500, 0
    count = 0

    # Simulate sand until it falls into the abyss
    while True:
        x, y = source_x, source_y

        while True:
            # If current position is already below the lowest rock, it will never rest
            if y > max_y:
                return count

            down = (x, y + 1)
            if down not in blocked:
                x, y = down
                continue

            down_left = (x - 1, y + 1)
            if down_left not in blocked:
                x, y = down_left
                continue

            down_right = (x + 1, y + 1)
            if down_right not in blocked:
                x, y = down_right
                continue

            # Comes to rest
            blocked.add((x, y))
            count += 1
            break

def main():
    data = sys.stdin.read()
    result = solve(data)
    print(result)

