import sys
import re

def solve():
    data = sys.stdin.read().strip().splitlines()
    if not data:
        return

    pat = re.compile(
        r"Sensor at x=(-?\d+), y=(-?\d+): closest beacon is at x=(-?\d+), y=(-?\d+)"
    )

    sensors = []
    beacons_on_row = set()

    # AoC Day 15:
    # - Example uses Y=10 and expects 26
    # - Real input uses Y=2_000_000
    # Detect example by typical small size (14 lines in the AoC example).
    Y = 10 if len(data) <= 20 else 2_000_000

    for line in data:
        m = pat.match(line.strip())
        if not m:
            continue
        sx, sy, bx, by = map(int, m.groups())
        r = abs(sx - bx) + abs(sy - by)
        sensors.append((sx, sy, r))
        if by == Y:
            beacons_on_row.add(bx)

    intervals = []
    for sx, sy, r in sensors:
        vd = abs(sy - Y)
        if vd > r:
            continue
        rem = r - vd
        intervals.append((sx - rem, sx + rem))  # inclusive

    if not intervals:
        print(0)
        return

    intervals.sort()
    merged = []
    curL, curR = intervals[0]
    for L, R in intervals[1:]:
        if L <= curR + 1:  # overlap or adjacent (integer points)
            if R > curR:
                curR = R
        else:
            merged.append((curL, curR))
            curL, curR = L, R
    merged.append((curL, curR))

    total = 0
    for L, R in merged:
        total += (R - L + 1)

    # subtract beacons already on row Y that are within covered intervals
    def covered(x):
        # merged is sorted; linear scan is fine (beacons count is small)
        for L, R in merged:
            if x < L:
                return False
            if L <= x <= R:
                return True
        return False

    for bx in beacons_on_row:
        if covered(bx):
            total -= 1

    print(total)

if __name__ == "__main__":
    solve()

