import sys
from functools import lru_cache

def solve():
    lines = [line.strip() for line in sys.stdin.read().splitlines() if line.strip()]
    value = {}
    left = {}
    right = {}
    op = {}
    typ = {}

    for ln in lines:
        name, job = ln.split(": ")
        parts = job.split()
        if len(parts) == 1:
            value[name] = int(parts[0])
            typ[name] = "const"
        else:
            a, oper, b = parts
            left[name] = a
            right[name] = b
            op[name] = oper
            typ[name] = "op"

    root_left = left["root"]
    root_right = right["root"]

    @lru_cache(None)
    def depends_on_humn(node: str) -> bool:
        if node == "humn":
            return True
        if typ[node] == "const":
            return False
        return depends_on_humn(left[node]) or depends_on_humn(right[node])

    def eval_known(node: str) -> int:
        if node == "humn":
            raise ValueError("eval_known called on humn")
        if typ[node] == "const":
            return value[node]
        a = eval_known(left[node])
        b = eval_known(right[node])
        oper = op[node]
        if oper == "+":
            return a + b
        if oper == "-":
            return a - b
        if oper == "*":
            return a * b
        if oper == "/":
            return a // b
        raise ValueError("Unknown operator")

    left_dep = depends_on_humn(root_left)
    right_dep = depends_on_humn(root_right)

    if left_dep and right_dep:
        raise ValueError("Both sides depend on humn; unexpected for this puzzle.")
    if not left_dep and not right_dep:
        raise ValueError("Neither side depends on humn; unexpected for this puzzle.")

    if not left_dep:
        needed = eval_known(root_left)
        unknown = root_right
    else:
        needed = eval_known(root_right)
        unknown = root_left

    # Walk down from the unknown side to humn, updating `needed` via inverse operations.
    while unknown != "humn":
        L = left[unknown]
        R = right[unknown]
        oper = op[unknown]

        L_dep = depends_on_humn(L)
        # Exactly one side should depend on humn.
        if L_dep:
            dependent = L
            known = R
            known_val = eval_known(known)
            # unknown = dependent (call it X), known_val is the other operand.
            if oper == "+":
                needed = needed - known_val
            elif oper == "-":
                # X - known_val = needed  => X = needed + known_val
                needed = needed + known_val
            elif oper == "*":
                needed = needed // known_val
            elif oper == "/":
                # X / known_val = needed => X = needed * known_val
                needed = needed * known_val
            else:
                raise ValueError("Unknown operator")
            unknown = dependent
        else:
            dependent = R
            known = L
            known_val = eval_known(known)
            if oper == "+":
                # known_val + X = needed => X = needed - known_val
                needed = needed - known_val
            elif oper == "-":
                # known_val - X = needed => X = known_val - needed
                needed = known_val - needed
            elif oper == "*":
                # known_val * X = needed => X = needed / known_val
                needed = needed // known_val
            elif oper == "/":
                # known_val / X = needed => X = known_val / needed
                needed = known_val // needed
            else:
                raise ValueError("Unknown operator")
            unknown = dependent

    print(needed)

if __name__ == "__main__":
    solve()

