import sys
import re

def solve(inp: str) -> int:
    lines = inp.splitlines()

    # Split map and path by first blank line
    split_idx = None
    for i, line in enumerate(lines):
        if line.strip() == "":
            split_idx = i
            break
    if split_idx is None:
        # Fallback: find the line that looks like the instruction string
        for i, line in enumerate(lines):
            if re.fullmatch(r"[0-9LR]+", line.strip()):
                split_idx = i
                break
    if split_idx is None:
        raise ValueError("Could not find instruction line")

    map_lines = lines[:split_idx]
    instr_line = ""
    for j in range(split_idx, len(lines)):
        if lines[j].strip() != "":
            instr_line = lines[j].strip()
            break
    if not instr_line:
        raise ValueError("Missing instruction string")

    R = len(map_lines)
    C = max((len(s) for s in map_lines), default=0)
    BLANK = ' '

    grid = [[BLANK] * C for _ in range(R)]
    for r, s in enumerate(map_lines):
        for c, ch in enumerate(s):
            grid[r][c] = ch

    # Parse instructions into tokens: numbers and L/R
    tokens = []
    i = 0
    while i < len(instr_line):
        ch = instr_line[i]
        if ch.isdigit():
            j = i
            while j < len(instr_line) and instr_line[j].isdigit():
                j += 1
            tokens.append(int(instr_line[i:j]))
            i = j
        else:
            tokens.append(ch)  # 'L' or 'R'
            i += 1

    # Directions: 0=Right,1=Down,2=Left,3=Up
    dr = [0, 1, 0, -1]
    dc = [1, 0, -1, 0]

    # Precompute wrap transitions for each row/col segment
    # next_pos[r][c][dir] -> (nr, nc)
    next_r = [[[0] * 4 for _ in range(C)] for __ in range(R)]
    next_c = [[[0] * 4 for _ in range(C)] for __ in range(R)]

    # Initialize transitions for BLANK cells (unused)
    for r in range(R):
        for c in range(C):
            for d in range(4):
                next_r[r][c][d] = r
                next_c[r][c][d] = c

    # Row segments for Right/Left wrapping
    for r in range(R):
        c = 0
        while c < C:
            while c < C and grid[r][c] == BLANK:
                c += 1
            if c >= C:
                break
            l = c
            while c < C and grid[r][c] != BLANK:
                c += 1
            rr = c - 1
            for x in range(l, rr + 1):
                # Right
                if x < rr:
                    next_r[r][x][0] = r
                    next_c[r][x][0] = x + 1
                else:
                    next_r[r][x][0] = r
                    next_c[r][x][0] = l
                # Left
                if x > l:
                    next_r[r][x][2] = r
                    next_c[r][x][2] = x - 1
                else:
                    next_r[r][x][2] = r
                    next_c[r][x][2] = rr

    # Column segments for Down/Up wrapping
    for c in range(C):
        r = 0
        while r < R:
            while r < R and grid[r][c] == BLANK:
                r += 1
            if r >= R:
                break
            t = r
            while r < R and grid[r][c] != BLANK:
                r += 1
            b = r - 1
            for y in range(t, b + 1):
                # Down
                if y < b:
                    next_r[y][c][1] = y + 1
                    next_c[y][c][1] = c
                else:
                    next_r[y][c][1] = t
                    next_c[y][c][1] = c
                # Up
                if y > t:
                    next_r[y][c][3] = y - 1
                    next_c[y][c][3] = c
                else:
                    next_r[y][c][3] = b
                    next_c[y][c][3] = c

    # Find starting position: leftmost open tile '.' in top row
    start_c = None
    for c in range(C):
        if grid[0][c] == '.':
            start_c = c
            break
    if start_c is None:
        raise ValueError("No starting open tile found")

    r, c, dir_idx = 0, start_c, 0

    for tok in tokens:
        if isinstance(tok, int):
            steps = tok
            for _ in range(steps):
                nr = next_r[r][c][dir_idx]
                nc = next_c[r][c][dir_idx]
                if grid[nr][nc] == '#':
                    break
                r, c = nr, nc
        else:
            if tok == 'R':
                dir_idx = (dir_idx + 1) % 4
            elif tok == 'L':
                dir_idx = (dir_idx + 3) % 4
            else:
                raise ValueError(f"Unexpected token: {tok}")

    final_row = r + 1
    final_col = c + 1
    password = 1000 * final_row + 4 * final_col + dir_idx
    return password

def main():
    data = sys.stdin.read()
    ans = solve(data)
    sys.stdout.write(str(ans))

if __name__ == "__main__":
    main()

