import sys
from collections import deque
from math import gcd

def lcm(a, b):
    return a // gcd(a, b) * b

def solve():
    grid = [line.rstrip("\n") for line in sys.stdin if line.strip("\n") != ""]
    if not grid:
        return
    H = len(grid)
    W = len(grid[0])

    walls = [[False] * W for _ in range(H)]
    start = end = None
    blizzards = []  # (r0, c0, dir_char)

    for r in range(H):
        for c in range(W):
            ch = grid[r][c]
            if ch == '#':
                walls[r][c] = True
            elif ch in '^v<>':
                blizzards.append((r, c, ch))
            else:
                # '.' or other non-wall
                if r == 0 and ch != '#':
                    start = (r, c)
                if r == H - 1 and ch != '#':
                    end = (r, c)

    if start is None or end is None:
        raise ValueError("Start or end not found")

    innerH = H - 2
    innerW = W - 2
    period = lcm(innerH, innerW)

    # blocked[t][r][c] for inner cells only (r in 1..H-2, c in 1..W-2)
    # We'll store as a list of 2D boolean arrays for each t.
    blocked = []
    for _ in range(period):
        blocked.append([[False] * W for _ in range(H)])

    # Precompute occupancy for each time modulo period
    for t in range(period):
        bt = blocked[t]
        for r0, c0, d in blizzards:
            ri = r0 - 1
            ci = c0 - 1
            if d == '>':
                ci2 = (ci + t) % innerW
                ri2 = ri
            elif d == '<':
                ci2 = (ci - t) % innerW
                ri2 = ri
            elif d == 'v':
                ri2 = (ri + t) % innerH
                ci2 = ci
            elif d == '^':
                ri2 = (ri - t) % innerH
                ci2 = ci
            else:
                continue
            r = ri2 + 1
            c = ci2 + 1
            bt[r][c] = True

    sr, sc = start
    gr, gc = end

    # BFS over (r, c, tmod)
    INF = 10**18
    dist = [[[INF] * period for _ in range(W)] for __ in range(H)]
    q = deque()

    dist[sr][sc][0] = 0
    q.append((sr, sc, 0))

    def is_blocked(nr, nc, ntmod):
        # Start/end are on outer boundary; blizzards only occupy inner wrap-around cells.
        if nr == sr and nc == sc:
            return False
        if nr == gr and nc == gc:
            return False
        if 1 <= nr <= H - 2 and 1 <= nc <= W - 2:
            return blocked[ntmod][nr][nc]
        # Outside inner rectangle but not start/end: should be walls anyway.
        return True

    dirs = [(-1, 0), (1, 0), (0, -1), (0, 1), (0, 0)]  # up, down, left, right, wait

    while q:
        r, c, tmod = q.popleft()
        curd = dist[r][c][tmod]
        if r == gr and c == gc:
            print(curd)
            return

        ntmod = (tmod + 1) % period
        for dr, dc in dirs:
            nr, nc = r + dr, c + dc
            if not (0 <= nr < H and 0 <= nc < W):
                continue
            if walls[nr][nc]:
                continue
            if is_blocked(nr, nc, ntmod):
                continue
            if dist[nr][nc][ntmod] == INF:
                dist[nr][nc][ntmod] = curd + 1
                q.append((nr, nc, ntmod))

    # If unreachable (shouldn't happen for valid inputs)
    print(-1)

if __name__ == "__main__":
    solve()

