import sys

def snafu_to_decimal(s: str) -> int:
    digit_map = {'2': 2, '1': 1, '0': 0, '-': -1, '=': -2}
    acc = 0
    for ch in s.strip():
        acc = acc * 5 + digit_map[ch]
    return acc

def decimal_to_snafu(n: int) -> str:
    if n == 0:
        return "0"
    digits = []
    while n != 0:
        r = n % 5  # 0..4
        if r <= 2:
            digits.append(str(r))  # 0->'0', 1->'1', 2->'2'
            n //= 5
        elif r == 3:
            digits.append('=')     # -2
            n = (n + 2) // 5
        else:  # r == 4
            digits.append('-')     # -1
            n = (n + 1) // 5
    return ''.join(reversed(digits))

def solve() -> None:
    lines = [line.strip() for line in sys.stdin.read().splitlines()]
    lines = [x for x in lines if x]
    total = 0
    for s in lines:
        total += snafu_to_decimal(s)
    print(decimal_to_snafu(total))

if __name__ == "__main__":
    solve()

