import sys

DIGIT_WORDS = {
    "one": "1",
    "two": "2",
    "three": "3",
    "four": "4",
    "five": "5",
    "six": "6",
    "seven": "7",
    "eight": "8",
    "nine": "9",
}

WORD_LIST = list(DIGIT_WORDS.keys())


def find_first_digit(s: str) -> str:
    for i in range(len(s)):
        ch = s[i]
        if "0" <= ch <= "9":
            return ch
        for w in WORD_LIST:
            if s.startswith(w, i):
                return DIGIT_WORDS[w]
    raise ValueError("No digit found in line")


def find_last_digit(s: str) -> str:
    for i in range(len(s) - 1, -1, -1):
        ch = s[i]
        if "0" <= ch <= "9":
            return ch
        for w in WORD_LIST:
            start = i - len(w) + 1
            if start >= 0 and s.startswith(w, start):
                return DIGIT_WORDS[w]
    raise ValueError("No digit found in line")


def solve(lines):
    total = 0
    for line in lines:
        line = line.strip()
        if not line:
            continue
        first = find_first_digit(line)
        last = find_last_digit(line)
        total += int(first + last)
    return total


