import sys
import re

def parse_input(text: str):
    lines = [ln.rstrip() for ln in text.splitlines()]
    seeds = []
    maps = []
    cur_map = None

    i = 0
    while i < len(lines):
        line = lines[i].strip()
        if not line:
            i += 1
            continue

        if line.startswith("seeds:"):
            nums = list(map(int, re.findall(r"-?\d+", line)))
            # first number is after "seeds:"; re.findall returns all ints on the line
            seeds = nums[1:] if nums and nums[0] == nums[0] else nums
            i += 1
            continue

        if line.endswith("map:"):
            if cur_map is not None:
                maps.append(cur_map)
            cur_map = []
            i += 1
            continue

        # mapping line: destStart srcStart length
        if cur_map is None:
            i += 1
            continue
        nums = list(map(int, re.findall(r"-?\d+", line)))
        if len(nums) == 3:
            dest_start, src_start, length = nums
            src_end = src_start + length
            delta = dest_start - src_start
            cur_map.append((src_start, src_end, delta))
        i += 1

    if cur_map is not None:
        maps.append(cur_map)

    # Sort intervals in each map by source start
    for m in maps:
        m.sort(key=lambda x: x[0])

    return seeds, maps

def merge_intervals(intervals):
    if not intervals:
        return []
    intervals.sort(key=lambda x: x[0])
    merged = [intervals[0]]
    for s, e in intervals[1:]:
        ps, pe = merged[-1]
        if s <= pe:  # overlap or adjacent (half-open adjacency means s==pe)
            merged[-1] = (ps, max(pe, e))
        else:
            merged.append((s, e))
    return merged

def apply_map_to_intervals(current, map_intervals):
    # current: list of disjoint half-open intervals [a,b)
    # map_intervals: sorted list of (s,e,delta) for source ranges [s,e)
    next_intervals = []
    for a, b in current:
        pos = a
        for s, e, delta in map_intervals:
            if e <= pos:
                continue
            if s >= b:
                break

            # identity segment before mapped overlap
            if pos < s:
                id_end = min(s, b)
                if pos < id_end:
                    next_intervals.append((pos, id_end))
                pos = id_end

            if pos >= b:
                break

            # mapped overlap
            ov_start = max(pos, s)
            ov_end = min(b, e)
            if ov_start < ov_end:
                next_intervals.append((ov_start + delta, ov_end + delta))
                pos = ov_end

            if pos >= b:
                break

        # remaining identity segment
        if pos < b:
            next_intervals.append((pos, b))

    return merge_intervals(next_intervals)

def solve():
    data = sys.stdin.read()
    seeds, maps = parse_input(data)

    # Part 1: each seed is a single value => interval [seed, seed+1)
    current = [(s, s + 1) for s in seeds]
    current = merge_intervals(current)

    for m in maps:
        current = apply_map_to_intervals(current, m)

    ans = min(s for s, _ in current) if current else 0
    sys.stdout.write(str(ans) + "\n")

if __name__ == "__main__":
    solve()

