import sys
import math
import re
from functools import reduce
from operator import mul

def count_ways(T: int, R: int) -> int:
    # Distance for hold time h: d(h) = h*(T-h)
    # Need d(h) > R  =>  h*(T-h) > R
    # Equivalent quadratic: h^2 - T*h + R < 0
    # Winning h are integers strictly between the real roots.
    disc = T * T - 4 * R
    if disc <= 0:
        return 0

    sqrt_disc = math.isqrt(disc)
    # If disc is not a perfect square, isqrt gives floor(sqrt). We still can use it
    # with careful integer bounds via binary search to avoid precision issues.
    # We'll use binary search for robustness as planned.

    def dist(h: int) -> int:
        return h * (T - h)

    # Find smallest h such that dist(h) > R
    lo, hi = 0, T
    while lo < hi:
        mid = (lo + hi) // 2
        if dist(mid) > R:
            hi = mid
        else:
            lo = mid + 1
    L = lo
    if L > T or dist(L) <= R:
        return 0

    # Find largest h such that dist(h) > R
    lo, hi = 0, T
    while lo < hi:
        mid = (lo + hi + 1) // 2
        if dist(mid) > R:
            lo = mid
        else:
            hi = mid - 1
    U = lo
    if U < 0 or dist(U) <= R:
        return 0

    return max(0, U - L + 1)

def solve():
    text = sys.stdin.read().strip().splitlines()
    if not text:
        return

    time_vals = []
    dist_vals = []

    for line in text:
        if "Time:" in line:
            time_vals = list(map(int, re.findall(r"-?\d+", line)))
        elif "Distance:" in line:
            dist_vals = list(map(int, re.findall(r"-?\d+", line)))

    if len(time_vals) != len(dist_vals):
        raise ValueError("Malformed input: Time and Distance counts differ.")

    ways = [count_ways(T, R) for T, R in zip(time_vals, dist_vals)]
    ans = reduce(mul, ways, 1)
    sys.stdout.write(str(ans) + "\n")

if __name__ == "__main__":
    solve()

