import sys

def parse_input():
    lines = sys.stdin.read().strip().splitlines()
    histories = []
    for line in lines:
        line = line.strip()
        if not line:
            continue
        histories.append([int(x) for x in line.split()])
    return histories

def build_layers(a):
    layers = [a[:]]
    while not all(v == 0 for v in layers[-1]):
        row = layers[-1]
        next_row = [row[i + 1] - row[i] for i in range(len(row) - 1)]
        layers.append(next_row)
    return layers

def extrapolate_next(a):
    layers = build_layers(a)
    # Forward extrapolation: extend to the right
    layers[-1].append(0)
    for k in range(len(layers) - 2, -1, -1):
        layers[k].append(layers[k][-1] + layers[k + 1][-1])
    return layers[0][-1]

def extrapolate_prev(a):
    layers = build_layers(a)
    # Backward extrapolation: extend to the left
    layers[-1].insert(0, 0)
    for k in range(len(layers) - 2, -1, -1):
        layers[k].insert(0, layers[k][0] - layers[k + 1][0])
    return layers[0][0]

def solve_part2(histories):
    return sum(extrapolate_prev(h) for h in histories)

if __name__ == "__main__":
    histories = parse_input()
    print(solve_part2(histories))

