import sys
from functools import lru_cache

def count_arrangements(pattern: str, groups: list[int]) -> int:
    n = len(pattern)
    m = len(groups)

    # Prefix sums for fast checks
    # badPrefix[k] = number of '.' in pattern[0..k-1]
    badPrefix = [0] * (n + 1)
    hashPrefix = [0] * (n + 1)  # number of '#' in pattern[0..k-1]
    for i, ch in enumerate(pattern):
        badPrefix[i + 1] = badPrefix[i] + (1 if ch == '.' else 0)
        hashPrefix[i + 1] = hashPrefix[i] + (1 if ch == '#' else 0)

    def segment_has_no_dot(i: int, L: int) -> bool:
        # segment pattern[i:i+L] contains no '.'
        return (badPrefix[i + L] - badPrefix[i]) == 0

    def suffix_has_no_hash(pos: int) -> bool:
        return (hashPrefix[n] - hashPrefix[pos]) == 0

    @lru_cache(maxsize=None)
    def dp(pos: int, gi: int) -> int:
        # If all groups placed, remaining must not contain forced '#'
        if gi == m:
            return 1 if suffix_has_no_hash(pos) else 0
        if pos == n:
            return 0

        ans = 0

        # Transition 1: treat current as operational '.'
        if pattern[pos] != '#':  # '.' or '?'
            ans += dp(pos + 1, gi)

        # Transition 2: place next damaged group starting at pos
        L = groups[gi]
        end = pos + L
        if end <= n and segment_has_no_dot(pos, L):
            # Separator after group: must not be '#'
            if end == n:
                ans += dp(end, gi + 1)
            else:
                if pattern[end] != '#':  # '.' or '?'
                    ans += dp(end + 1, gi + 1)

        return ans

    return dp(0, 0)

def solve() -> None:
    total = 0
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        pattern, nums = line.split()
        groups = list(map(int, nums.split(',')))
        total += count_arrangements(pattern, groups)
    print(total)

if __name__ == "__main__":
    solve()

