import sys

def parse_patterns(lines):
    patterns = []
    cur = []
    for line in lines:
        line = line.rstrip("\n")
        if line.strip() == "":
            if cur:
                patterns.append(cur)
                cur = []
        else:
            cur.append(line)
    if cur:
        patterns.append(cur)
    return patterns

def find_reflection_score(grid):
    R = len(grid)
    C = len(grid[0]) if R else 0

    # Vertical reflection: between columns k-1 and k, where k in [1..C-1]
    for k in range(1, C):
        dmax = min(k, C - k) - 1
        ok = True
        for d in range(dmax + 1):
            colL = k - 1 - d
            colR = k + d
            for r in range(R):
                if grid[r][colL] != grid[r][colR]:
                    ok = False
                    break
            if not ok:
                break
        if ok:
            return k  # number of columns to the left

    # Horizontal reflection: between rows k-1 and k, where k in [1..R-1]
    for k in range(1, R):
        dmax = min(k, R - k) - 1
        ok = True
        for d in range(dmax + 1):
            rowT = k - 1 - d
            rowB = k + d
            for c in range(C):
                if grid[rowT][c] != grid[rowB][c]:
                    ok = False
                    break
            if not ok:
                break
        if ok:
            return 100 * k  # 100 * number of rows above

    return 0  # Should not happen for valid inputs

def solve():
    lines = sys.stdin.read().splitlines()
    patterns = parse_patterns(lines)
    total = 0
    for grid in patterns:
        total += find_reflection_score(grid)
    print(total)

if __name__ == "__main__":
    solve()

