import sys

def tilt(grid, direction):
    R = len(grid)
    C = len(grid[0])

    if direction == 'N':
        for c in range(C):
            r = 0
            while r < R:
                while r < R and grid[r][c] == '#':
                    r += 1
                if r >= R:
                    break
                start = r
                while r < R and grid[r][c] != '#':
                    r += 1
                end = r  # exclusive
                count = 0
                for rr in range(start, end):
                    if grid[rr][c] == 'O':
                        count += 1
                for rr in range(start, end):
                    grid[rr][c] = 'O' if (rr - start) < count else '.'

    elif direction == 'S':
        for c in range(C):
            r = 0
            while r < R:
                while r < R and grid[r][c] == '#':
                    r += 1
                if r >= R:
                    break
                start = r
                while r < R and grid[r][c] != '#':
                    r += 1
                end = r  # exclusive
                count = 0
                for rr in range(start, end):
                    if grid[rr][c] == 'O':
                        count += 1
                for rr in range(start, end):
                    grid[rr][c] = 'O' if (end - 1 - rr) < count else '.'

    elif direction == 'W':
        for r in range(R):
            c = 0
            while c < C:
                while c < C and grid[r][c] == '#':
                    c += 1
                if c >= C:
                    break
                start = c
                while c < C and grid[r][c] != '#':
                    c += 1
                end = c  # exclusive
                count = 0
                for cc in range(start, end):
                    if grid[r][cc] == 'O':
                        count += 1
                for cc in range(start, end):
                    grid[r][cc] = 'O' if (cc - start) < count else '.'

    elif direction == 'E':
        for r in range(R):
            c = 0
            while c < C:
                while c < C and grid[r][c] == '#':
                    c += 1
                if c >= C:
                    break
                start = c
                while c < C and grid[r][c] != '#':
                    c += 1
                end = c  # exclusive
                count = 0
                for cc in range(start, end):
                    if grid[r][cc] == 'O':
                        count += 1
                for cc in range(start, end):
                    grid[r][cc] = 'O' if (end - 1 - cc) < count else '.'
    else:
        raise ValueError("Invalid direction")

def spin_cycle(grid):
    tilt(grid, 'N')
    tilt(grid, 'W')
    tilt(grid, 'S')
    tilt(grid, 'E')

def state_key(grid):
    return '\n'.join(''.join(row) for row in grid)

def compute_load(grid):
    R = len(grid)
    total = 0
    for r in range(R):
        weight = R - r
        row = grid[r]
        for ch in row:
            if ch == 'O':
                total += weight
    return total

def main():
    lines = [line.rstrip('\n') for line in sys.stdin if line.strip('\n') != '']
    if not lines:
        return
    grid = [list(line) for line in lines]
    target = 1_000_000_000

    seen = {}
    states = []  # store keys in order of cycle index
    i = 0
    while i < target:
        key = state_key(grid)
        if key in seen:
            start = seen[key]
            cycle_len = i - start
            remaining = target - start
            desired_index = start + (remaining % cycle_len)
            # Re-simulate from initial state to desired_index
            # We stored only keys; easiest is to keep a snapshot list of grids? Avoid memory.
            # Instead, re-run from scratch using the same simulation until desired_index.
            # To do that, we need the initial grid; reconstruct by using the first stored key.
            # We'll re-run from the current grid? Not possible. So store initial grid snapshot.
            break
        seen[key] = i
        states.append(key)
        spin_cycle(grid)
        i += 1
    else:
        # i == target, grid already at target
        print(compute_load(grid))
        return

    # If we broke due to cycle detection, we need to re-simulate from the initial grid.
    # Reconstruct initial grid from states[0] key.
    initial_key = states[0]
    init_rows = initial_key.split('\n')
    init_grid = [list(row) for row in init_rows]

    # Determine desired_index precisely
    key = state_key(grid)
    start = seen[key]
    cycle_len = i - start
    remaining = target - start
    desired_index = start + (remaining % cycle_len)

    grid2 = [row[:] for row in init_grid]
    for _ in range(desired_index):
        spin_cycle(grid2)

    print(compute_load(grid2))

if __name__ == "__main__":
    main()

