import sys

def holiday_hash(s: str) -> int:
    current = 0
    for ch in s:
        current += ord(ch)
        current *= 17
        current %= 256
    return current

def solve():
    line = sys.stdin.read()
    if not line:
        return
    line = line.strip()
    steps = [tok for tok in line.split(',') if tok != ""]

    # Part 1 (not required for output, but computed per plan)
    part1_sum = 0
    for step in steps:
        part1_sum += holiday_hash(step)

    # Part 2
    boxes = [[] for _ in range(256)]  # each box: list of [label, focal] in order

    for step in steps:
        if step.endswith('-'):
            label = step[:-1]
            b = holiday_hash(label)
            lenses = boxes[b]
            for i, (lab, _) in enumerate(lenses):
                if lab == label:
                    del lenses[i]
                    break
        else:
            label, focal_str = step.split('=')
            focal = int(focal_str)
            b = holiday_hash(label)
            lenses = boxes[b]
            for i, (lab, _) in enumerate(lenses):
                if lab == label:
                    lenses[i][1] = focal
                    break
            else:
                lenses.append([label, focal])

    total = 0
    for b in range(256):
        for slot_idx, (_, focal) in enumerate(boxes[b]):
            slot = slot_idx + 1
            total += (b + 1) * slot * focal

    print(total)

if __name__ == "__main__":
    solve()

