import sys
from collections import deque

def solve():
    grid = [line.rstrip("\n") for line in sys.stdin if line.strip("\n") != ""]
    if not grid:
        return
    R, C = len(grid), len(grid[0])

    # Directions: 0=Up, 1=Right, 2=Down, 3=Left
    dr = [-1, 0, 1, 0]
    dc = [0, 1, 0, -1]

    def next_dirs(tile, d):
        # Always return a list of outgoing directions
        if tile == '.':
            return [d]
        if tile == '/':
            # Up->Right, Right->Up, Down->Left, Left->Down
            return [{0: 1, 1: 0, 2: 3, 3: 2}[d]]
        if tile == '\\':
            # Up->Left, Left->Up, Down->Right, Right->Down
            return [{0: 3, 3: 0, 2: 1, 1: 2}[d]]
        if tile == '|':
            # If moving vertically, pass through; if horizontally, split up+down
            if d in (0, 2):
                return [d]
            return [0, 2]
        if tile == '-':
            # If moving horizontally, pass through; if vertically, split left+right
            if d in (1, 3):
                return [d]
            return [1, 3]
        # Should never happen
        return [d]

    def simulate(sr, sc, sd):
        visited = [[[False] * 4 for _ in range(C)] for __ in range(R)]
        energized = [[False] * C for _ in range(R)]

        q = deque()
        q.append((sr, sc, sd))

        while q:
            r, c, d = q.popleft()
            if not (0 <= r < R and 0 <= c < C):
                continue
            if visited[r][c][d]:
                continue
            visited[r][c][d] = True
            energized[r][c] = True

            tile = grid[r][c]
            for nd in next_dirs(tile, d):
                nr, nc = r + dr[nd], c + dc[nd]
                if 0 <= nr < R and 0 <= nc < C:
                    q.append((nr, nc, nd))

        return sum(1 for r in range(R) for c in range(C) if energized[r][c])

    # Part 2: maximize over all edge starts
    best = 0

    # Top row: heading down (dir=2)
    for c in range(C):
        best = max(best, simulate(0, c, 2))
    # Bottom row: heading up (dir=0)
    for c in range(C):
        best = max(best, simulate(R - 1, c, 0))
    # Left column: heading right (dir=1)
    for r in range(R):
        best = max(best, simulate(r, 0, 1))
    # Right column: heading left (dir=3)
    for r in range(R):
        best = max(best, simulate(r, C - 1, 3))

    print(best)

if __name__ == "__main__":
    solve()

