import sys

def parse_workflows(lines):
    workflows = {}
    for line in lines:
        line = line.strip()
        if not line:
            continue
        name, rest = line.split("{", 1)
        rest = rest.rstrip("}")
        tokens = rest.split(",")
        rules = []
        for tok in tokens:
            if ":" in tok:
                cond, dest = tok.split(":", 1)
                var = cond[0]
                op = cond[1]
                threshold = int(cond[2:])
                rules.append((var, op, threshold, dest))
            else:
                # unconditional fallback
                rules.append((None, None, None, tok))
        workflows[name] = rules
    return workflows

def parse_parts(lines):
    parts = []
    for line in lines:
        line = line.strip()
        if not line:
            continue
        inner = line.strip("{}")
        items = inner.split(",")
        d = {}
        for it in items:
            k, v = it.split("=", 1)
            d[k] = int(v)
        parts.append(d)
    return parts

