    cur = "in"
    while True:
        if cur == "A":
            return True
        if cur == "R":
            return False
        rules = workflows[cur]
        for var, op, thr, dest in rules:
            if var is None:
                cur = dest
                break
            val = part[var]
            if op == "<":
                if val < thr:
                    cur = dest
                    break
            else:  # op == ">"
                if val > thr:
                    cur = dest
                    break

def solve(data):
    blocks = data.split("\n\n", 1)
    if len(blocks) == 1:
        workflow_block = blocks[0].splitlines()
        part_block = []
    else:
        workflow_block = blocks[0].splitlines()
        part_block = blocks[1].splitlines()

