    ans = 0
    for p in parts:
        if evaluate_part(p, workflows):
            ans += p["x"] + p["m"] + p["a"] + p["s"]
    return ans

def main():
    data = sys.stdin.read()
    result = solve(data)
    sys.stdout.write(str(result) + "\n")

