import sys
from functools import lru_cache

def parse_workflows(lines):
    workflows = {}
    for line in lines:
        line = line.strip()
        if not line:
            break
        name, rest = line.split("{", 1)
        rest = rest.rstrip("}")
        rules = []
        for part in rest.split(","):
            if ":" in part:
                cond, dest = part.split(":")
                cat = cond[0]
                op = cond[1]
                val = int(cond[2:])
                rules.append((cat, op, val, dest))
            else:
                # unconditional
                rules.append((None, None, None, part))
        workflows[name] = rules
    return workflows

def solve_part_two(workflows):
    # Box represented as (x_lo, x_hi, m_lo, m_hi, a_lo, a_hi, s_lo, s_hi), inclusive integer bounds.
    initial_box = (1, 4000, 1, 4000, 1, 4000, 1, 4000)

    def volume(box):
        x_lo, x_hi, m_lo, m_hi, a_lo, a_hi, s_lo, s_hi = box
        if x_lo > x_hi or m_lo > m_hi or a_lo > a_hi or s_lo > s_hi:
            return 0
        return (x_hi - x_lo + 1) * (m_hi - m_lo + 1) * (a_hi - a_lo + 1) * (s_hi - s_lo + 1)

    def intersect(box, cat, op, val):
        # Returns a new box after intersecting with predicate (cat op val).
        x_lo, x_hi, m_lo, m_hi, a_lo, a_hi, s_lo, s_hi = box

        if cat == 'x':
            if op == '<':
                x_hi = min(x_hi, val - 1)
            else:  # '>'
                x_lo = max(x_lo, val + 1)
        elif cat == 'm':
            if op == '<':
                m_hi = min(m_hi, val - 1)
            else:
                m_lo = max(m_lo, val + 1)
        elif cat == 'a':
            if op == '<':
                a_hi = min(a_hi, val - 1)
            else:
                a_lo = max(a_lo, val + 1)
        elif cat == 's':
            if op == '<':
                s_hi = min(s_hi, val - 1)
            else:
                s_lo = max(s_lo, val + 1)
        else:
            raise ValueError("Unknown category")

        return (x_lo, x_hi, m_lo, m_hi, a_lo, a_hi, s_lo, s_hi)

    def complement_intersect(box, cat, op, val):
        # Intersect with the negation of predicate (cat op val).
        # For '<': complement is cat >= val
        # For '>': complement is cat <= val
        x_lo, x_hi, m_lo, m_hi, a_lo, a_hi, s_lo, s_hi = box

        if cat == 'x':
            if op == '<':
                x_lo = max(x_lo, val)
            else:  # '>'
                x_hi = min(x_hi, val)
        elif cat == 'm':
            if op == '<':
                m_lo = max(m_lo, val)
            else:
                m_hi = min(m_hi, val)
        elif cat == 'a':
            if op == '<':
                a_lo = max(a_lo, val)
            else:
                a_hi = min(a_hi, val)
        elif cat == 's':
            if op == '<':
                s_lo = max(s_lo, val)
            else:
                s_hi = min(s_hi, val)
        else:
            raise ValueError("Unknown category")

        return (x_lo, x_hi, m_lo, m_hi, a_lo, a_hi, s_lo, s_hi)

    @lru_cache(maxsize=None)
    def dfs(workflow_name, box):
        if workflow_name == "A":
            return volume(box)
        if workflow_name == "R":
            return 0

        rules = workflows[workflow_name]
        remaining = box
        total = 0

        for cat, op, val, dest in rules:
            if cat is None:
                # Unconditional rule: first matching semantics means we route all remaining.
                total += dfs(dest, remaining)
                break

            matched = intersect(remaining, cat, op, val)
            if volume(matched) != 0:
                total += dfs(dest, matched)

            remaining = complement_intersect(remaining, cat, op, val)
            if volume(remaining) == 0:
                break

        return total

    return dfs("in", initial_box)

def main():
    data = sys.stdin.read().splitlines()
    # Split into workflow section and parts section by first blank line
    workflows_lines = []
    i = 0
    while i < len(data) and data[i].strip() != "":
        workflows_lines.append(data[i])
        i += 1

    workflows = parse_workflows(workflows_lines)
    ans = solve_part_two(workflows)
    print(ans)

if __name__ == "__main__":
    main()

