import sys
from collections import deque, defaultdict

def solve(data: str) -> str:
    lines = [line.strip() for line in data.splitlines() if line.strip()]
    if not lines:
        return ""

    # Module types: broadcaster, flipflop, conjunction
    mod_type = {}
    dests = defaultdict(list)

    for line in lines:
        left, right = line.split(" -> ")
        left = left.strip()
        right = right.strip()

        if left == "broadcaster":
            mod_type["broadcaster"] = "broadcaster"
            name = "broadcaster"
        elif left.startswith("%"):
            name = left[1:]
            mod_type[name] = "flipflop"
        elif left.startswith("&"):
            name = left[1:]
            mod_type[name] = "conjunction"
        else:
            # Shouldn't happen for valid inputs, but keep robust
            name = left
            # Treat as untyped sink (no internal behavior)
        dest_list = [x.strip() for x in right.split(",")]
        dests[name].extend(dest_list)

    # Precompute inputs to each conjunction for initial memory
    inputs_to = defaultdict(list)  # conjunction -> list of input module names
    for u, outs in dests.items():
        for v in outs:
            if mod_type.get(v) == "conjunction":
                inputs_to[v].append(u)

    # Initialize flip-flops (off) and conjunction memory (all low)
    flip_state = {name: 0 for name, t in mod_type.items() if t == "flipflop"}  # 0=off, 1=on
    mem = {}  # conjunction -> dict[input_module] = last_pulse (0=low, 1=high)
    for c, ins in inputs_to.items():
        mem[c] = {src: 0 for src in ins}

    LOW, HIGH = 0, 1

    low_count = 0
    high_count = 0

    # Simulate 1000 button presses
    for _ in range(1000):
        q = deque()
        # button sends a single low pulse to broadcaster
        q.append(("button", LOW, "broadcaster"))

        while q:
            sender, pulse, receiver = q.popleft()

            if pulse == LOW:
                low_count += 1
            else:
                high_count += 1

            # If receiver is an untyped sink or unknown, it does nothing further
            rtype = mod_type.get(receiver)
            if rtype is None:
                continue

            if rtype == "broadcaster":
                for v in dests.get(receiver, []):
                    q.append((receiver, pulse, v))

            elif rtype == "flipflop":
                if pulse == HIGH:
                    continue  # ignored
                # toggle on low pulse
                flip_state[receiver] ^= 1
                out_pulse = HIGH if flip_state[receiver] == 1 else LOW
                for v in dests.get(receiver, []):
                    q.append((receiver, out_pulse, v))

            elif rtype == "conjunction":
                # Update memory for this sender
                # Sender might be "button" or some module; conjunction memory should include all real inputs.
                # If sender wasn't in memory (shouldn't happen with correct inputs_to), treat as low default.
                if receiver not in mem:
                    mem[receiver] = {}
                if sender not in mem[receiver]:
                    mem[receiver][sender] = 0
                mem[receiver][sender] = pulse

                # If all remembered inputs are HIGH -> send LOW, else send HIGH
                all_high = True
                for val in mem[receiver].values():
                    if val != HIGH:
                        all_high = False
                        break
                out_pulse = LOW if all_high else HIGH

                for v in dests.get(receiver, []):
                    q.append((receiver, out_pulse, v))

    return str(low_count * high_count)

if __name__ == "__main__":
    data = sys.stdin.read()
    sys.stdout.write(solve(data))

