    # Build reverse adjacency: inputs[dest] = list of sources that feed into dest
    inputs = defaultdict(list)
    for src, outs in dests.items():
        for dst in outs:
            inputs[dst].append(src)

    return type_map, dests, inputs

def reset_states(type_map, inputs):
    ff_state = {}  # only for flipflop
    conj_mem = {}  # conj_mem[conj][input] = 'low'/'high'

    for name, t in type_map.items():
        if t == "flipflop":
            ff_state[name] = 0  # 0=off, 1=on
        elif t == "conjunction":
            mem = {}
            for src in inputs[name]:
                mem[src] = 0  # 0=low, 1=high
            conj_mem[name] = mem
    return ff_state, conj_mem

def simulate_button_presses(type_map, dests, inputs, presses, count_pulses=False, watch_rx=False, watch_conj=None):
    """
    watch_conj: optional tuple (conj_name, sender_name) to record high pulses from sender to conj.
                 Returns list of press indices when such high occurs.
    """
    ff_state, conj_mem = reset_states(type_map, inputs)

