                    q.append((receiver, out_pulse, dst))
                    if count_pulses:
                        if out_pulse == 0:
                            low_count += 1
                        else:
                            high_count += 1

            else:
                # untyped sink: do nothing
                continue

    return low_count, high_count, rx_low_press, high_hits

