        # The "high from sender to conj" events correspond to sender's pulses that set memory to HIGH.
        # We measure the period of those events and then LCM.
        periods = []
        for si in conj_inputs:
            # watch high pulses from si to conj (i.e., conj processes an input pulse from si and outputs HIGH)
            # But we need the times when conj's memory for si becomes HIGH, which happens when si sends HIGH to conj.
