            hits = []
            press = 0
            while len(hits) < 2:
                press += 1
                q = deque()
                q.append(("button", 0, "broadcaster"))
                while q:
                    sender, pulse, receiver = q.popleft()
                    rtype = type_map.get(receiver, "untyped")

                    if receiver == conj and sender == si and pulse == 1:
                        hits.append(press)
                        if len(hits) >= 2:
                            # still must fully handle this press; but we can stop after press completes
                            pass

                    if rtype == "broadcaster":
                        for dst in dests[receiver]:
                            q.append((receiver, pulse, dst))
                    elif rtype == "flipflop":
                        if pulse == 1:
                            continue
                        ff_state[receiver] ^= 1
                        out_pulse = ff_state[receiver]
                        for dst in dests[receiver]:
                            q.append((receiver, out_pulse, dst))
                    elif rtype == "conjunction":
                        mem = conj_mem[receiver]
                        if sender not in mem:
                            mem[sender] = 0
                        mem[sender] = pulse
                        all_high = True
                        for v in mem.values():
                            if v == 0:
                                all_high = False
                                break
                        out_pulse = 0 if all_high else 1
                        for dst in dests[receiver]:
                            q.append((receiver, out_pulse, dst))
                    else:
                        continue

                # loop continues to next press if needed

            periods.append(hits[1] - hits[0])

        # Candidate answer is LCM of periods
        ans = 1
        for p in periods:
            ans = lcm(ans, p)

        # Verify by direct simulation until rx receives low
        _, _, rx_low_press, _ = simulate_button_presses(type_map, dests, inputs, presses=ans, watch_rx=True)
        # rx_low_press should be exactly ans for correct inputs; if not, keep searching.
        if rx_low_press is None:
            # Search forward (should be rare)
            press = ans
            while True:
                press += 1
                _, _, rx_low_press2, _ = simulate_button_presses(type_map, dests, inputs, presses=press, watch_rx=True)
                if rx_low_press2 is not None:
                    return rx_low_press2
        return rx_low_press if rx_low_press is not None else ans

    # General fallback: brute-force simulate until rx gets low.
    # This is safe for small/unknown inputs.
    press = 0
    while True:
        press += 1
        _, _, rx_low_press, _ = simulate_button_presses(type_map, dests, inputs, presses=press, watch_rx=True)
        if rx_low_press is not None:
            return rx_low_press

def main():
    lines = sys.stdin.read().strip().splitlines()
    type_map, dests, inputs = parse_input(lines)

    p1 = part1(type_map, dests, inputs)
    p2 = part2(type_map, dests, inputs)

    print(p1)
    print(p2)

if __name__ == "__main__":
    main()

