import sys

def solve():
    lines = [line.rstrip("\n") for line in sys.stdin.read().splitlines() if line.strip() != ""]
    if not lines:
        return

    R = len(lines)
    C = max(len(line) for line in lines)

    grid = []
    sr = sc = None
    for r in range(R):
        row = lines[r]
        if 'S' in row:
            sr = r
            sc = row.index('S')
        if len(row) < C:
            row = row + ('#' * (C - len(row)))
        grid.append(row)

    if sr is None:
        print(0)
        return

    def walkable(r, c):
        return 0 <= r < R and 0 <= c < C and grid[r][c] != '#'

    K = 64
    frontier = {(sr, sc)}
    dirs = [(1, 0), (-1, 0), (0, 1), (0, -1)]

    for _ in range(K):
        nxt = set()
        for r, c in frontier:
            for dr, dc in dirs:
                nr, nc = r + dr, c + dc
                if walkable(nr, nc):
                    nxt.add((nr, nc))
        frontier = nxt

    print(len(frontier))

if __name__ == "__main__":
    solve()

