import sys
from collections import defaultdict

def parse_input():
    bricks = []
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        a, b = line.split("~")
        x1, y1, z1 = map(int, a.split(","))
        x2, y2, z2 = map(int, b.split(","))
        if x1 > x2: x1, x2 = x2, x1
        if y1 > y2: y1, y2 = y2, y1
        if z1 > z2: z1, z2 = z2, z1
        bricks.append((x1, x2, y1, y2, z1, z2))
    return bricks

def enumerate_cells(brick):
    x1, x2, y1, y2, z1, z2 = brick
    cells = []
    for x in range(x1, x2 + 1):
        for y in range(y1, y2 + 1):
            for z in range(z1, z2 + 1):
                cells.append((x, y, z))
    return cells

def solve(bricks_in):
    B = len(bricks_in)
    # Precompute occupied cells for each brick in its initial position
    brick_cells = [enumerate_cells(br) for br in bricks_in]

    # Sort bricks by their initial minZ (z1 after normalization)
    order = sorted(range(B), key=lambda i: bricks_in[i][4])

    # Occupancy map: (x,y,z) -> brick_id for settled bricks
