def solve():
    lines = [line.rstrip("\n") for line in sys.stdin if line.strip("\n") != ""]
    if not lines:
        return
    R = len(lines)
    C = len(lines[0])
    grid = [list(row) for row in lines]

    # Find start (only non-# in top row) and end (only non-# in bottom row)
    start_c = None
    end_c = None
    for c in range(C):
        if grid[0][c] != '#':
            start_c = c
            break
    for c in range(C):
        if grid[R - 1][c] != '#':
            end_c = c
            break
    start = (0, start_c)
    end = (R - 1, end_c)

    # Movement rules: directed edges induced by slopes
    dirs = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    slope_out = {
        '>': [(0, 1)],
        '<': [(0, -1)],
        '^': [(-1, 0)],
        'v': [(1, 0)],
    }

    def is_walkable(r, c):
        return 0 <= r < R and 0 <= c < C and grid[r][c] != '#'

    def outgoing(u):
        r, c = u
        ch = grid[r][c]
        if ch in slope_out:
            cand = slope_out[ch]
        else:
            cand = dirs  # '.' and also treat any other non-# as '.'-like
        res = []
        for dr, dc in cand:
            nr, nc = r + dr, c + dc
            if is_walkable(nr, nc):
                res.append((nr, nc))
        return res

    # Precompute outdegree for all walkable tiles
    outdeg = {}
    walkable = []
    for r in range(R):
        for c in range(C):
            if grid[r][c] != '#':
                walkable.append((r, c))
                outdeg[(r, c)] = len(outgoing((r, c)))

    # Node marking: start/end and any tile with outdegree != 1
    is_node = set()
    for u in walkable:
        if u == start or u == end or outdeg[u] != 1:
            is_node.add(u)

    # Stronger safety: if a non-node tile has outdeg != 1, it would already be a node.
    # Additionally, ensure corridor-following determinism by marking tiles with indeg != 1 as nodes.
    # This helps preserve correctness if indegree patterns cause overlaps.
    indeg = {u: 0 for u in walkable}
    for u in walkable:
        for v in outgoing(u):
            indeg[v] += 1
    for u in walkable:
        if u == start or u == end:
            continue
        if indeg[u] != 1 or outdeg[u] != 1:
            is_node.add(u)

    # Build compressed directed weighted graph
    node_list = list(is_node)
    node_id = {u: i for i, u in enumerate(node_list)}
    G = [[] for _ in range(len(node_list))]  # edges: (to_id, weight)

    def follow(u, v):
        # Start from u, take first step to v, then follow forced corridor until next node
        # Assumes v is walkable and not a node (or could be a node).
        dist = 1
        cur = v
        prev = u
        while cur not in is_node:
            outs = outgoing(cur)
            # In a corridor, outdeg should be 1; if not, treat as node to be safe
            if len(outs) != 1:
                is_node.add(cur)
                # Update node_id and G lazily is complex; instead, we ensure by marking indeg/outdeg != 1 earlier.
                # If this happens, we will break and treat cur as node by returning it.
                break
            nxt = outs[0]
            prev, cur = cur, nxt
            dist += 1
        return cur, dist

    # Ensure node_id includes any late additions (shouldn't happen often)
    # We'll rebuild if needed.
    # First, check if any tile not in is_node would be encountered with outdeg != 1 during follow.
    # Since we already marked outdeg!=1 and indeg!=1 as nodes, this should not occur.
    # Still, handle robustly by rebuilding if new nodes appear.
    # We'll do a two-pass: build edges, and if follow returns a node not in node_id, rebuild.
    def build_graph():
        nonlocal node_list, node_id, G
        node_list = list(is_node)
        node_id = {u: i for i, u in enumerate(node_list)}
        G = [[] for _ in range(len(node_list))]

        for u in node_list:
            uid = node_id[u]
            for v in outgoing(u):
                w, dist = follow(u, v)
                if w not in node_id:
                    # Mark and rebuild
                    is_node.add(w)
                    return False
                wid = node_id[w]
                G[uid].append((wid, dist))
        return True

    ok = build_graph()
    if not ok:
        # Rebuild until stable (should converge quickly)
        while True:
            ok = build_graph()
            if ok:
                break

    start_id = node_id[start]
    end_id = node_id[end]

    # Sort edges by weight descending for faster finding of long paths
    for u in range(len(G)):
        G[u].sort(key=lambda x: x[1], reverse=True)

    # DFS for longest simple path in compressed graph (no revisiting nodes)
    visited = [False] * len(G)
    best = 0

    def dfs(u, acc):
        nonlocal best
        if u == end_id:
            if acc > best:
                best = acc
            # Do not return early; there could be cycles that revisit end with longer acc,
            # but revisiting nodes is forbidden, so reaching end ends the path.
            return
        for v, w in G[u]:
            if not visited[v]:
                visited[v] = True
                dfs(v, acc + w)
                visited[v] = False

    visited[start_id] = True
    dfs(start_id, 0)

    print(best)

if __name__ == "__main__":
    solve()

