import sys

def count_xmas(grid, word="XMAS"):
    if not grid:
        return 0
    R = len(grid)
    C = len(grid[0])
    L = len(word)

    directions = [
        (0, 1),   # right
        (0, -1),  # left
        (1, 0),   # down
        (-1, 0),  # up
        (1, 1),   # down-right
        (1, -1),  # down-left
        (-1, 1),  # up-right
        (-1, -1), # up-left
    ]

    count = 0
    for r in range(R):
        for c in range(C):
            if grid[r][c] != word[0]:
                continue
            for dr, dc in directions:
                ok = True
                for k in range(L):
                    nr = r + k * dr
                    nc = c + k * dc
                    if nr < 0 or nr >= R or nc < 0 or nc >= C or grid[nr][nc] != word[k]:
                        ok = False
                        break
                if ok:
                    count += 1
    return count

def main():
    grid = [line.rstrip("\n") for line in sys.stdin if line.strip("\n") != ""]
    if not grid:
        return
    print(count_xmas(grid))

