import sys

def solve(data: str) -> int:
    lines = [line.strip() for line in data.splitlines()]
    rules = []
    updates = []
    parsing_rules = True

    for line in lines:
        if not line:
            parsing_rules = False
            continue
        if parsing_rules:
            x_str, y_str = line.split("|")
            rules.append((int(x_str), int(y_str)))
        else:
            pages = [int(x) for x in line.split(",") if x != ""]
            if pages:
                updates.append(pages)

    # after[x] = set of y such that rule x|y exists
    after = {}
    for x, y in rules:
        after.setdefault(x, set()).add(y)

    total = 0
    for pages in updates:
        pos = {p: i for i, p in enumerate(pages)}
        valid = True

        # Check only applicable rules where both endpoints are present in this update
        for x in pages:
            if x not in after:
                continue
            px = pos[x]
            for y in after[x]:
                if y in pos and px >= pos[y]:
                    valid = False
                    break
            if not valid:
                break

        if valid:
            total += pages[len(pages) // 2]

    return total

def main():
    data = sys.stdin.read()
    print(solve(data))

if __name__ == "__main__":
    main()

