import sys
from collections import deque, defaultdict

def solve(data: str) -> int:
    lines = [line.strip() for line in data.splitlines()]
    rules = []
    updates = []
    parsing_rules = True

    for line in lines:
        if not line:
            parsing_rules = False
            continue
        if parsing_rules:
            x, y = line.split("|")
            rules.append((int(x), int(y)))
        else:
            updates.append([int(v) for v in line.split(",")])

    # Build adjacency list for the global rule graph
    adj = defaultdict(list)
    for x, y in rules:
        adj[x].append(y)

    part2_sum = 0

    for upd in updates:
        pages = set(upd)
        pos = {p: i for i, p in enumerate(upd)}

        # Check if update already satisfies all applicable rules
        correct = True
        for x in pages:
            px = pos[x]
            for y in adj.get(x, ()):
                if y in pages and px >= pos[y]:
                    correct = False
                    break
            if not correct:
                break

        if correct:
            continue

        # Build induced subgraph and topologically sort it
        indeg = {p: 0 for p in pages}
        for x in pages:
            for y in adj.get(x, ()):
                if y in pages:
                    indeg[y] += 1

        q = deque([p for p in pages if indeg[p] == 0])
        topo = []

        while q:
            n = q.popleft()
            topo.append(n)
            for m in adj.get(n, ()):
                if m in indeg:
                    indeg[m] -= 1
                    if indeg[m] == 0:
                        q.append(m)

        # If there is a cycle, topo won't include all nodes; problem inputs are assumed valid.
        if len(topo) != len(upd):
            # Fallback: keep original order for safety (should not happen with valid inputs)
            topo = upd[:]

        part2_sum += topo[len(upd) // 2]

    return part2_sum

def main():
    data = sys.stdin.read()
    print(solve(data))

if __name__ == "__main__":
    main()

