import sys
import math

def digits(x: int) -> int:
    return 1 if x == 0 else int(math.log10(x)) + 1

def can_make(target: int, nums: list[int], allow_concat: bool) -> bool:
    if not nums:
        return False
    if len(nums) == 1:
        return nums[0] == target

    reachable = {nums[0]}
    for x in nums[1:]:
        nxt = set()
        for v in reachable:
            s = v + x
            if s <= target:
                nxt.add(s)

            p = v * x
            if p <= target:
                nxt.add(p)

            if allow_concat:
                c = v * (10 ** digits(x)) + x
                if c <= target:
                    nxt.add(c)

        if not nxt:
            return False
        reachable = nxt

    return target in reachable

def solve() -> None:
    lines = [line.strip() for line in sys.stdin.read().splitlines() if line.strip()]
    equations = []
    for line in lines:
        left, right = line.split(":")
        target = int(left.strip())
        nums = list(map(int, right.strip().split()))
        equations.append((target, nums))

    total = 0
    for target, nums in equations:
        if can_make(target, nums, allow_concat=True):
            total += target

    print(total)

if __name__ == "__main__":
    solve()

