import sys
from collections import defaultdict

def solve():
    grid = [line.rstrip("\n") for line in sys.stdin if line.strip("\n") != ""]
    if not grid:
        return
    H = len(grid)
    W = len(grid[0])

    freq_pos = defaultdict(list)
    for r in range(H):
        row = grid[r]
        # If input might contain ragged lines, normalize by treating missing as '.'
        if len(row) != W:
            row = row.ljust(W, '.')
        for c, ch in enumerate(row):
            if ch != '.':
                freq_pos[ch].append((r, c))

    antinodes = set()

    for positions in freq_pos.values():
        k = len(positions)
        if k < 2:
            continue
        for i in range(k):
            r1, c1 = positions[i]
            for j in range(i + 1, k):
                r2, c2 = positions[j]
                dr = r1 - r2
                dc = c1 - c2

                # Candidate beyond A (away from B): (2*r1 - r2, 2*c1 - c2)
                r3 = r1 + dr
                c3 = c1 + dc
                if 0 <= r3 < H and 0 <= c3 < W:
                    antinodes.add(r3 * W + c3)

                # Candidate beyond B (away from A): (2*r2 - r1, 2*c2 - c1)
                r4 = r2 - dr
                c4 = c2 - dc
                if 0 <= r4 < H and 0 <= c4 < W:
                    antinodes.add(r4 * W + c4)

    print(len(antinodes))

if __name__ == "__main__":
    solve()

