import sys

def solve():
    lines = [line.strip() for line in sys.stdin if line.strip() != ""]
    if not lines:
        return

    R = len(lines)
    C = len(lines[0])
    h = [[ord(ch) - 48 for ch in row] for row in lines]

    # Assign an id to each height-9 cell for bitset DP
    nine_id = [[-1] * C for _ in range(R)]
    nine_cells = []
    for r in range(R):
        for c in range(C):
            if h[r][c] == 9:
                nine_id[r][c] = len(nine_cells)
                nine_cells.append((r, c))
    K = len(nine_cells)

    # dp[r][c] is a bitset (Python int) of reachable 9 endpoints from (r,c)
    dp = [[0] * C for _ in range(R)]
    for r in range(R):
        for c in range(C):
            if h[r][c] == 9:
                dp[r][c] = 1 << nine_id[r][c]

    # Process heights from 8 down to 0
    dirs = ((1, 0), (-1, 0), (0, 1), (0, -1))
    for height in range(8, -1, -1):
        for r in range(R):
            for c in range(C):
                if h[r][c] != height:
                    continue
                mask = 0
                nh = height + 1
                for dr, dc in dirs:
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < R and 0 <= nc < C and h[nr][nc] == nh:
