    # Sum scores for all trailheads (height 0)
    total = 0
    for r in range(R):
        for c in range(C):
            if h[r][c] == 0:
                total += dp[r][c].bit_count()

    sys.stdout.write(str(total))

if __name__ == "__main__":
    solve()

