import sys
from functools import lru_cache

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    stones = list(map(int, data))
    T = 25

    @lru_cache(maxsize=None)
    def f(x, t):
        if t == 0:
            return 1
        if x == 0:
            return f(1, t - 1)

        s = str(x)
        if len(s) % 2 == 0:
            mid = len(s) // 2
            left = int(s[:mid])
            right = int(s[mid:])
            return f(left, t - 1) + f(right, t - 1)
        else:
            return f(x * 2024, t - 1)

    total = 0
    for x in stones:
        total += f(x, T)

    sys.stdout.write(str(total))

if __name__ == "__main__":
    solve()

