import sys
from collections import deque

def solve(grid):
    if not grid:
        return 0
    R = len(grid)
    C = len(grid[0])

    visited = [[False] * C for _ in range(R)]
    dirs = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    total_price = 0

    for r in range(R):
        for c in range(C):
            if visited[r][c]:
                continue

            ch = grid[r][c]
            q = deque([(r, c)])
            visited[r][c] = True

            area = 0
            perimeter = 0

            while q:
                x, y = q.popleft()
                area += 1

                for dr, dc in dirs:
