import sys
from collections import deque, defaultdict

def solve():
    grid = [line.rstrip("\n") for line in sys.stdin if line.strip() != ""]
    if not grid:
        return
    R, C = len(grid), len(grid[0])

    dirs = [(-1, 0), (1, 0), (0, -1), (0, 1)]  # up, down, left, right

    def boundary_edge_for_cell(r, c, dr, dc):
        # Cell is square with corners:
        # (c, r) (c+1, r)
        # (c, r+1) (c+1, r+1)
        # If neighbor in (dr,dc) is outside/different, that side is boundary.
        if dr == -1 and dc == 0:      # up
            return (c, r), (c + 1, r)
        if dr == 1 and dc == 0:       # down
            return (c, r + 1), (c + 1, r + 1)
        if dr == 0 and dc == -1:      # left
            return (c, r), (c, r + 1)
        # right
        return (c + 1, r), (c + 1, r + 1)

    def vec(u, v):
        return (v[0] - u[0], v[1] - u[1])

    # Deterministic next-edge choice using a left-hand rule.
    # Incoming direction is (dx,dy). We prefer turning left, then going straight, then right.
    def choose_next(prev, cur, adj):
        incoming = vec(prev, cur)
        dx, dy = incoming
        left = (-dy, dx)
        right = (dy, -dx)
        straight = (-dx, -dy)  # would go back to prev; but prev is excluded from candidates

        candidates = [n for n in adj[cur] if n != prev]
        if not candidates:
            return None
        if len(candidates) == 1:
            return candidates[0]

        for n in candidates:
            if vec(cur, n) == left:
                return n
        # "straight" relative to incoming means continuing in same direction as incoming
        # which is (dx,dy). Since candidates are neighbors, check that.
        for n in candidates:
            if vec(cur, n) == (dx, dy):
                return n
        for n in candidates:
            if vec(cur, n) == right:
                return n
        return candidates[0]

    visited = [[False] * C for _ in range(R)]
    total = 0

    for sr in range(R):
        for sc in range(C):
            if visited[sr][sc]:
                continue

            ch = grid[sr][sc]
            q = deque([(sr, sc)])
            visited[sr][sc] = True
            area = 0
            boundary_edges = set()  # undirected edges between vertices

            while q:
                r, c = q.popleft()
                area += 1
                for dr, dc in dirs:
                    nr, nc = r + dr, c + dc
                    if nr < 0 or nr >= R or nc < 0 or nc >= C or grid[nr][nc] != ch:
                        a, b = boundary_edge_for_cell(r, c, dr, dc)
                        if a > b:
                            a, b = b, a
                        boundary_edges.add((a, b))
                    else:
                        if not visited[nr][nc]:
                            visited[nr][nc] = True
                            q.append((nr, nc))

            # Build adjacency of boundary vertices
            adj = defaultdict(list)
            for a, b in boundary_edges:
                adj[a].append(b)
                adj[b].append(a)

            # Traverse boundary cycles.
            # IMPORTANT FIX: mark undirected edges as used so we don't traverse each cycle twice.
            used_undirected = set()
            sides = 0

            for a, b in list(boundary_edges):
                # If this undirected edge already used, skip starting from it.
                if (a, b) in used_undirected:
                    continue

                # Start a traversal from one endpoint; we will follow until we return.
                start_u, start_v = a, b
                prev = start_u
                cur = start_v

                # Mark the starting undirected edge used
                x, y = prev, cur
                if x > y:
                    x, y = y, x
                used_undirected.add((x, y))

                dprev = vec(prev, cur)
                corners = 0

                while True:
                    nxt = choose_next(prev, cur, adj)
                    if nxt is None:
                        break

                    # Count corner when direction changes
                    dcur = vec(cur, nxt)
                    if dcur != dprev:
                        corners += 1

                    # If next edge already used, we are closing/finishing
                    x, y = cur, nxt
                    if x > y:
                        x, y = y, x
                    if (x, y) in used_undirected:
                        break

                    used_undirected.add((x, y))
                    prev, cur = cur, nxt
                    dprev = dcur

                    if prev == start_u and cur == start_v:
                        break

                sides += corners

            total += area * sides

    print(total)

if __name__ == "__main__":
    solve()

