import sys
import math
import re

def egcd(a, b):
    # returns (g, x, y) such that a*x + b*y = g
    if b == 0:
        return (abs(a), 1 if a >= 0 else -1, 0)
    g, x1, y1 = egcd(b, a % b)
    x = y1
    y = x1 - (a // b) * y1
    return (g, x, y)

def ceil_div(a, b):
    # smallest integer t such that t >= a/b (b != 0)
    if b < 0:
        a, b = -a, -b
    if a >= 0:
        return (a + b - 1) // b
    return a // b  # Python floors, which is already ceil for negative a

def floor_div(a, b):
    # largest integer t such that t <= a/b (b != 0)
    if b < 0:
        a, b = -a, -b
    if a >= 0:
        return a // b
    # for negative a, floor is more negative; Python's // already floors
    return -((-a + b - 1) // b)

def solve_machine(ax, ay, bx, by, px, py):
    # Handle zero vectors
    if ax == 0 and ay == 0 and bx == 0 and by == 0:
        return 0 if (px == 0 and py == 0) else None

    if ax == 0 and ay == 0:
        # Only B can move; i must be 0 to satisfy exact position
        if bx == 0 and by == 0:
            return 0 if (px == 0 and py == 0) else None
        # Need j*B = P
        if bx == 0:
            if px != 0:
                return None
            if by == 0:
                return 0 if py == 0 else None
            if py % by != 0:
                return None
            j = py // by
        else:
            if px % bx != 0:
                return None
            j = px // bx
            if by * j != py:
                return None
        if j < 0:
            return None
        return j  # cost = 3*i + 1*j, i=0

    if bx == 0 and by == 0:
        # Only A can move; j must be 0
        if ax == 0 and ay == 0:
            return 0 if (px == 0 and py == 0) else None
        if ax == 0:
            if py % ay != 0:
                return None
            i = py // ay
            if px != 0:
                return None
        else:
            if px % ax != 0:
                return None
            i = px // ax
            if ay * i != py:
                return None
        if i < 0:
            return None
        return 3 * i  # cost = 3*i + j, j=0

    det = ax * by - ay * bx
    if det != 0:
        # Unique rational solution via Cramer's rule
        i_num = px * by - py * bx
        j_num = ax * py - ay * px

        if i_num % det != 0 or j_num % det != 0:
            return None
        i = i_num // det
        j = j_num // det
        if i < 0 or j < 0:
            return None
        return 3 * i + j

    # Degenerate: det == 0, vectors are collinear or one is zero (handled above)
    # Check consistency: P must be collinear with A (and B)
    if ax * py - ay * px != 0:
        return None

    # Reduce to 1D equation using an axis where coefficients are not both zero
    # Prefer X if possible, else Y.
    if ax != 0 or bx != 0:
        A1, B1, P1 = ax, bx, px
    else:
        A1, B1, P1 = ay, by, py

    # Solve A1*i + B1*j = P1 with i,j >= 0 minimizing 3i + j
    g, x0, y0 = egcd(A1, B1)  # A1*x0 + B1*y0 = g (up to sign handled in egcd)
    if P1 % g != 0:
        return None

    mult = P1 // g
    i0 = x0 * mult
    j0 = y0 * mult

    # General solution:
    # i = i0 + (B1/g)*t
    # j = j0 - (A1/g)*t
    di = B1 // g
    dj = -A1 // g

    # Feasible t range from i>=0 and j>=0
    t_low = -10**30
    t_high = 10**30

    if di == 0:
        if i0 < 0:
            return None
    else:
        # i0 + di*t >= 0
        if di > 0:
            t_low = max(t_low, ceil_div(-i0, di))
        else:
            t_high = min(t_high, floor_div(-i0, di))

    if dj == 0:
        if j0 < 0:
            return None
    else:
        # j0 + dj*t >= 0
        if dj > 0:
            t_low = max(t_low, ceil_div(-j0, dj))
        else:
            t_high = min(t_high, floor_div(-j0, dj))

    if t_low > t_high:
        return None

    # Cost(t) = 3*i + j = 3*(i0 + di*t) + (j0 + dj*t) = (3*i0 + j0) + t*(3*di + dj)
    slope = 3 * di + dj
    # Minimum over integer t in [t_low, t_high] occurs at an endpoint
    candidates = [t_low, t_high]
    best = None
    for t in candidates:
        i = i0 + di * t
        j = j0 + dj * t
        if i >= 0 and j >= 0:
            cost = 3 * i + j
            if best is None or cost < best:
                best = cost
    return best

def parse_input(lines):
