        if bx == 0 and by == 0:
            return 0 if (px == 0 and py == 0) else None
        # Need j*B = P
        if bx == 0:
            if px != 0:
                return None
            if by == 0:
                return 0 if py == 0 else None
            if py % by != 0:
                return None
            j = py // by
        else:
