import sys

def solve():
    lines = [line.rstrip("\n") for line in sys.stdin.readlines()]
    # Split into map and moves (moves may have blank lines)
    map_lines = []
    move_lines = []
    in_moves = False
    for line in lines:
        if not in_moves and line and all(ch in "#.@O" for ch in line):
            map_lines.append(line)
        else:
            if line.strip() == "":
                if map_lines:
                    in_moves = True
                continue
            if not in_moves:
                # First non-map line starts moves
                in_moves = True
            move_lines.append(line.strip())

    grid = [list(row) for row in map_lines]
    h = len(grid)
    w = len(grid[0]) if h else 0

    rx = ry = -1
    for i in range(h):
        for j in range(w):
            if grid[i][j] == '@':
                rx, ry = i, j
                grid[i][j] = '.'

    moves = "".join(move_lines)
    dir_map = {'^': (-1, 0), 'v': (1, 0), '<': (0, -1), '>': (0, 1)}

    for c in moves:
        if c not in dir_map:
            continue
        dx, dy = dir_map[c]
        nx, ny = rx + dx, ry + dy

        # Bounds are assumed safe due to walls border, but keep checks anyway
        if not (0 <= nx < h and 0 <= ny < w):
            continue

        target = grid[nx][ny]
        if target == '#':
            continue
        if target == '.':
            rx, ry = nx, ny
            continue

        # target == 'O': push contiguous chain
        bx, by = nx, ny
        chain = []
        while 0 <= bx < h and 0 <= by < w and grid[bx][by] == 'O':
            chain.append((bx, by))
            bx += dx
            by += dy

        # Now (bx, by) is first non-box cell
        if not (0 <= bx < h and 0 <= by < w) or grid[bx][by] == '#':
            continue

        # Shift boxes one step in direction; update far to near to avoid overwrite
        for cx, cy in reversed(chain):
            grid[cx + dx][cy + dy] = 'O'
            grid[cx][cy] = '.'

        # Move robot into the old first box position
        rx, ry = nx, ny

    total = 0
    for i in range(h):
        for j in range(w):
            if grid[i][j] == 'O':
                total += 100 * i + j

    print(total)

if __name__ == "__main__":
    solve()

