import sys
import math

W = 101
H = 103

def mod_pos(a, m):
    return a % m

def parse_input(lines):
    robots = []
    for line in lines:
        line = line.strip()
        if not line:
            continue
        # Example: p=0,4 v=3,-3
        parts = line.split()
        ppart = parts[0].split('=')[1]
        vpart = parts[1].split('=')[1]
        px, py = map(int, ppart.split(','))
        vx, vy = map(int, vpart.split(','))
        robots.append((px, py, vx, vy))
    return robots

def pos_at(robot, t):
    px, py, vx, vy = robot
    x = mod_pos(px + vx * t, W)
    y = mod_pos(py + vy * t, H)
    return x, y

def safety_factor_after_100(robots):
    midX = W // 2
    midY = H // 2
    q1 = q2 = q3 = q4 = 0  # TL, TR, BL, BR
    for r in robots:
        x, y = pos_at(r, 100)
        if x == midX or y == midY:
            continue
        if x < midX and y < midY:
            q1 += 1
        elif x > midX and y < midY:
            q2 += 1
        elif x < midX and y > midY:
            q3 += 1
        elif x > midX and y > midY:
            q4 += 1
    return q1 * q2 * q3 * q4

def axis_cluster_width(values, m):
    # values are in [0, m-1]
    values = sorted(values)
    if not values:
        return 0
    # largest gap on the circle
    largest_gap = 0
    for i in range(len(values) - 1):
        gap = values[i + 1] - values[i]
        if gap > largest_gap:
            largest_gap = gap
    wrap_gap = (values[0] + m) - values[-1]
    if wrap_gap > largest_gap:
        largest_gap = wrap_gap
    return m - largest_gap

def score_at_time(robots, t):
    xs = []
    ys = []
    for r in robots:
        x, y = pos_at(r, t)
        xs.append(x)
        ys.append(y)
    return axis_cluster_width(xs, W) + axis_cluster_width(ys, H)

def render_grid(robots, t):
    grid = [['.' for _ in range(W)] for _ in range(H)]
    for r in robots:
        x, y = pos_at(r, t)
        grid[y][x] = '#'
    return "\n".join("".join(row) for row in grid)

def main():
    robots = parse_input(sys.stdin.read().splitlines())

    part1 = safety_factor_after_100(robots)

    period = W * H // math.gcd(W, H)  # lcm(101,103)=10403
    best_t = 0
    best_score = None

    # Scan all times; choose earliest time with minimal compactness score.
    for t in range(period):
        s = score_at_time(robots, t)
        if best_score is None or s < best_score or (s == best_score and t < best_t):
            best_score = s
            best_t = t

    # Optional verification: if multiple times tie for best_score, pick earliest.
    # (We already pick earliest among ties; rendering not required for correctness.)
    part2 = best_t

    sys.stdout.write(f"{part1}\n{part2}\n")

if __name__ == "__main__":
    main()

