import sys
import heapq
from collections import deque

def solve(data: str) -> str:
    lines = [line.rstrip("\n") for line in data.splitlines() if line.strip("\n") != ""]
    if not lines:
        return "0\n"
    R, C = len(lines), len(lines[0])
    grid = [list(row) for row in lines]

    sr = sc = er = ec = -1
    for r in range(R):
        for c in range(C):
            if grid[r][c] == 'S':
                sr, sc = r, c
            elif grid[r][c] == 'E':
                er, ec = r, c

    # Directions: 0=East, 1=South, 2=West, 3=North
    dr = [0, 1, 0, -1]
    dc = [1, 0, -1, 0]

    INF = 10**18
    # dist[r][c][dir]
    dist = [[[INF] * 4 for _ in range(C)] for __ in range(R)]
    # preds[r][c][dir] = list of predecessor states (pr, pc, pdir)
    preds = [[[[ ] for _ in range(4)] for __ in range(C)] for ___ in range(R)]

    start_dir = 0  # East
    dist[sr][sc][start_dir] = 0
    pq = [(0, sr, sc, start_dir)]

    def is_passable(r, c):
        return 0 <= r < R and 0 <= c < C and grid[r][c] != '#'

    while pq:
        d, r, c, dir_ = heapq.heappop(pq)
        if d != dist[r][c][dir_]:
            continue

        # 1) Forward move
        nr, nc = r + dr[dir_], c + dc[dir_]
        if is_passable(nr, nc):
            nd = d + 1
            if nd < dist[nr][nc][dir_]:
                dist[nr][nc][dir_] = nd
                preds[nr][nc][dir_] = [(r, c, dir_)]
                heapq.heappush(pq, (nd, nr, nc, dir_))
            elif nd == dist[nr][nc][dir_]:
                preds[nr][nc][dir_].append((r, c, dir_))

        # 2) Rotate clockwise
        ndir = (dir_ + 1) & 3
        nd = d + 1000
        if nd < dist[r][c][ndir]:
            dist[r][c][ndir] = nd
            preds[r][c][ndir] = [(r, c, dir_)]
            heapq.heappush(pq, (nd, r, c, ndir))
        elif nd == dist[r][c][ndir]:
            preds[r][c][ndir].append((r, c, dir_))

        # 3) Rotate counterclockwise
        ndir = (dir_ + 3) & 3
        nd = d + 1000
        if nd < dist[r][c][ndir]:
            dist[r][c][ndir] = nd
            preds[r][c][ndir] = [(r, c, dir_)]
            heapq.heappush(pq, (nd, r, c, ndir))
        elif nd == dist[r][c][ndir]:
            preds[r][c][ndir].append((r, c, dir_))

    best = min(dist[er][ec])
    if best >= INF:
        return "0\n"

    # Reverse traverse from all optimal end states
    onOptimalState = [[[False] * 4 for _ in range(C)] for __ in range(R)]
    q = deque()
    for dir_ in range(4):
        if dist[er][ec][dir_] == best:
            onOptimalState[er][ec][dir_] = True
            q.append((er, ec, dir_))

    while q:
        r, c, dir_ = q.popleft()
        for pr, pc, pdir in preds[r][c][dir_]:
            if not onOptimalState[pr][pc][pdir]:
                onOptimalState[pr][pc][pdir] = True
                q.append((pr, pc, pdir))

    # Count tiles that are part of at least one optimal path
    onOptimalTile = [[False] * C for _ in range(R)]
    for r in range(R):
        for c in range(C):
            if grid[r][c] == '#':
