                    if not inb(br, bc):
                        continue

                    if not passable[br][bc]:
                        continue
                    if distE[br][bc] >= INF:
                        continue

                    total = distS[ar][ac] + 2 + distE[br][bc]
                    if normal - total >= 100:
                        ans += 1

    print(ans)

if __name__ == "__main__":
    solve()

