    moves = NUM_MOVES[(d1, d2)]  # strings over '^v<>', shortest to move arm on numeric keypad
    best = 10**18
    for m in moves:
        # Lowest directional keypad must type (m + 'A') to press d2 on numeric keypad.
        # That typing is done by level 1 keypad, so we call dp(1, ...)
        seq = m + 'A'
        cur = 'A'
        total = 0
        for ch in seq:
            total += dp(1, cur, ch)
            cur = ch
        best = min(best, total)
    return best

def type_numeric_code(code):
    cur = 'A'
    total = 0
    for ch in code:
        total += numeric_transition_cost(cur, ch)
        cur = ch
    return total

def solve():
    codes = [line.strip() for line in sys.stdin if line.strip()]
    ans = 0
    for code in codes:
        # code ends with 'A'
        numeric_part = code[:-1]
        numeric_value = int(numeric_part.lstrip('0') or '0')
        presses = type_numeric_code(code)
        ans += presses * numeric_value
    print(ans)

if __name__ == "__main__":
    solve()

