def heights_from_block(block):
    h = len(block)
    w = len(block[0]) if h > 0 else 0

    top = block[0]
    bottom = block[-1]
    is_lock = all(ch == '#' for ch in top) and all(ch == '.' for ch in bottom)

    heights = [0] * w
    if is_lock:
        # Count consecutive '#' from top until first '.'
        for c in range(w):
            cnt = 0
            for r in range(h):
                if block[r][c] == '#':
                    cnt += 1
                else:
                    break
            heights[c] = cnt
    else:
        # Count consecutive '#' from bottom until first '.'
        for c in range(w):
            cnt = 0
            for r in range(h - 1, -1, -1):
                if block[r][c] == '#':
                    cnt += 1
                else:
                    break
            heights[c] = cnt

    return heights

def solve(data):
    lines = data.splitlines()
    blocks = parse_blocks(lines)

    locks = []
    keys = []
    for block in blocks:
        if not block:
            continue
        top = block[0]
        bottom = block[-1]
        is_lock = all(ch == '#' for ch in top) and all(ch == '.' for ch in bottom)
        heights = heights_from_block(block)
        if is_lock:
            locks.append(heights)
        else:
            keys.append(heights)

    if not locks or not keys:
        return "0"

    depth = len(blocks[0])  # schematic depth (rows per block)
