def parse_schematics(lines):
    blocks = []
    cur = []
    for line in lines:
        line = line.rstrip("\n")
        if line == "":
            if cur:
                blocks.append(cur)
                cur = []
        else:
            cur.append(line)
    if cur:
        blocks.append(cur)
    return blocks

def heights_from_block(block):
    H = len(block)
    W = len(block[0]) if H else 0
    # Determine lock vs key by top row / bottom row filled with '#'
    top_filled = all(ch == '#' for ch in block[0])
    bottom_filled = all(ch == '#' for ch in block[-1])

    if not (top_filled or bottom_filled):
        # Defensive: treat as lock if top row is filled, else key if bottom row is filled
        # (In valid inputs, one of these must be true.)
        raise ValueError("Invalid schematic: neither top row nor bottom row is fully filled with '#'.")

    if top_filled:
        # Lock: count consecutive '#' from top downward in each column
        heights = []
        for c in range(W):
            h = 0
            for r in range(H):
                if block[r][c] == '#':
                    h += 1
                else:
                    break
            heights.append(h)
        return True, heights  # True => lock
    else:
        # Key: count consecutive '#' from bottom upward in each column
        heights = []
        for c in range(W):
            h = 0
            for r in range(H - 1, -1, -1):
                if block[r][c] == '#':
                    h += 1
                else:
                    break
            heights.append(h)
        return False, heights  # False => key

