    lines = sys.stdin.read().splitlines()
    blocks = parse_schematics(lines)
    if not blocks:
        print(0)
        return

    locks = []
    keys = []
    H = None
    W = None

    for block in blocks:
        if not block:
            continue
        if H is None:
            H = len(block)
            W = len(block[0])
        # Assume consistent dimensions; if not, still compute per block but overlap check uses this H.
        is_lock, vec = heights_from_block(block)
        if is_lock:
            locks.append(vec)
        else:
            keys.append(vec)

    if not locks or not keys:
        print(0)
        return

    ans = 0
    for L in locks:
        for K in keys:
            ok = True
            for c in range(W):
                if L[c] + K[c] > H:
                    ok = False
                    break
            if ok:
                ans += 1

    print(ans)

if __name__ == "__main__":
    solve()

