import sys

def solve():
    line = sys.stdin.read().strip()
    if not line:
        return

    parts = [p.strip() for p in line.split(',')]
    ranges = []
    for p in parts:
        if not p:
            continue
        a, b = p.split('-')
        start = int(a)
        end = int(b)
        if start > end:
            start, end = end, start
        ranges.append((start, end))

    if not ranges:
        print(0)
        return

    # Merge ranges into disjoint intervals
    ranges.sort()
    merged = []
    cur_l, cur_r = ranges[0]
    for l, r in ranges[1:]:
        if l <= cur_r + 1:
            if r > cur_r:
                cur_r = r
        else:
            merged.append((cur_l, cur_r))
            cur_l, cur_r = l, r
    merged.append((cur_l, cur_r))

    max_end = max(r for _, r in merged)
    max_digits = len(str(max_end))

    ans = 0

    # Pointer for interval membership
    i = 0
    m = len(merged)

    # Generate invalid IDs: X repeated twice => full = X * 10^k + X, where len(X)=k and X has no leading zeros
    # Only even digit lengths up to max_digits are possible.
    for k in range(1, max_digits // 2 + 1):
        pow10 = 10 ** k
        x_start = 10 ** (k - 1)
        x_end = 10 ** k - 1

        # full increases monotonically with X for fixed k
        for x in range(x_start, x_end + 1):
            full = x * pow10 + x
            if full > max_end:
                break

            # Advance interval pointer until full <= current interval end
            while i < m and full > merged[i][1]:
                i += 1
            if i < m:
                l, r = merged[i]
                if l <= full <= r:
                    ans += full

    print(ans)

if __name__ == "__main__":
    solve()

