import sys

def best_subsequence_of_length_k(s: str, k: int) -> str:
    n = len(s)
    stack = []
    for i, ch in enumerate(s):
        rem = n - i - 1  # digits remaining after this position
        # Try to pop while it improves lexicographic order and we can still reach length k
        while stack and stack[-1] < ch:
            ssz = len(stack)
            # If we pop one digit, stack becomes ssz-1.
            # After processing current digit, we will add ch (so +1),
            # and we still have rem digits later.
            # Need: (ssz-1) + 1 + rem >= k  <=> (ssz-1) + rem >= k-1
            if (ssz - 1) + rem >= k - 1:
                stack.pop()
            else:
                break
        if len(stack) < k:
            stack.append(ch)
    return ''.join(stack)

def solve():
    lines = [line.strip() for line in sys.stdin.read().splitlines() if line.strip()]
    k = 12
    total = 0
    for bank in lines:
        best = best_subsequence_of_length_k(bank, k)
        total += int(best)
    print(total)

if __name__ == "__main__":
    solve()

