import sys
from bisect import bisect_right

def solve(data: str) -> str:
    lines = [line.strip() for line in data.splitlines()]
    # Split into ranges section and queries section by the first blank line
    blank_idx = None
    for i, line in enumerate(lines):
        if line == "":
            blank_idx = i
            break

    if blank_idx is None:
        range_lines = [l for l in lines if l != ""]
        query_lines = []
    else:
        range_lines = [l for l in lines[:blank_idx] if l != ""]
        query_lines = [l for l in lines[blank_idx + 1:] if l != ""]

    intervals = []
    for s in range_lines:
        if not s:
            continue
        a, b = s.split("-")
        L, R = int(a), int(b)
        if L > R:
            L, R = R, L
        intervals.append((L, R))

    if not intervals or not query_lines:
        return "0"

    # Sort and merge overlapping/touching intervals
    intervals.sort(key=lambda x: (x[0], x[1]))
    merged = []
    for L, R in intervals:
        if not merged:
            merged.append([L, R])
        else:
            a, b = merged[-1]
            # Merge if overlapping or touching (inclusive ranges)
            if L <= b + 1:
                merged[-1][1] = max(b, R)
            else:
                merged.append([L, R])

    # Prepare starts for binary search
    starts = [L for L, _ in merged]

    fresh_count = 0
    for q in query_lines:
        if not q:
            continue
        x = int(q)
        # Find rightmost interval with start <= x
        i = bisect_right(starts, x) - 1
        if i >= 0 and x <= merged[i][1]:
            fresh_count += 1

    return str(fresh_count)

def main():
    data = sys.stdin.read()
    print(solve(data))

if __name__ == "__main__":
    main()

