import sys

def solve():
    lines = sys.stdin.read().splitlines()
    if not lines:
        return

    R = len(lines)
    C = max(len(s) for s in lines) if lines else 0
    grid = [list(s.ljust(C)) for s in lines]

    # Mark delimiter columns: columns that are spaces in every row
    is_delim = [True] * C
    for j in range(C):
        for i in range(R):
            if grid[i][j] != ' ':
                is_delim[j] = False
                break

    # Build contiguous column intervals for each problem
    intervals = []
    start = None
    for j in range(C):
        if not is_delim[j]:
            if start is None:
                start = j
        else:
            if start is not None:
                intervals.append((start, j - 1))
                start = None
    if start is not None:
        intervals.append((start, C - 1))

    grand_total = 0

    for L, RR in intervals:
        # Extract operation: scan from bottom to top for '+' or '*'
        op = None
        for i in range(R - 1, -1, -1):
            for j in range(L, RR + 1):
                ch = grid[i][j]
                if ch == '+' or ch == '*':
                    op = ch
                    break
            if op is not None:
                break
        if op is None:
            continue

        # Extract numbers: scan each row left-to-right within the interval,
        # tokenizing contiguous digit runs.
        numbers = []
        for i in range(R):
            j = L
            while j <= RR:
                ch = grid[i][j]
                if '0' <= ch <= '9':
                    k = j
                    while k <= RR and ('0' <= grid[i][k] <= '9'):
                        k += 1
                    numbers.append(int(''.join(grid[i][j:k])))
                    j = k
                else:
                    j += 1

        if not numbers:
            continue

        if op == '+':
            ans = sum(numbers)
        else:
            ans = 1
            for x in numbers:
                ans *= x

        grand_total += ans

    sys.stdout.write(str(grand_total))

if __name__ == "__main__":
    solve()

