import sys
from collections import deque

def solve():
    lines = [line.rstrip('\n') for line in sys.stdin]
    # Remove possible empty lines at the end/beginning
    grid = [ln for ln in lines if ln != ""]
    if not grid:
        return

    H = len(grid)
    W = len(grid[0])

    rS = cS = None
    for r in range(H):
        for c in range(W):
            if grid[r][c] == 'S':
                rS, cS = r, c
                break
        if rS is not None:
            break

    # next_split[r][c] = nearest t >= r with grid[t][c] == '^', else -1
    next_split = [[-1] * W for _ in range(H + 1)]
    for c in range(W):
        nxt = -1
        for r in range(H - 1, -1, -1):
            if grid[r][c] == '^':
                nxt = r
            next_split[r][c] = nxt
        next_split[H][c] = -1

    visited_split = [[False] * W for _ in range(H)]
    ans = 0

    # Beam state: (r, c) meaning beam is at row r, next step is to r+1
    q = deque([(rS, cS)])

    while q:
        r, c = q.pop()
        nr = r + 1
        if nr >= H:
            continue

        t = next_split[nr][c]
        if t == -1:
            continue

        # Count this splitter cell only once
        if visited_split[t][c]:
            continue
        visited_split[t][c] = True
        ans += 1

        # Emit new beams from immediate left/right of the splitter
        if c - 1 >= 0:
            q.append((t, c - 1))
        if c + 1 < W:
            q.append((t, c + 1))

    print(ans)

if __name__ == "__main__":
    solve()

