import sys
import re
from math import inf

def parse_machine_line(line: str):
    line = line.strip()
    if not line:
        return None

    # Target diagram
    m = re.search(r'\[([.#]+)\]', line)
    if not m:
        return None
    diagram = m.group(1)
    L = len(diagram)
    target = 0
    for i, ch in enumerate(diagram):
        if ch == '#':
            target |= 1 << i

    # Buttons: all parenthesized groups after the diagram
    # Example: (3) (1,3) (2) ...
    parens = re.findall(r'\(([^)]*)\)', line[m.end():])
    masks = []
    for p in parens:
        p = p.strip()
        if not p:
            masks.append(0)
            continue
        nums = [int(x) for x in p.split(',') if x.strip() != '']
        mask = 0
        for x in nums:
            if 0 <= x < L:
                mask |= 1 << x
        masks.append(mask)

    return target, masks

def min_presses_for_machine(target: int, masks: list[int]) -> int:
    n = len(masks)
    if target == 0:
        return 0

    n1 = n // 2
    n2 = n - n1
    left = masks[:n1]
    right = masks[n1:]

    # Enumerate all subsets of left half, store minimal popcount for each XOR result
    best_left = {}
    for s in range(1 << n1):
        xorv = 0
        cnt = s.bit_count()
        # compute XOR
        # (n1 is small enough for this approach)
        for i in range(n1):
            if (s >> i) & 1:
                xorv ^= left[i]
        prev = best_left.get(xorv)
        if prev is None or cnt < prev:
            best_left[xorv] = cnt

    ans = inf
    # Enumerate all subsets of right half and combine
    for t in range(1 << n2):
        xorv = 0
        cnt = t.bit_count()
        for j in range(n2):
            if (t >> j) & 1:
                xorv ^= right[j]
        need = target ^ xorv
        if need in best_left:
            cand = best_left[need] + cnt
            if cand < ans:
                ans = cand

    return ans if ans != inf else 0

def solve():
    total = 0
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        parsed = parse_machine_line(line)
        if parsed is None:
            continue
        target, masks = parsed
        total += min_presses_for_machine(target, masks)
    sys.stdout.write(str(total) + "\n")

if __name__ == "__main__":
    solve()

