import sys
from typing import Dict, List

def count_paths_to_out(adj: Dict[str, List[str]], start: str = "you", target: str = "out") -> int:
    memo: Dict[str, int] = {}

    sys.setrecursionlimit(1_000_000)

    def dfs(u: str) -> int:
        if u == target:
            return 1
        if u in memo:
            return memo[u]
        neighbors = adj.get(u, [])
