import sys
from functools import lru_cache

def parse_input(data: str):
    lines = [ln.rstrip("\n") for ln in data.splitlines()]

    def is_shape_header(s: str):
        s = s.strip()
        if not s.endswith(":"):
            return False
        left = s[:-1].strip()
        return left.isdigit()

    def is_region_header(s: str):
        s = s.strip()
        if not s.endswith(":"):
            return False
        left = s[:-1].strip()
        if "x" not in left:
            return False
        w, h = left.split("x", 1)
        return w.isdigit() and h.isdigit()

    shapes = []
    regions = []

    i = 0
    n = len(lines)
    while i < n:
        if not lines[i].strip():
            i += 1
            continue

        if is_shape_header(lines[i]):
            i += 1
            coords = []
            r = 0
            while i < n and lines[i].strip() and (not is_shape_header(lines[i])) and (not is_region_header(lines[i])):
                row = lines[i].rstrip()
                for c, ch in enumerate(row):
                    if ch == '#':
                        coords.append((r, c))
                r += 1
                i += 1
            shapes.append(coords)
            continue

        if is_region_header(lines[i]):
            header = lines[i].strip()
            left, right = header[:-1].split(":", 1)
            W_str, H_str = left.split("x", 1)
            W, H = int(W_str), int(H_str)
            right = right.strip()
            counts_in = list(map(int, right.split())) if right else []
            regions.append((W, H, counts_in))
            i += 1
            continue

        i += 1

    return shapes, regions

def normalize(cells):
    minr = min(r for r, c in cells)
    minc = min(c for r, c in cells)
    return tuple(sorted((r - minr, c - minc) for r, c in cells))

def gen_transformations(cells):
    pts = list(set(cells))

    def rot90(p):
        r, c = p
        return (c, -r)

    def reflect(p):
        r, c = p
        return (r, -c)

    seen = set()
    out = []
    for do_ref in (0, 1):
        for k in range(4):
            transformed = []
            for p in pts:
                q = p
                if do_ref:
                    q = reflect(q)
                for _ in range(k):
                    q = rot90(q)
                transformed.append(q)
            norm = normalize(transformed)
            if norm not in seen:
                seen.add(norm)
                out.append(norm)
    return out

def solve_region(W, H, shapes, counts_in):
    n_shapes = len(shapes)

    counts = [0] * n_shapes
    for idx, val in enumerate(counts_in):
        if idx >= n_shapes:
            break
        counts[idx] = val

    total_area = W * H
    shape_areas = [len(shapes[i]) for i in range(n_shapes)]
    required_area = sum(counts[i] * shape_areas[i] for i in range(n_shapes))
    if required_area != total_area:
        return False

    used = [i for i in range(n_shapes) if counts[i] > 0]
    if not used:
        return total_area == 0

    local_counts = [counts[i] for i in used]
    local_shape_area = [shape_areas[i] for i in used]
    L = len(used)

    # Precompute placements for each local shape as bitmasks
    placements_by_shape = [[] for _ in range(L)]
    for j, si in enumerate(used):
        trans = gen_transformations(shapes[si])
        masks = set()

        for t in trans:
            maxr = max(r for r, c in t)
            maxc = max(c for r, c in t)
            th, tw = maxr + 1, maxc + 1
            if th > H or tw > W:
                continue

            for top in range(H - th + 1):
                for left in range(W - tw + 1):
                    mask = 0
                    for r, c in t:
                        rr = top + r
                        cc = left + c
                        bit = rr * W + cc  # consistent with (r,c) -> r*W+c
                        mask |= 1 << bit
                    masks.add(mask)

        placements_by_shape[j] = list(masks)
        if not placements_by_shape[j]:
            return False

    full_mask = (1 << (W * H)) - 1

    # placements_by_cell[cell] = list of (local_shape_index, placement_mask)
    placements_by_cell = [[] for _ in range(W * H)]
    for j in range(L):
        for pmask in placements_by_shape[j]:
            m = pmask
            while m:
                lsb = m & -m
                cell = lsb.bit_length() - 1
                placements_by_cell[cell].append((j, pmask))
                m -= lsb

    init_counts = tuple(local_counts)

    @lru_cache(maxsize=None)
    def dfs(covered_mask, rem_counts):
        if covered_mask == full_mask:
            return True

        uncovered = full_mask ^ covered_mask

        # Necessary area check
        rem_area = 0
        for j in range(L):
            rem_area += rem_counts[j] * local_shape_area[j]
        if rem_area != uncovered.bit_count():
            return False

        # Necessary feasibility: each remaining shape must have at least one placement
        # fully contained in uncovered.
        for j in range(L):
            if rem_counts[j] == 0:
                continue
            ok = False
            for pmask in placements_by_shape[j]:
                if (pmask & uncovered) == pmask:
                    ok = True
                    break
            if not ok:
                return False

        # MRV: choose an uncovered cell with fewest feasible placements
        best_list = None
        best_len = 10**18

        m = uncovered
        while m:
            lsb = m & -m
            cell = lsb.bit_length() - 1
            m -= lsb

            feasible = []
            for j, pmask in placements_by_cell[cell]:
                if rem_counts[j] == 0:
                    continue
                if (pmask & uncovered) == pmask:
                    feasible.append((j, pmask))

            if not feasible:
                return False
            if len(feasible) < best_len:
                best_len = len(feasible)
                best_list = feasible
                if best_len == 1:
                    break

        # Try placements
        for j, pmask in best_list:
            if rem_counts[j] == 0:
                continue
            new_rem = list(rem_counts)
            new_rem[j] -= 1
            if dfs(covered_mask | pmask, tuple(new_rem)):
                return True

        return False

    return dfs(0, init_counts)

def main():
    data = sys.stdin.read()
    shapes, regions = parse_input(data)
    ans = 0
    for W, H, counts in regions:
        if solve_region(W, H, shapes, counts):
            ans += 1
    print(ans)

if __name__ == "__main__":
    main()

