import sys

FORBIDDEN = {'i', 'o', 'l'}

def next_password(pwd: str) -> str:
    # Odometer increment on 8 lowercase letters (base-26)
    arr = [ord(c) - 97 for c in pwd]
    i = 7
    while i >= 0:
        if arr[i] != 25:
            arr[i] += 1
            break
        arr[i] = 0
        i -= 1
    return ''.join(chr(x + 97) for x in arr)

def is_valid(pwd: str) -> bool:
    # 1) Forbidden letters
    for c in pwd:
        if c in FORBIDDEN:
            return False

    # 2) Increasing straight of at least three letters (length-3 window)
    vals = [ord(c) - 97 for c in pwd]
    has_straight = False
    for i in range(6):
        if vals[i + 1] == vals[i] + 1 and vals[i + 2] == vals[i] + 2:
            has_straight = True
            break
    if not has_straight:
        return False

    # 3) At least two different, non-overlapping pairs
    pair_letters = set()
    i = 0
    while i < 7:
        if pwd[i] == pwd[i + 1]:
            pair_letters.add(pwd[i])
            i += 2  # non-overlapping
        else:
            i += 1
    return len(pair_letters) >= 2

def solve(start: str):
    cur = start.strip()

    # Part 1: next valid password
    while True:
        cur = next_password(cur)
        if is_valid(cur):
            ans1 = cur
            break

    # Part 2: next valid password after ans1
    cur = ans1
    while True:
        cur = next_password(cur)
        if is_valid(cur):
            ans2 = cur
            break

    return ans1, ans2

if __name__ == "__main__":
    s = sys.stdin.readline().strip()
    a1, a2 = solve(s)
    print(a1)
    print(a2)

