import sys

def solve():
    # MFCSAM target readings
    target = {
        "children": 3,
        "cats": 7,
        "samoyeds": 2,
        "pomeranians": 3,
        "akitas": 0,
        "vizslas": 0,
        "goldfish": 5,
        "trees": 3,
        "cars": 2,
        "perfumes": 1,
    }

    # Special inequality rules
    greater_than = {"cats", "trees"}
    less_than = {"pomeranians", "goldfish"}

    constraints = {}  # id -> dict(compound -> value)

    # Read all lines until EOF
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue

        # Example: "Sue 1: cars: 9, akitas: 3, goldfish: 0"
        left, right = line.split(":", 1)
        left = left.strip()  # "Sue 1"
        sue_id = int(left.split()[1])

        pairs = right.strip().split(",")
        sue_constraints = {}
        for p in pairs:
            p = p.strip()
            if not p:
                continue
            k, v = p.split(":")
            sue_constraints[k.strip()] = int(v.strip())

        constraints[sue_id] = sue_constraints

    answer = None
    # Iterate over all parsed Aunts
    for sue_id, sue_constraints in constraints.items():
        is_match = True
        for compound, val in sue_constraints.items():
            t = target[compound]
            if compound in greater_than:
                if not (val > t):
                    is_match = False
                    break
            elif compound in less_than:
                if not (val < t):
                    is_match = False
                    break
            else:
                if val != t:
                    is_match = False
                    break
        if is_match:
            answer = sue_id
            break  # unique solution expected

    if answer is not None:
        print(answer)

if __name__ == "__main__":
    solve()

