import sys
import re
from collections import deque

FLOOR_RE = re.compile(r"floor (\d+)", re.IGNORECASE)
ITEM_RE = re.compile(r"a (\w+)(?:-compatible)? (generator|microchip)", re.IGNORECASE)

def parse_input(lines):
    # Floors are 1..4 in input; internally use 0..3
    floors = {1: [], 2: [], 3: [], 4: []}
    for line in lines:
        line = line.strip()
        if not line:
            continue
        m = FLOOR_RE.search(line)
        if not m:
            continue
        f = int(m.group(1))
        floors[f].append(line)

    # Extract items from each floor line
    # Map element type -> (gen_floor, chip_floor) (floors 0..3), fill as we find them
    gen_floor = {}
    chip_floor = {}

    for f in range(1, 5):
        for line in floors.get(f, []):
            # Normalize: "a hydrogen-compatible microchip" / "a hydrogen generator"
            # We'll find all occurrences of "a <type> ... <kind>"
            # Examples:
            # "a hydrogen-compatible microchip"
            # "a lithium generator"
            for m in re.finditer(r"a ([a-z]+)(?:-compatible)? (generator|microchip)", line, re.IGNORECASE):
                typ = m.group(1).lower()
                kind = m.group(2).lower()
                if kind == "generator":
                    gen_floor[typ] = f - 1
                else:
                    chip_floor[typ] = f - 1

    # Ensure consistent ordering of types
    types = sorted(set(gen_floor.keys()) | set(chip_floor.keys()))
    pairs = []
    for t in types:
        # In valid puzzle inputs, both sides exist; but handle missing gracefully
        gf = gen_floor.get(t, -1)
        cf = chip_floor.get(t, -1)
        pairs.append((gf, cf))
    return pairs

def is_safe(e, pairs):
    # e is elevator floor (unused for safety), pairs is list of (gi, ci) with floors 0..3
    # For each floor, if any generator exists, all chips on that floor must have their generator there.
    for f in range(4):
        has_gen = False
        for gi, ci in pairs:
            if gi == f:
                has_gen = True
                break
        if not has_gen:
            continue
        for gi, ci in pairs:
            if ci == f and gi != f:
                return False
    return True

def canonical_key(e, pairs):
    # Sort pairs to remove element identity symmetry
    # Key: (e, sorted_pairs)
    sp = tuple(sorted(pairs))
    return (e, sp)

def neighbors(e, pairs):
    # Generate all safe neighbor states from current state
    # Move 1 or 2 items from elevator floor e to e2 (e +/- 1)
    avail = []
    for idx, (gi, ci) in enumerate(pairs):
        if gi == e:
            avail.append(("g", idx))
        if ci == e:
            avail.append(("c", idx))

    if not avail:
        return []

    res = []
    for d in (-1, 1):
        e2 = e + d
        if e2 < 0 or e2 > 3:
            continue

        # Choose 1 item
        for i in range(len(avail)):
            kind1, idx1 = avail[i]
            new_pairs = list(pairs)
            gi, ci = new_pairs[idx1]
            if kind1 == "g":
                new_pairs[idx1] = (e2, ci)
            else:
                new_pairs[idx1] = (gi, e2)
            if is_safe(e2, new_pairs):
                res.append((e2, new_pairs))
        # Choose 2 items (combinations)
        for i in range(len(avail)):
            for j in range(i + 1, len(avail)):
                kind1, idx1 = avail[i]
                kind2, idx2 = avail[j]
                new_pairs = list(pairs)
                gi1, ci1 = new_pairs[idx1]
                gi2, ci2 = new_pairs[idx2]

                if kind1 == "g":
                    new_pairs[idx1] = (e2, ci1)
                else:
                    new_pairs[idx1] = (gi1, e2)

                if kind2 == "g":
                    new_pairs[idx2] = (e2, ci2)
                else:
                    new_pairs[idx2] = (gi2, e2)

                if is_safe(e2, new_pairs):
                    res.append((e2, new_pairs))
    return res

def bfs_min_steps(initial_pairs):
    # Elevator starts on floor 0 (floor 1 in input)
    start_e = 0
    # Validate initial safety
    if not is_safe(start_e, initial_pairs):
        return None

    start_key = canonical_key(start_e, initial_pairs)
    q = deque([(start_e, initial_pairs, 0)])
    visited = {start_key}

    while q:
        e, pairs, dist = q.popleft()

        # Goal: all items on floor 3
        if all(gi == 3 and ci == 3 for gi, ci in pairs):
            return dist

        for e2, npairs in neighbors(e, pairs):
            key = canonical_key(e2, npairs)
            if key not in visited:
                visited.add(key)
                q.append((e2, npairs, dist + 1))
    return None

def solve(lines):
    base_pairs = parse_input(lines)

    part1 = bfs_min_steps(base_pairs)

    # Part 2: add elerium and dilithium (both generator and microchip) on floor 1 (internal 0)
    # Add two new types: (gen_floor=0, chip_floor=0) each
    pairs2 = list(base_pairs)
    pairs2.append((0, 0))  # elerium
    pairs2.append((0, 0))  # dilithium
    part2 = bfs_min_steps(pairs2)

    return part1, part2

def main():
    lines = sys.stdin.read().splitlines()
    p1, p2 = solve(lines)
    # Output format: two lines (common AoC style)
    print(p1)
    print(p2)

if __name__ == "__main__":
    main()

