import sys

def parse_pattern(s: str):
    # "a/b/c" -> list of list of chars
    return [list(row) for row in s.strip().split('/')]

def pattern_to_key(mat):
    # list[list[str]] -> "a/b/c"
    return '/'.join(''.join(row) for row in mat)

def rotate90(mat):
    # rotate clockwise
    n = len(mat)
    return [[mat[n - 1 - j][i] for j in range(n)] for i in range(n)]

def flip_horizontal(mat):
    # mirror left-right
    n = len(mat)
    return [list(reversed(row)) for row in mat]

def canonical_key(mat):
    # Generate all 8 variants (4 rotations * optional horizontal flip)
    variants = []
    cur = mat
    for _ in range(4):
        variants.append(pattern_to_key(cur))
        variants.append(pattern_to_key(flip_horizontal(cur)))
        cur = rotate90(cur)
    return min(variants)

def enhance(grid, rules, iterations):
    # grid: list[list[str]]
    for _ in range(iterations):
        n = len(grid)
        if n % 2 == 0:
            block_size, out_size = 2, 3
        else:
            block_size, out_size = 3, 4

        k = n // block_size
        new_n = k * out_size
        new_grid = [['.' for _ in range(new_n)] for _ in range(new_n)]

        for br in range(k):
            for bc in range(k):
                block = [row[bc * block_size:(bc + 1) * block_size] for row in grid[br * block_size:(br + 1) * block_size]]
                key = canonical_key(block)
                out_block = rules[key]  # list[list[str]]

                for i in range(out_size):
                    for j in range(out_size):
                        new_grid[br * out_size + i][bc * out_size + j] = out_block[i][j]

        grid = new_grid
    return grid

def main():
    rules = {}
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        left, right = line.split(" => ")
        in_pat = parse_pattern(left)
        out_pat = parse_pattern(right)
        rules[canonical_key(in_pat)] = out_pat

    # Starting grid
    grid = parse_pattern(".#./..#/###")

    # Part Two: 18 iterations
    grid = enhance(grid, rules, 18)

    ans = sum(cell == '#' for row in grid for cell in row)
    print(ans)

if __name__ == "__main__":
    main()

