    prog = parse_program(lines)

    part1 = run_part1(prog)

    # Part 2: set a=1 and compute h.
    # For this puzzle variant, h counts number of divisors of N.
    N = run_until_divisor_constant(prog, a_value=1)
    part2 = divisor_count(N)

    sys.stdout.write(f"{part1}\n{part2}\n")

if __name__ == "__main__":
    main()

