import sys

def parse_input(lines):
    initial_state = None
    rules = [False] * 32

    for line in lines:
        line = line.strip()
        if not line:
            continue
        if line.startswith("initial state:"):
            s = line.split(":")[1].strip()
            plants = set()
            for i, ch in enumerate(s):
                if ch == '#':
                    plants.add(i)  # index 0 corresponds to pot 0
            initial_state = plants
        else:
            if "=>" in line:
                pat, out = line.split("=>")
                pat = pat.strip()
                out = out.strip()
                if out == '#':
                    # Encode pattern into 5-bit key:
                    # bit0: p-2, bit1: p-1, bit2: p, bit3: p+1, bit4: p+2
                    key = 0
                    for i, ch in enumerate(pat):
                        if ch == '#':
                            key |= (1 << i)
                    rules[key] = True

    return initial_state if initial_state is not None else set(), rules

def step(state, rules):
    if not state:
        return set()

    minP = min(state)
    maxP = max(state)
    next_state = set()

    # Candidate pots that could possibly become plants
    for p in range(minP - 2, maxP + 3):
        key = 0
        if (p - 2) in state: key |= 1 << 0
        if (p - 1) in state: key |= 1 << 1
        if p in state: key |= 1 << 2
        if (p + 1) in state: key |= 1 << 3
        if (p + 2) in state: key |= 1 << 4
        if rules[key]:
            next_state.add(p)

    return next_state

def signature(state):
    if not state:
        return ()
    m = min(state)
    return tuple(sorted(p - m for p in state))

def solve(plants, rules):
    # Part 1
    state = set(plants)
    for _ in range(20):
        state = step(state, rules)
    part1 = sum(state)

    # Part 2 with stabilization detection (translation-invariant)
    target = 50_000_000_000
    state = set(plants)

    seen = {}  # sig -> (gen, minP, sum, state_size)
    gen = 0
    while gen < target:
        if not state:
            part2 = 0
            break

        sig = signature(state)
        minP = min(state)
        ssum = sum(state)
        size = len(state)

        if sig in seen:
            prev_gen, prev_minP, prev_ssum, prev_size = seen[sig]
            # If shape repeats, it should translate by constant delta each generation.
            # Compute delta in minP per generation.
            delta_min = minP - prev_minP
            delta_gen = gen - prev_gen
            if delta_gen != 0:
                # After delta_gen generations, minP shifted by delta_min.
                # So per generation shift is delta_min / delta_gen (should be integer).
                if delta_min % delta_gen == 0:
                    per_gen_shift = delta_min // delta_gen
                    remaining = target - gen
                    shift_total = remaining * per_gen_shift
                    # Sum shifts by shift_total * number_of_plants (shape size constant)
                    part2 = ssum + shift_total * size
                    break
        else:
            seen[sig] = (gen, minP, ssum, size)

        state = step(state, rules)
        gen += 1
    else:
        # If loop ended exactly at target
        part2 = sum(state) if state else 0

    return part1, part2

def main():
    lines = sys.stdin.read().splitlines()
    plants, rules = parse_input(lines)
    p1, p2 = solve(plants, rules)
    sys.stdout.write(f"{p1}\n{p2}\n")

if __name__ == "__main__":
    main()

