def solve(lines):
    clay, min_y, max_y = parse_input(lines)

    # state: '|' flowing, '~' settled
    state = {}

    def is_clay(x, y):
        return (x, y) in clay

    def is_blocked(x, y):
        # blocked for water movement if clay or settled water
        return is_clay(x, y) or state.get((x, y)) == '~'

    # Stack-based simulation: process a falling/spreading "source" at (x,y)
    stack = [(500, 0)]

    while stack:
        x, y = stack.pop()

        # Descend as far as possible
        while True:
            if y > max_y:
                break
            if is_clay(x, y):
                break
            # Mark flowing while descending
            if state.get((x, y)) != '~':
                state[(x, y)] = '|'

            if y == max_y:
                break

            if not is_blocked(x, y + 1):
                y += 1
                continue
            # Below is blocked; spread on this row
            row = y
            break
        else:
            continue

        if y > max_y or is_clay(x, y):
            continue

        # If we broke because below is not blocked, we already handled by descending.
        # We only spread when below is blocked.
        if y <= max_y and is_blocked(x, y + 1):
            row = y

            # Find left boundary
            xl = x
            left_leak = False
            while True:
                if is_clay(xl, row):
                    break
                # Tentatively mark flowing
                if state.get((xl, row)) != '~':
                    state[(xl, row)] = '|'
                # If below is not blocked, water leaks
                if row + 1 > max_y:
                    left_leak = True
                    break
                if not is_blocked(xl, row + 1):
                    left_leak = True
                    break
                xl -= 1

            # Find right boundary
            xr = x
            right_leak = False
            while True:
                if is_clay(xr, row):
                    break
                if state.get((xr, row)) != '~':
                    state[(xr, row)] = '|'
                if row + 1 > max_y:
                    right_leak = True
                    break
                if not is_blocked(xr, row + 1):
                    right_leak = True
                    break
                xr += 1

            # Determine if bounded by clay on both sides
            left_bounded = not left_leak and is_clay(xl, row)
            right_bounded = not right_leak and is_clay(xr, row)

            if left_bounded and right_bounded:
                # Settle between walls (exclusive of clay walls)
                for xx in range(xl + 1, xr):
                    state[(xx, row)] = '~'
                # After settling, try to spread upward from the cell above
                stack.append((x, row - 1))
            else:
                # Keep flowing; ensure leaking sides continue downward
                # Left leak position is xl (where below is open) or xl+1 depending on loop break.
                if left_leak:
                    # Find the first position from x going left where below is open (not blocked)
                    # We can use xl as current position where either clay or open below caused break.
                    # If xl is clay, leak must have been due to open below at xl+1; handle robustly.
                    leak_x = xl
                    if is_clay(leak_x, row):
                        leak_x = xl + 1
                    stack.append((leak_x, row))
                if right_leak:
                    leak_x = xr
                    if is_clay(leak_x, row):
                        leak_x = xr - 1
                    stack.append((leak_x, row))

    # Part Two: count settled water within scan y-range
    ans = 0
    for (x, y), v in state.items():
        if v == '~' and min_y <= y <= max_y:
            ans += 1
    return ans

def main():
    lines = sys.stdin.read().splitlines()
    result = solve(lines)
    print(result)

if __name__ == "__main__":
    main()

