import sys
from collections import defaultdict, deque

def solve():
    program_line = sys.stdin.readline().strip()
    if not program_line:
        return
    base_prog = list(map(int, program_line.split(',')))

    class IntcodeComputer:
        def __init__(self, program):
            self.mem = defaultdict(int)
            for i, v in enumerate(program):
                self.mem[i] = v
            self.ip = 0
            self.rb = 0
            self.halted = False

        def _get(self, addr):
            return self.mem[addr]

        def _set(self, addr, val):
            self.mem[addr] = val

        def _param_value(self, offset, mode):
            if mode == 0:  # position
                return self._get(self._get(self.ip + offset))
            if mode == 1:  # immediate
                return self._get(self.ip + offset)
            if mode == 2:  # relative
                return self._get(self.rb + self._get(self.ip + offset))
            raise ValueError("Unknown parameter mode")

        def _param_target(self, offset, mode):
            if mode == 0:  # position
                return self._get(self.ip + offset)
            if mode == 2:  # relative
                return self.rb + self._get(self.ip + offset)
            # mode 1 is invalid for write targets in Intcode
            raise ValueError("Invalid mode for write target")

        def run(self, input_func=None, output_func=None):
            """
            Runs until halt.
            - input_func: callable returning next input value when opcode 3 is hit.
            - output_func: callable taking output value when opcode 4 is hit.
            """
            while True:
                instr = self._get(self.ip)
                op = instr % 100
                modes = [(instr // 100) % 10, (instr // 1000) % 10, (instr // 10000) % 10]

                if op == 99:
                    self.halted = True
                    return

                if op in (1, 2, 7, 8):
                    a = self._param_value(1, modes[0])
                    b = self._param_value(2, modes[1])
                    t = self._param_target(3, modes[2])
                    if op == 1:
                        self._set(t, a + b)
                    elif op == 2:
                        self._set(t, a * b)
                    elif op == 7:
                        self._set(t, 1 if a < b else 0)
                    else:  # op == 8
                        self._set(t, 1 if a == b else 0)
                    self.ip += 4

                elif op == 3:
                    if input_func is None:
                        raise RuntimeError("Input requested but no input_func provided")
                    t = self._param_target(1, modes[0])
                    self._set(t, input_func())
                    self.ip += 2

                elif op == 4:
                    v = self._param_value(1, modes[0])
                    if output_func is not None:
                        output_func(v)
                    self.ip += 2

                elif op in (5, 6):
                    a = self._param_value(1, modes[0])
                    b = self._param_value(2, modes[1])
                    cond = (a != 0) if op == 5 else (a == 0)
                    self.ip = b if cond else self.ip + 3

                elif op == 9:
                    a = self._param_value(1, modes[0])
                    self.rb += a
                    self.ip += 2

                else:
                    raise ValueError(f"Unknown opcode: {op}")

    def part_one():
        comp = IntcodeComputer(base_prog)

        triple = []
        block_count = 0

        def on_output(v):
            nonlocal block_count
            triple.append(v)
            if len(triple) == 3:
                x, y, tile_id = triple
                if tile_id == 2:
                    block_count += 1
                triple.clear()

        comp.run(input_func=lambda: 0, output_func=on_output)
        return block_count

    def part_two():
        prog2 = base_prog[:]
        prog2[0] = 2
        comp = IntcodeComputer(prog2)

        triple = []
        paddle_x = 0
        ball_x = 0
        score = 0

        def on_output(v):
            nonlocal paddle_x, ball_x, score
            triple.append(v)
            if len(triple) == 3:
                x, y, tile_id = triple
                if x == -1 and y == 0:
                    score = tile_id
                else:
                    if tile_id == 3:
                        paddle_x = x
                    elif tile_id == 4:
                        ball_x = x
                triple.clear()

        def input_func():
            if ball_x < paddle_x:
                return -1
            if ball_x > paddle_x:
                return 1
            return 0

        comp.run(input_func=input_func, output_func=on_output)
        return score

    ans1 = part_one()
    ans2 = part_two()
    sys.stdout.write(f"{ans1}\n{ans2}\n")

if __name__ == "__main__":
    solve()

