            elif opcode in (1, 2, 7, 8):
                a = read_param(modes[0], 1)
                b = read_param(modes[1], 2)
                if opcode == 1:
                    res = a + b
                elif opcode == 2:
                    res = a * b
                elif opcode == 7:
                    res = 1 if a < b else 0
                else:  # opcode == 8
                    res = 1 if a == b else 0
                write_param(modes[2], 3, res)
                self.ip += 4
            elif opcode == 3:
                if not inp:
                    raise RuntimeError("Input required but none available")
                write_param(modes[0], 1, inp.popleft())
                self.ip += 2
            elif opcode == 4:
                a = read_param(modes[0], 1)
                out.append(a)
                self.ip += 2
            elif opcode in (5, 6):
                a = read_param(modes[0], 1)
                b = read_param(modes[1], 2)
