            if op == "NOT":
                env[y] = (not xv)
            elif op == "AND":
                env[y] = env[y] and xv  # wrong: AND X Y sets Y based on X and Y, not Y and X? Actually: Y = X and Y
                # But we need correct semantics: AND X Y sets Y to true if both X and Y are true.
                # That is: Y = (X and Y_old). So we must use old Y.
                # We'll implement properly below by redoing with old value.
            else:
                raise ValueError("Unexpected op")

        # The above is incorrect; implement properly with correct semantics:
        env = {"A": A, "B": B, "C": C, "D": D, "T": False, "J": False}
        for op, x, y in prog:
            if op == "NOT":
                env[y] = (not env[x])
            elif op == "AND":
                env[y] = (env[x] and env[y])
            elif op == "OR":
                env[y] = (env[x] or env[y])
            else:
                raise ValueError("Unknown op")
        return env["J"]

    for A in (False, True):
        for B in (False, True):
            for C in (False, True):
                for D in (False, True):
                    expected = (not A) and (B or C) and D
                    actual = eval_prog(A, B, C, D)
                    if actual != expected:
                        return False
    return True

