import sys
import re

def solve(data: str):
    lines = [line.strip() for line in data.splitlines()]
    # Split into sections by blank lines
    sections = []
    cur = []
    for line in lines:
        if line == "":
            if cur:
                sections.append(cur)
                cur = []
        else:
            cur.append(line)
    if cur:
        sections.append(cur)

    rules_lines = sections[0]
    my_ticket_line = sections[1][1]  # sections[1] like ["your ticket:", "x,y,z"]
    nearby_lines = sections[2][1:]   # sections[2] like ["nearby tickets:", "a,b,c", ...]

    rules = {}  # name -> (a,b,c,d)
    field_names = []
    rule_re = re.compile(r"^([^:]+): (\d+)-(\d+) or (\d+)-(\d+)$")

    for rl in rules_lines:
        m = rule_re.match(rl)
        if not m:
            continue
        name = m.group(1)
        a, b, c, d = map(int, m.group(2, 3, 4, 5))
        rules[name] = (a, b, c, d)
        field_names.append(name)

    my_ticket = list(map(int, my_ticket_line.split(",")))
    n = len(my_ticket)

    nearby_tickets = [list(map(int, ln.split(","))) for ln in nearby_lines if ln]

    def valid_for_field(x, field):
        a, b, c, d = rules[field]
        return (a <= x <= b) or (c <= x <= d)

    def valid_for_any_field(x):
        for f in field_names:
            if valid_for_field(x, f):
                return True
        return False

    # Part 1: scanning error rate + collect valid tickets
    error_rate = 0
    valid_tickets = []
    for t in nearby_tickets:
        ticket_valid = True
        for x in t:
            if not valid_for_any_field(x):
                error_rate += x
                ticket_valid = False
        if ticket_valid:
            valid_tickets.append(t)

    # Part 2: determine field positions
    candidates = [set(field_names) for _ in range(n)]
    for col in range(n):
        for f in list(candidates[col]):
            ok = True
            for t in valid_tickets:
                if not valid_for_field(t[col], f):
                    ok = False
                    break
            if not ok:
                candidates[col].remove(f)

    assigned = [None] * n
    used = set()

    # Iterative singleton propagation
    while True:
        progress = False
        for col in range(n):
            if assigned[col] is not None:
                continue
            # Remove already used fields from consideration
            candidates[col] -= used
            if len(candidates[col]) == 1:
                f = next(iter(candidates[col]))
                assigned[col] = f
                used.add(f)
                progress = True
        if all(a is not None for a in assigned):
            break
        if not progress:
            # Should not happen for valid AoC inputs
            break

    product = 1
    for col, f in enumerate(assigned):
        if f is not None and f.startswith("departure"):
            product *= my_ticket[col]

    return error_rate, product

def main():
    data = sys.stdin.read()
    part1, part2 = solve(data)
    print(part1)
    print(part2)

if __name__ == "__main__":
    main()

