import sys

def decode_entry(patterns, outputs):
    pats = [frozenset(p) for p in patterns]
    outs = [frozenset(o) for o in outputs]

    by_len = {}
    for s in pats:
        by_len.setdefault(len(s), []).append(s)

    one = by_len[2][0]
    four = by_len[4][0]
    seven = by_len[3][0]
    eight = by_len[7][0]

    digit_to_set = {1: one, 4: four, 7: seven, 8: eight}

    # length 6 => 0,6,9
    for s in by_len[6]:
        if four.issubset(s):
            digit_to_set[9] = s
        elif one.issubset(s):
            digit_to_set[0] = s
        else:
            digit_to_set[6] = s

    # length 5 => 2,3,5
    for s in by_len[5]:
        if one.issubset(s):
            digit_to_set[3] = s
        elif s.issubset(digit_to_set[6]):
            digit_to_set[5] = s
        else:
            digit_to_set[2] = s

    set_to_digit = {v: k for k, v in digit_to_set.items()}

    value = 0
    for o in outs:
        value = value * 10 + set_to_digit[o]
    return value

def solve():
    tokens = sys.stdin.read().strip().split()
    if not tokens:
        return

    i = 0
    total = 0

    while i < len(tokens):
        patterns = []
        while i < len(tokens) and tokens[i] != '|':
            patterns.append(tokens[i])
            i += 1
        if i >= len(tokens) or tokens[i] != '|':
            break
        if len(patterns) != 10:
            # malformed input; stop
            break

        i += 1  # skip '|'

        if i + 4 > len(tokens):
            break
        outputs = tokens[i:i+4]
        i += 4

        total += decode_entry(patterns, outputs)

    print(total)

if __name__ == "__main__":
    solve()

