import sys

def solve(data: str) -> str:
    lines = data.splitlines()

    dots = set()
    folds = []

    parsing_dots = True
    for line in lines:
        line = line.strip()
        if not line:
            parsing_dots = False
            continue
        if parsing_dots:
            x_str, y_str = line.split(",")
            dots.add((int(x_str), int(y_str)))
        else:
            # line like: "fold along y=7"
            expr = line[len("fold along "):]
            axis, k_str = expr.split("=")
            folds.append((axis, int(k_str)))

    def apply_fold(points, axis, k):
        new_points = set()
        if axis == "y":
            for x, y in points:
                if y > k:
                    y2 = k - (y - k)
                    new_points.add((x, y2))
                else:
                    new_points.add((x, y))
        else:  # axis == "x"
            for x, y in points:
                if x > k:
                    x2 = k - (x - k)
                    new_points.add((x2, y))
                else:
                    new_points.add((x, y))
        return new_points

    for axis, k in folds:
        dots = apply_fold(dots, axis, k)

    if not dots:
        return ""

    max_x = max(x for x, _ in dots)
    max_y = max(y for _, y in dots)

    out_lines = []
    for y in range(max_y + 1):
        row = []
        for x in range(max_x + 1):
            row.append("#" if (x, y) in dots else ".")
        out_lines.append("".join(row))

    return "\n".join(out_lines)

if __name__ == "__main__":
    data = sys.stdin.read()
    sys.stdout.write(solve(data))

