            amph_rows.append(rr)

    depth = len(amph_rows)
    if depth == 0:
        raise ValueError("No amphipods found (could not detect room amphipod rows).")

    n = 7 + 4 * depth

    def room_base(room):
        return 7 + room * depth

    start = [-1] * n

    # Hallway amphipods (usually empty). Detect by scanning fixed hallway stop columns.
    for hi, x in enumerate(HALL_X):
        for rr in range(R):
            ch = grid[rr][x]
            if ch in TYPE_IDX:
                start[hi] = TYPE_IDX[ch]
                break

    # Rooms: amph_rows are top->bottom
    for d, rr in enumerate(amph_rows):
        for room in range(4):
            x = ROOM_X[room]
            ch = grid[rr][x]
            if ch in TYPE_IDX:
                start[room_base(room) + d] = TYPE_IDX[ch]

    return tuple(start), depth

def solve():
    raw_lines = [ln.rstrip("\n") for ln in sys.stdin if ln.strip("\n") != ""]
    if not raw_lines:
        return

    # Detect depth to decide part2 expansion
    _, depth0 = parse_state(raw_lines)
    if depth0 == 2:
        raw_lines = expand_part2(raw_lines)

    start, depth = parse_state(raw_lines)
    n = 7 + 4 * depth

    def room_base(room):
        return 7 + room * depth

    # Goal: room r contains type r in all slots
    goal = [-1] * n
    for r in range(4):
        for d in range(depth):
            goal[room_base(r) + d] = r
    goal = tuple(goal)

    # Precompute horizontal distances and blocking masks for hallway paths.
    HORIZ_HALL_TO_ROOM = [[abs(HALL_X[hi] - ROOM_X[r]) for r in range(4)] for hi in range(7)]

    def between_hall_indices(x1, x2):
        lo, hi = (x1, x2) if x1 < x2 else (x2, x1)
        res = []
        for i, x in enumerate(HALL_X):
            if lo < x < hi:
                res.append(i)
        return res

    # BLOCK_HALL_BETWEEN[hi][room] is a bitmask of hallway stops that must be empty
    # when moving from hallway stop hi to the room entrance of 'room'.
    BLOCK_HALL_BETWEEN = [[0] * 4 for _ in range(7)]
    for hi in range(7):
        for r in range(4):
            mask = 0
            for j in between_hall_indices(HALL_X[hi], ROOM_X[r]):
                mask |= (1 << j)
            BLOCK_HALL_BETWEEN[hi][r] = mask

    def room_can_accept(s, room, t):
        base = room_base(room)
        for d in range(depth):
            v = s[base + d]
            if v != -1 and v != t:
                return False
        return True

    def room_deepest_empty(s, room):
        base = room_base(room)
        for d in range(depth - 1, -1, -1):
            if s[base + d] == -1:
                return d
        return -1

    def room_is_settled(s, room):
        base = room_base(room)
        for d in range(depth):
            if s[base + d] != room:
                return False
        return True

    def topmost_in_room(s, room):
        base = room_base(room)
        for d in range(depth):
            v = s[base + d]
            if v != -1:
                return d, v
        return None, None

    def generate_moves(s):
        hall_mask = 0
        for hi in range(7):
            if s[hi] != -1:
                hall_mask |= (1 << hi)

        # Hallway -> Room
        for hi in range(7):
            t = s[hi]
            if t == -1:
                continue
            room = t
            if not room_can_accept(s, room, t):
                continue
            d_to = room_deepest_empty(s, room)
            if d_to == -1:
                continue
            if hall_mask & BLOCK_HALL_BETWEEN[hi][room]:
                continue

            # steps: from hallway stop down into room slot
            # vertical steps = d_to + 1 (top slot is 1 step down)
            steps = (d_to + 1) + HORIZ_HALL_TO_ROOM[hi][room]
            cost = steps * ENERGY[t]

            ns = list(s)
            ns[hi] = -1
            ns[room_base(room) + d_to] = t
            yield tuple(ns), cost

        # Room -> Hallway
        for room in range(4):
            if room_is_settled(s, room):
                continue
            d_from, t = topmost_in_room(s, room)
            if d_from is None:
                continue

            base = room_base(room)
            vert = d_from + 1  # steps to exit room to hallway level

            for hi in range(7):
                if s[hi] != -1:
                    continue
                if hall_mask & BLOCK_HALL_BETWEEN[hi][room]:
                    continue

                steps = vert + HORIZ_HALL_TO_ROOM[hi][room]
                cost = steps * ENERGY[t]

                ns = list(s)
                ns[base + d_from] = -1
                ns[hi] = t
                yield tuple(ns), cost

    # Dijkstra
    pq = [(0, start)]
    dist = {start: 0}

    while pq:
        dcur, s = heapq.heappop(pq)
        if dcur != dist.get(s):
            continue
        if s == goal:
            print(dcur)
            return
        for ns, cost in generate_moves(s):
            nd = dcur + cost
            if nd < dist.get(ns, 10**30):
                dist[ns] = nd
                heapq.heappush(pq, (nd, ns))

    print(-1)

if __name__ == "__main__":
    solve()

