import sys
from collections import deque

def solve(data: str) -> str:
    lines = [line.strip() for line in data.strip().splitlines() if line.strip()]
    if not lines:
        return "0"

    adj = {}
    flow_rate = {}

    for line in lines:
        # Example:
        # Valve AA has flow rate=0; tunnels lead to valves DD, II, BB
        # Valve HH has flow rate=22; tunnel leads to valve GG
        left, right = line.split(";")
        parts = left.split()
        name = parts[1]
        rate = int(parts[-1].split("=")[1])
        flow_rate[name] = rate

        right = right.strip()
        right = right.replace("tunnels lead to valves", "tunnels lead to valves")
        right = right.replace("tunnel leads to valve", "tunnels lead to valves")
        # Now right should contain: "tunnels lead to valves X, Y, Z" or similar
        if "tunnels lead to valves" in right:
            neigh = right.split("tunnels lead to valves", 1)[1].strip()
        else:
            # Fallback (shouldn't happen)
            neigh = right.split("valves", 1)[1].strip()
        neighbors = [x.strip() for x in neigh.split(",")]
        adj[name] = neighbors

    # Useful valves: positive flow
    pos = [v for v, r in flow_rate.items() if r > 0]
    m = len(pos)
    if m == 0:
        return "0"

    idx = {v: i for i, v in enumerate(pos)}
    flow = [flow_rate[v] for v in pos]

    # Precompute shortest distances between relevant nodes using BFS
    # Relevant sources: AA and each positive valve
    sources = ["AA"] + pos
    dist = {s: {} for s in sources}

    for s in sources:
        q = deque([s])
        d = {s: 0}
        while q:
            u = q.popleft()
            for w in adj.get(u, []):
                if w not in d:
                    d[w] = d[u] + 1
                    q.append(w)
        dist[s] = d

    # Distances from AA to each useful valve
    dist_from_start = [dist["AA"].get(v, 10**9) for v in pos]

    # Distances between useful valves
    dist_between = [[0] * m for _ in range(m)]
    for i in range(m):
        vi = pos[i]
        for j in range(m):
            if i == j:
                dist_between[i][j] = 0
            else:
                dist_between[i][j] = dist[vi].get(pos[j], 10**9)

    T = 26  # Part 2: 4 minutes teaching, 26 minutes to execute

    all_mask = (1 << m) - 1

    # DP for one agent:
    # dp[mask][i] = max pressure achievable when opened exactly mask and currently at valve i (i in mask)
    # time_used[mask][i] = time spent to reach that state (for tie-breaking)
    # We'll store as dict-like arrays for memory efficiency: dp[mask] is list length m with -inf.
    neg_inf = -10**18
    dp = [[neg_inf] * m for _ in range(1 << m)]
    time_used = [[10**9] * m for _ in range(1 << m)]

    # Initialize from start AA
    for i in range(m):
        t_open = dist_from_start[i] + 1  # move + open
        if t_open <= T:
            mask = 1 << i
            pressure = flow[i] * (T - t_open)
            dp[mask][i] = pressure
            time_used[mask][i] = t_open

    # Transitions
    for mask in range(1 << m):
        # quick skip if no states
        # We'll check any i in mask has dp != neg_inf
        if mask == 0:
            continue
        for i in range(m):
            if not (mask & (1 << i)):
                continue
            curp = dp[mask][i]
            if curp == neg_inf:
                continue
            curt = time_used[mask][i]
            # Try opening new valve j
            for j in range(m):
                if mask & (1 << j):
                    continue
                d = dist_between[i][j]
                if d >= 10**9:
                    continue
                cost = d + 1
                nt = curt + cost
                if nt > T:
                    continue
                nmask = mask | (1 << j)
                add = flow[j] * (T - nt)
                np = curp + add
                if np > dp[nmask][j] or (np == dp[nmask][j] and nt < time_used[nmask][j]):
                    dp[nmask][j] = np
                    time_used[nmask][j] = nt

    # best[mask] = max pressure achievable by one agent opening exactly mask (any ending valve)
    best = [0] * (1 << m)
    for mask in range(1 << m):
        best_val = 0
        for i in range(m):
            if mask & (1 << i):
                if dp[mask][i] > best_val:
                    best_val = dp[mask][i]
        best[mask] = best_val

    # Split between you and elephant: disjoint subsets
    ans = 0
    # Iterate all masks; duplicates are fine but we can halve by fixing one bit
    # We'll just iterate all for simplicity.
    for mask in range(1 << m):
        other = all_mask ^ mask
        total = best[mask] + best[other]
        if total > ans:
            ans = total

    return str(ans)

def main():
    data = sys.stdin.read()
    sys.stdout.write(solve(data))

if __name__ == "__main__":
    main()

