import sys
from typing import List, Optional

def is_safe(seq: List[int]) -> bool:
    n = len(seq)
    if n <= 2:
        return True

    if seq[0] == seq[1]:
        return False

    inc = seq[1] > seq[0]
    for i in range(n - 1):
        diff = seq[i + 1] - seq[i]
        if inc:
            if not (1 <= diff <= 3):
                return False
        else:
            if not (-3 <= diff <= -1):
                return False
    return True

def safe_with_one_removal_direction(seq: List[int], inc: bool) -> bool:
    """
    Can we make seq valid for a fixed direction (inc=True => increasing)
    by removing at most one element?
    """
    n = len(seq)
    if n <= 2:
        return True

    def ok(diff: int) -> bool:
        if inc:
            return 1 <= diff <= 3
        else:
            return -3 <= diff <= -1

    # dp0_last: latest possible last kept index with 0 deletions used
    # dp1_last: latest possible last kept index with 1 deletion used
    dp0_last: Optional[int] = 0
    dp1_last: Optional[int] = None

    for i in range(1, n):
        new_dp0: Optional[int] = None
        new_dp1: Optional[int] = None

        # Option 1: keep seq[i]
        if dp0_last is not None and ok(seq[i] - seq[dp0_last]):
            new_dp0 = i

        if dp1_last is not None and ok(seq[i] - seq[dp1_last]):
            new_dp1 = i

        # Option 2: delete seq[i]
        # If we delete current element, last kept index stays the same.
        if dp0_last is not None:
            # use deletion now
            new_dp1 = dp0_last if new_dp1 is None else max(new_dp1, dp0_last)

        if dp1_last is not None:
            # already used deletion; deleting again is not allowed,
            # but since we are only allowed to remove at most one element,
            # we must NOT allow this transition.
            # Therefore: do nothing here.

            pass

        # If we kept into dp0, dp1 might also be possible via other paths;
        # but our transitions already cover all valid ways with at most one deletion.
        dp0_last, dp1_last = new_dp0, new_dp1

        if dp0_last is None and dp1_last is None:
            return False

    return dp0_last is not None or dp1_last is not None

def safe_with_one_removal(seq: List[int]) -> bool:
    if is_safe(seq):
        return True
    return (safe_with_one_removal_direction(seq, True) or
            safe_with_one_removal_direction(seq, False))

def main():
    ans = 0
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        seq = list(map(int, line.split()))
        if safe_with_one_removal(seq):
            ans += 1
    print(ans)

if __name__ == "__main__":
    main()

