    visited_cells = set()
    r, c, d = sr, sc, sdir
    visited_cells.add((r, c))
    while True:
        nxt = step(r, c, d, extra_block=None)
        if nxt is None:
            break
        r, c, d = nxt
        visited_cells.add((r, c))

    # Part 2: for each candidate cell (except start), test if it causes a loop
    ans = 0
    for br, bc in visited_cells:
        if br == sr and bc == sc:
            continue

        seen = [[[False] * 4 for _ in range(C)] for __ in range(R)]
        r, c, d = sr, sc, sdir
        while True:
            if seen[r][c][d]:
                ans += 1
                break
            seen[r][c][d] = True

            nxt = step(r, c, d, extra_block=(br, bc))
            if nxt is None:
                break
            r, c, d = nxt

    return str(ans)

def main():
    data = sys.stdin.read()
    sys.stdout.write(solve(data))

if __name__ == "__main__":
    main()

